INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1,'7b551c65c3e39acb58b1','WellbeingCounties','RFP','OPEN','Tästä pääset Hilmaan. ( ulkoinen linkki )','Päivitetty 26.5.2026.','Western Uusimaa wellbeing county','ANY',3,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/',NULL,'[\"tästä\", \"pääset\", \"hilmaan\", \"ulkoinen\", \"linkki\", \"päivitetty\", \"western\", \"uusimaa\", \"wellbeing\", \"county\", \"healthcare\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Päivitetty 26.5.2026. Länsi-Uudenmaan hyvinvointialue vastaa sosiaali- ja terveydenhuollosta sekä pelastustoimesta. Hankimme markkinoilta asiakkaille kohdentuvien palvelujen lisäksi palvelutuotannon tarvitsemia palveluita, laitteita ja tavaroita yli 600 miljoonalla eurolla vuosittain. Tavoitteenamme on tarjota yrityksille mahdollisuus osallistua hankintoihin matalalla kynnyksellä luoden yhdessä kustannustehokkaita ratkaisuja asiakkaan parhaaksi. Panostamme avoimuuteen ja läpinäkyvyyteen kaikissa hankintaprosesseissamme. Alla olevaan hyvinvointialueen hankintakalenteriin on listattu suunnitellut kansallisen kynnysarvon ylittävät hankinnat, mitkä julkaistaan myös Hilma-tietokannassa. Hankinnat ja niihin liittyvät asiakirjat ovat myös Tarjouspalvelu.fi -sivuilla, jossa voit jättää tarjoukset. Verkkosivuillamme ylläpidämme myös ajantasaisia tietoja Länsi-Uudenmaan hyvinvointialueen palveluseteleistä ja niiden käsikirjoista. Tästä pääset Hilmaan. ( ulkoinen linkki ) Tästä pääset Tarjouspalvelu.fi -sivulle. ( ulkoinen linkki ) Tästä pääset Luvn.fi -palvelusetelisivulle. Hankinnat ovat listattuna kategorioittain ja voit avata listat alla olevia kategorioita klikkaamalla.\"}',50,NULL,'2026-09-04 10:01:02','2026-09-04 18:01:27');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (2,'6c2c4687534926990b1b','WellbeingCounties','RFP','OPEN','hankinta@luvn.fi','Asiakaspalvelu hankinta@luvn.fi','Western Uusimaa wellbeing county','ANY',3,14,NULL,NULL,NULL,'EUR','https://luvn.fimailto:hankinta@luvn.fi',NULL,'[\"hankinta\", \"luvn\", \"asiakaspalvelu\", \"western\", \"uusimaa\", \"wellbeing\", \"county\", \"healthcare\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Asiakaspalvelu hankinta@luvn.fi Voit ottaa yhteyttä myös yhteydenottolomakkeemme kautta, joka löytyy alta. (Jos yhteydenottolomaketta ei näy, hyväksy evästeet.) Hankintajohtaja Emilia Kortelainen emilia.kortelainen@luvn.fi Hankintoja koskevat tietopyynnöt käsitellään kirjaamon kautta .\"}',50,NULL,'2026-09-04 10:01:02','2026-09-04 18:01:27');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (3,'8779928fa8caa5628efd','WellbeingCounties','RFP','OPEN','Tarjouspalvelu-portaali','Pirkanmaan hyvinvointialue vastaa sosiaali- ja terveydenhuollosta sekä pelastustoimesta. Asiakkaille kohdentuvien palvelujen lisäksi hyvinvointialue hankkii palvelutuotannon tarvitsemia palveluja, aineita, tarvikkeita ja tavaroita. Hankintojen arvo on hyvinvointialueella noin 1,4 miljardia euroa vuodessa.','Pirkanmaa wellbeing county','ANY',3,3,NULL,NULL,NULL,'EUR','http://tarjouspalvelu.fi/Default/Index',NULL,'[\"hyvinvointialue\", \"tarjouspalvelu\", \"portaali\", \"pirkanmaan\", \"vastaa\", \"sosiaali\", \"terveydenhuollosta\", \"pelastustoimesta\", \"asiakkaille\", \"kohdentuvien\", \"palvelujen\", \"lisäksi\", \"hankkii\", \"palvelutuotannon\", \"tarvitsemia\", \"palveluja\", \"aineita\", \"tarvikkeita\", \"tavaroita\", \"hankintojen\"]',NULL,NULL,NULL,'{\"text\": \"Pirkanmaan hyvinvointialue vastaa sosiaali- ja terveydenhuollosta sekä pelastustoimesta. Asiakkaille kohdentuvien palvelujen lisäksi hyvinvointialue hankkii palvelutuotannon tarvitsemia palveluja, aineita, tarvikkeita ja tavaroita. Hankintojen arvo on hyvinvointialueella noin 1,4 miljardia euroa vuodessa. Pirkanmaan hyvinvointialueen hankinnat löytyvät tarjouspalvelu.fi-sivustolta Tuomi Logistiikka Oy:n julkaisemana: Tarjouspalvelu-portaali Kansallisen ja EU-kynnysarvon ylittävät hankinnat ilmoitetaan HILMAssa: Hilma - Julkiset hankinnat Keskeiset asiakirjat Pirkanmaan hyvinvointialueen hankintaohjelma 2026 - 2029 (pdf) Pirkanmaan hyvinvointialueen hankintasuunnitelma 2026 - 2027 (pdf) Sosiaalihuollon kirjaamisen opas (pdf, Pirkanmaan hyvinvointialueelle palveluja tuottaville yksityisille palveluntuottajille Kantaan kirjaamisen tueksi)\"}',50,NULL,'2026-09-04 10:01:48','2026-09-04 18:15:37');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (4,'48032e6f6882ec2cbf95','WellbeingCounties','RFP','OPEN','Pirha tutkihankintoja.fi-palvelussa','','Pirkanmaa wellbeing county','ANY',3,3,NULL,NULL,NULL,'EUR','https://tutkihankintoja.fi/hankintayksikot/Pirkanmaan%20hyvinvointialue',NULL,'[\"pirha\", \"tutkihankintoja\", \"palvelussa\", \"pirkanmaa\", \"wellbeing\", \"county\", \"healthcare\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Pirha tutkihankintoja.fi-palvelussa\"}',50,NULL,'2026-09-04 10:01:48','2026-09-04 18:15:37');
