INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (25,'2024-147407','HILMA','RFP','OPEN','Lentolan päiväkoti, sähköurakka','Hankinta käsittää Lentolan päiväkodin rakentamisen sähköurakan työt urakkalaskenta-asiakirjojen mukaisesti. Sähköurakka on pääurakkaan alistettu sivu-urakka. Kohde uudisrakennus. Työt tehdään tilaajan laadituttamien suunnitelmien mukaan. Rakennusurakoitsija toimii työmaan päätoteuttajana ja työmaan johtovelvollisena urakoitsijana. Tilaajan nimiin kilpailutetaan erikseen sivu-urakoitsijat ja tilaajan erillishankinnat. Sivu-urakoitsijat alistetaan pääurakkaan. Tarjous annetaan tarjouspyyntömateriaalien perusteella. Tarjouspyyntöasiakirjat ovat saatavilla SokoPron linkin kautta. Rakennuskohteen nimi: Lentolan päiväkoti Pyhtäänkorvenkuja 3, Vantaa Kts. liitteet hankinnan kuvaus ja urakkaohjelma. Rakennuspaikan esittely hankinnan kuvauksen mukaisesti.','Vantaan kaupunki / Kaupunkiympäristö / Kiinteistöt ja tilat','ANY',2,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147407','[\"45311000\"]','[\"lentolan\", \"sivu\", \"tilaajan\", \"päiväkoti\", \"sähköurakka\", \"työt\", \"mukaisesti\", \"pääurakkaan\", \"työmaan\", \"urakoitsijat\", \"hankinnan\", \"hankinta\", \"käsittää\", \"päiväkodin\", \"rakentamisen\", \"sähköurakan\", \"urakkalaskenta\", \"asiakirjojen\", \"alistettu\", \"urakka\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/vantaa?id=517998&tpk=33690f4c-36b1-491e-95dd-a2c81632c81b\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-147407\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-147407\", \"lots\"