INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (32,'2024-147478','HILMA','RFP','OPEN','Kolarin kirkon kellotapulin vesikaton ja sisäpuolen korjaustyöt','Kolarin seurakunta pyytää tarjousta kellotapulin vesikaton, sekä sisäpuolen vesivahinkojen korjaustyöstä. Vesikate uusitaan kokonaisuudessaan kellotornin osuudelle ja vesikaton alapuoliset rakenteet uusitaan. Vesikatteen vuotaminen on aiheuttanut kosteusvaurioita myös kellotapulin sisäpuolisille osille, jotka korjataan samassa urakassa. Tilaaja teettää kohteeseen asbesti- ja haitta-ainekartoituksen, joka toimitetaan tarjouspyyntöön lisäkirjeellä. Rakennuskohteen kaikki työt toteutetaan kokonaisurakkana tarjouspyynnön liiteasiakirjojen mukaisesti täysin valmiiksi ja viimeistellyksi toteuttaen Vesikate uusitaan kokonaisuudessaan kellotornin osuudelle ja vesikaton alapuoliset rakenteet uusitaan. Vesikatteen vuotaminen on aiheuttanut kosteusvaurioita myös kellotapulin sisäpuolisille osille, jotka korjataan samassa urakassa. Tilaaja teettää kohteeseen asbesti- ja haitta-ainekartoituksen, joka toimitetaan tarjouspyyntöön lisäkirjeellä.','Kolarin seurakunta','ANY',2,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147478','[\"45000000\"]','[\"kolarin\", \"kellotapulin\", \"vesikaton\", \"uusitaan\", \"seurakunta\", \"sisäpuolen\", \"vesikate\", \"kokonaisuudessaan\", \"kellotornin\", \"osuudelle\", \"alapuoliset\", \"rakenteet\", \"vesikatteen\", \"vuotaminen\", \"aiheuttanut\", \"kosteusvaurioita\", \"sisäpuolisille\", \"osille\", \"jotka\", \"korjataan\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/public/procurement/100494/notice/147478\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-147478\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-147478\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"\", \"currency\": \"EUR\", \"deadline\": \"2024-07-12T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1D7\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Vesikate uusitaan kokonaisuudessaan kellotornin osuudelle ja vesikaton alapuoliset rakenteet uusitaan. Vesikatteen vuotaminen on aiheuttanut kosteusvaurioita myös kellotapulin sisäpuolisille osille, jotka korjataan samassa urakassa.  Tilaaja teettää kohteeseen asbesti- ja haitta-ainekartoituksen, joka toimitetaan tarjouspyyntöön lisäkirjeellä.\", \"descriptionSv\": null, \"procedureType\": \"open\", \"estimatedValue\": 0.0, \"expirationDate\": \"2024-07-12T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": null, \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"works\", \"receivedTenderCount\": 0, \"winnerOrganisations\": \"\", \"innovationConsidered\": true, \"lotResultTotalAmount\": 0.0, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": false, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": true, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": \"\", \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissi