INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (36,'2024-007826','HILMA','OTHER','OPEN','Hattulan, Hämeenlinnan ja Valkeakosken jätekuljetukset: syväkeräys, etukuormaus ja jätepuristimet','Urakka koskee kuntien jätehuoltovastuuseen kuuluvien jätejakeiden keräämistä Hattulan, Hämeenlinnan ja Valkeakosken alueella tarjouspyyntöasiakirjojen mukaisesti. Urakka käsittää jätteen noudon, kuormauksen, kuljettamisen ja toimittamisen tilaajan määrittelemiin vastaanottopaikkoihin. Yksikköhintoihin ei sisällytetä jätteenkäsittelymaksuja, sillä maksua ei peritä urakoitsijalta vaan suoraan kiinteistöiltä. Tarjouspyyntöasiakirjoissa ja sen liitteissä esitetyt asiat ovat toimeksiantoon sisältyviä minimivaatimuksia, joiden mukaisesti urakoitsija tarjouksen tekemällä sitoutuu toimeksiannon toteuttamaan. Tarjouskilpailun voittava urakoitsija velvoitetaan hyväksymään palveluhankinnan sisältö sopimukseen sellaisenaan. Tarjous on sitova ja se tulee tehdä Suomen kielellä., Urakka-alue A, syväkeräys Jätteen keräys ja kuljetus tarjouspyyntöasiakirjojen mukaisesti., Urakka-alue B, etukuormaus Jätteen keräys ja kuljetus tarjouspyyntöasiakirjojen mukaisesti., Urakka-alue C, jätepuristimet Jätteen keräys ja kuljetus tarjouspyyntöasiakirjojen mukaisesti.,','Kiertokapula Oy','ANY',2,2,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-007826','[\"90500000\"]','[\"urakka\", \"mukaisesti\", \"tarjouspyyntöasiakirjojen\", \"jätteen\", \"alue\", \"keräys\", \"kuljetus\", \"hattulan\", \"hämeenlinnan\", \"valkeakosken\", \"syväkeräys\", \"etukuormaus\", \"jätepuristimet\", \"urakoitsija\", \"jätekuljetukset\", \"koskee\", \"kuntien\", \"jätehuoltovastuuseen\", \"kuuluvien\", \"jätejakeiden\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-007826\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-7826\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Urakka-alue A, syväkeräys\", \"titleSv\": \"\", \"cpvCodes\": \"90500000\", \"currency\": \"EUR\", \"deadline\": null, \"lowCarbon\": true, \"nutsCodes\": \"FI1C2\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Jätteen keräys ja kuljetus tarjouspyyntöasiakirjojen mukaisesti.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 1498800.0, \"expirationDate\": \"2024-10-05T07:30:04.629Z\", \"circularEconomy\": true, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": 2, \"winnerOrganisations\": \"Verdis Oy (2230771-6)\", \"innovationConsidered\": true, \"lotResultTotalAmount\": 0.0, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": false, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": true, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}, {\"id\": \"LOT-0002\", \"titleEn\