INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (37,'2024-147444','HILMA','RFP','OPEN','Mittauslaitteet SMARTTEST-projektiin / Measurement instrumentation for SMARTTEST project','Geologian tutkimuskeskuksen tarkoituksena on hankkia SMARTTEST-projektiin fysikaalisten ja kemiallisten parametrien mittaamisen mahdollistavia instrumentteja. Instrumentointia käytetään kaivannaisjätemateriaalin kenttätestauksessa rikastushiekan ja muiden louhintasivuvirtojen ja niiden huokosveden ominaisuuksien tutkimiseen. Kuvat koesuunnitelmista ja anturien suunnitellusta sijoittelusta on esitetty liitteessä 1. Katso lisätiedot liitteessä 1. The aim is to acquire instruments enabling the measurement of physical and chemical parameters for the SMARTTEST project. The instrumentation will be used in field testing of extractive waste material to study tailings and other extractive side streams and their pore water properties. Illustrations of the test designs and the planned placement of the sensors are presented in Appendix 1. Please see more appendix 1 and Invitation Letter (National procurement notification) English Geologian tutkimuskeskuksen tarkoituksena on hankkia SMARTTEST-projektiin fysikaalisten ja kemiallisten parametrien mittaamisen mahdollistavia instrumentteja. Instrumentointia käytetään kaivannaisjätemateriaalin kenttätestauksessa rikastushiekan ja muiden louhintasivuvirtojen ja niiden huokosveden ominaisuuksien tutkimiseen. Kuvat koesuunnitelmista ja anturien suunnitellusta sijoittelusta on esitetty liitteessä 1. Katso lisätiedot liitteessä 1. The instruments will be used to measure the long-term behaviour of extractive waste material (e.g., tailings coarser mineral material (i.e., crushed waste rock) (< 32 mm)) for two or three consecutive years. For example, oxygen and humidity conditions are measured every 30 minutes for three years. The total amount of sensors is gathered in the appendixes. The test materials are assembled in larger-scale container and smaller IBC lysimeters, where the sensors are installed at the desired measurement depths, at the deepest almost 3 meters. The wires from the sensors are passed through or from the concrete walls of the container, or diagonally up, to avoid the formation of preferential flow paths along the cables. Pictures of the TP2-TP4 set-ups can be found at the appendixes. Please see more appendix 1 Invitation Letter (National procurement notification) English','Geologian tutkimuskeskus','SME',5,3,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147444','[\"38400000\"]','[\"smarttest\", \"liitteessä\", \"sensors\", \"projektiin\", \"measurement\", \"geologian\", \"extractive\", \"waste\", \"material\", \"appendix\", \"instrumentation\", \"project\", \"tutkimuskeskuksen\", \"tarkoituksena\", \"hankkia\", \"fysikaalisten\", \"kemiallisten\", \"parametrien\", \"mittaamisen\", \"mahdollistavia\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/gtk?id=513284&tpk=af23f0ef-2d04-4324-8945-ba04939e85e0\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-147444\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-147444\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"38400000\", \"currency\": null, \"deadline\": \"2024-06-26T13:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1D3\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Geologian tutkimuskeskuksen tarkoituksena on hankkia SMARTTEST-projektiin fysikaalisten ja kemiallisten parametrien mittaamisen mahdollistavia instrumentteja. Instrumentointia käytetään kaivannaisjätemateriaalin kenttätestauksessa rikastushiekan ja muiden louhintasivuvirtojen ja niiden huokosveden ominaisuuksien tutkimiseen. Kuvat koesuunnitelmista ja anturien suunnitellusta sijoittelusta on esitetty liitteessä 1.  Katso lisätiedot liitteessä 1.  The instruments will be used to measure the long-term behaviour of extractive waste material (e.g., tailings coarser mineral material (i.e., crushed waste rock) (< 32 mm)) for two or three consecutive years. For example, oxygen and humidity conditions are measured every 30 minutes for three years. The total amount of sensors is gathered in the appendixes. The test materials are assembled in larger-scale container and smaller IBC lysimeters, where the sensors are installed at the desired measurement depths, at the deepest almost 3 meters. The wires from the sensors are passed through or from the concrete walls of the container, or diagonally up, to avoid the formation of preferential flow paths along the cables. Pictures of the TP2-TP4 set-ups can be found at the appendixes.  Please see more appendix 1 Invitation Letter (National procurement notification) English\", \"descriptionSv\": null, \"procedureType\": \"open\", \"estimatedValue\": 0.0, \"expirationDate\": \"2024-06-26T13:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": null, \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": 0, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\":