INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (39,'2024-007869','HILMA','OTHER','OPEN','Laboratorion lasitarvikkeet 2','Laboratorion lasitarvikkeet 2 HUS-yhtymä pyytää tarjouksia Laboratorion lasitarvikkeista. Kyseessä on yhteishankinta, jonka osapuolet on kuvattu jäljempänä tässä tarjouspyynnössä. Tässä tarjouspyynnössä mukana olevista osapuolista käytetään jäljempänä lyhennettä \"Tilaaja\". HUS-yhtymä julkaisi aiemmin viime vuonna tarjouspyynnön HUS 732-2021 Laboratorion lasitarvikkeet. Kyseisessä kilpailutuksessa oli kuitenkin muutamia tuoteryhmiä, joissa asetetuissa vähimmäisvaatimuksissa oli sellaisia virheitä, joiden vuoksi osa-alue jouduttiin keskeyttämään. Tässä tarjouspyynnössä hankintayksikkö pyytää tarjouksia niihin aiemmassa kilpailutuksessa keskeytettyihin osa-alueisiin, jotka kilpailutetaan nyt uudelleen. Hankintaan sisältyvät seuraavat, tarjouspyynnössä ja sen liitteissä tarkemmin yksilöidyt tuoteryhmät/tuotteet: - Aluslasit - Värjäysmaljat Tuotteet on jaettu tuoteryhmiin, joista muodostuvat hankinnan osa-alueet. Hankinta on jaettu 9 osa-alueeseen. Jokaisen osa-alueen (eli tuoteryhmän) sisällä vertailu tehdään kuitenkin riveittäin (eli positioittain. Jokaiseen positioon valitaan yksi (1) toimittaja. Tarjoajan ei tarvitse tuoteryhmän sisällä tarjota jokaiseen positioon. Teknisistä syistä tämän tarjouspyyntödokumentin kohdassa II 1.6. on mainittu, että sopimus ei ole jaettu osiin. Tuoteryhmät ja positiot on kuvattu vain tarjouspyynnön liitteellä 2 Tuoteliite. Lisäksi tarjouspyyntödokumentin kohdassa \"Tarjouspalvelun tiedot\" otsikon \"Hankintamenettely\" alla on teknisistä syistä mainittu, että osatarjoukset ryhmittäin ei ole sallittu. Osatarjoukset on kuitenkin sallittu, kuten tässä tarjouspyynnössä ja sen liitteissä on kuvattu, eli tarjoajan ei tarvitse tuoteryhmän sisällä tarjota jokaiseen positioon. Tarjousten vertailu tehdään positioittain. Jos sama tarjoaja tulee valituksi sopimustoimittajaksi useammassa kuin yhdessä positiossa, hankintayksikkö varaa oikeuden tehdä em. positioista yhden sopimuksen. Hankinnan kohteeseen kuuluu lisäksi lisätuotteet, joiden hankintamäärien arvioidaan olevan vähäisiä, esimerkiksi värjäysmaljojen mahdolliset lisätarvikkeet. Sopimuskausi on yksi (1) vuosi, jonka jälkeen sopimus jatkuu toistaiseksi voimassa olevana. YHTEISHANKINNAN TIEDOT Kyseessä on useamman hankintayksikön yhteishankinta. Tässä tarjouspyynnössä pyydettyjä tuotteita tulevat käyttämään pääasiassa HUS-yhtymän (HUS), Etelä-Karjalan hyvinvointialueen ja Kymenlaakson hyvinvointialueen alueella toimivat HUS Diagnostiikkakeskuksen yksiköt. Sopimuksen piiriin kuuluvat kuitenkin myös HUS-yhtymän muut yksiköt. Tarkemmat tiedot tarjouspyynnön liitteessä 3 Sopimusluonnos. Hankinnan kohde ja sitä koskevat vaatimukset on kuvattu yksityiskohtaisesti tarjouspyynnössä ja sen liitteissä.,','HUS-yhtymä','ANY',3,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-007869','[\"33793000\"]','[\"tarjouspyynnössä\", \"tässä\", \"laboratorion\", \"kuvattu\", \"kuitenkin\", \"lasitarvikkeet\", \"yhtymä\", \"tarjouspyynnön\", \"liitteissä\", \"jaettu\", \"hankinnan\", \"tuoteryhmän\", \"sisällä\", \"jokaiseen\", \"positioon\", \"tiedot\", \"pyytää\", \"tarjouksia\", \"kyseessä\", \"yhteishankinta\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-007869\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-7869\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Laboratorion lasitarvikkeet 2\", \"titleSv\": \"\", \"cpvCodes\": \"33793000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"HUS-yhtymä pyytää tarjouksia Laboratorion lasitarvikkeista. Kyseessä on yhteishankinta, jonka osapuolet on kuvattu jäljempänä tässä tarjouspyynnössä. Tässä tarjouspyynnössä mukana olevista osapuolista käytetään jäljempänä lyhennettä \\\"Tilaaja\\\".\\n\\nHUS-yhtymä julkaisi aiemmin viime vuonna tarjouspyynnön HUS 732-2021 Laboratorion lasitarvikkeet. Kyseisessä kilpailutuksessa oli kuitenkin muutamia tuoteryhmiä, joissa asetetuissa vähimmäisvaatimuksissa oli sellaisia virheitä, joiden vuoksi osa-alue jouduttiin keskeyttämään. Tässä tarjouspyynnössä hankintayksikkö pyytää tarjouksia niihin aiemmassa kilpailutuksessa keskeytettyihin osa-alueisiin, jotka kilpailutetaan nyt uudelleen.\\n\\nHankintaan sisältyvät seuraavat, tarjouspyynnössä ja sen liitteissä tarkemmin yksilöidyt tuoteryhmät/tuotteet:\\n- Aluslasit\\n- Värjäysmaljat\\n\\nTuotteet on jaettu tuoteryhmiin, joista muodostuvat hankinnan osa-alueet. Hankinta on jaettu 9 osa-alueeseen.\\nJokaisen osa-alueen (eli tuoteryhmän) sisällä vertailu tehdään kuitenkin riveittäin (eli positioittain. Jokaiseen positioon valitaan yksi (1) toimittaja.\\nTarjoajan ei tarvitse tuoteryhmän sisällä tarjota jokaiseen positioon.\\n\\nTeknisistä syistä tämän tarjouspyyntödokumentin kohdassa II 1.6. on mainittu, että sopimus ei ole jaettu osiin. Tuoteryhmät ja positiot on kuvattu vain tarjouspyynnön liitteellä 2 Tuoteliite. Lisäksi tarjouspyyntödokumentin kohdassa \\\"Tarjouspalvelun tiedot\\\" otsikon \\\"Hankintamenettely\\\" alla on teknisistä syistä mainittu, että osatarjoukset ryhmittäin ei ole sallittu. Osatarjoukset on kuitenkin sallittu, kuten tässä tarjouspyynnössä ja sen liitteissä on kuvattu, eli tarjoajan ei tarvitse tuoteryhmän sisällä tarjota jokaiseen positioon. Tarjousten vertailu tehdään positioittain.\\nJos sama tarjoaja tulee valituksi sopimustoimittajaksi useammassa kuin yhdessä positiossa, hankintayksikkö varaa oikeuden tehdä em. positioista yhden sopimuksen.\\n\\nHankinnan kohteeseen kuuluu lisäksi lisätuotteet, joiden hankintamäärien arvioidaan olevan vähäisiä, esimerkiksi värjäysmaljojen mahdolliset lisätarvikkeet.\\n\\nSopimuskausi on yksi (1) vuosi, jonka jälkeen sopimus jatkuu toistaiseksi voimassa olevana.\\n\\n\\nYHTEISHANKINNAN TIEDOT\\n\\nKyseessä on useamman hankintayksikön yhteishankinta. Tässä tarjouspyynnössä pyydettyjä tuotteita tulevat käyttämään pääasiassa HUS-yhtymän (HUS), Etelä-Karjalan hyvinvointialueen ja Kymenlaakson hyvinvointialueen alueella toimivat HUS Diagnostiikkakeskuksen yksiköt. Sopimuksen piiriin kuuluvat kuitenkin myös HUS-yhtymän muut yksiköt.\\nTarkemmat tiedot tarjouspyynnön liitteessä 3 Sopimusluonnos.\\n\\nHankinnan kohde ja sitä koskevat vaatimukset on kuvattu yksityiskohtaisesti tarjouspyynnössä ja sen liitteissä.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2024-10-05T07:30:09.382Z\", \"circularEconomy\": true, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": 5, \"winnerOrganisations\": \"Mekalasi Oy (0111498-2)//Immuno Diagnostic Oy (0499964-0)//Fisher Scientific Oy (2281126-9)//Mediq Suomi Oy (2285192-2)\", \"innovationConsidered\": false, \"lotResultTotalAmount\": 0.0, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": false, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"29\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Laboratorion lasitarvikkeet 2\", \"titleSv\": \"\", \"cpvCodes\": \"33793000\", \"currency\": null, \"deadline\": null, \"eFormsId\": \"2d2637d3-463c-4b5d-a98e-bc2712ac8262\", \"isEForms\": true, \"mainType\": \"ContractAwardNotices\", \"noticeId\": 7869, \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"isCancelled\": false, \"procedureId\": 6176, \"biodiversity\": false, \"dateModified\": \"2024-04-05T07:30:09.429Z\", \"fullEFormsId\": \"2d2637d3-463c-4b5d-a98e-bc2712ac8262-01\", \"noticeNumber\": \"2024-007869\", \"@search.score\": 1.0, \"codeOfConduct\": false, \"datePublished\": \"2024-04-05T07:30:09.382Z\", \"descriptionEn\": \"\", \"descriptionFi\": \"Laboratorion lasitarvikkeet 2 HUS-yhtymä pyytää tarjouksia Laboratorion lasitarvikkeista. Kyseessä on yhteishankinta, jonka osapuolet on kuvattu jäljempänä tässä tarjouspyynnössä. Tässä tarjouspyynnössä mukana olevista osapuolista käytetään jäljempänä lyhennettä \\\"Tilaaja\\\".\\n\\nHUS-yhtymä julkaisi aiemmin viime vuonna tarjouspyynnön HUS 732-2021 Laboratorion lasitarvikkeet. Kyseisessä kilpailutuksessa oli kuitenkin muutamia tuoteryhmiä, joissa asetetuissa vähimmäisvaatimuksissa oli sellaisia virheitä, joiden vuoksi osa-alue jouduttiin keskeyttämään. Tässä tarjouspyynnössä hankintayksikkö pyytää tarjouksia niihin aiemmassa kilpailutuksessa keskeytettyihin osa-alueisiin, jotka kilpailutetaan nyt uudelleen.\\n\\nHankintaan sisältyvät seuraavat, tarjouspyynnössä ja sen liitteissä tarkemmin yksilöidyt tuoteryhmät/tuotteet:\\n- Aluslasit\\n- Värjäysmaljat\\n\\nTuotteet on jaettu tuoteryhmiin, joista muodostuvat hankinnan osa-alueet. Hankinta on jaettu 9 osa-alueeseen.\\nJokaisen osa-alueen (eli tuoteryhmän) sisällä vertailu tehdään kuitenkin riveittäin (eli positioittain. Jokaiseen positioon valitaan yksi (1) toimittaja.\\nTarjoajan ei tarvitse tuoteryhmän sisällä tarjota jokaiseen positioon.\\n\\nTeknisistä syistä tämän tarjouspyyntödokumentin kohdassa II 1.6. on mainittu, että sopimus ei ole jaettu osiin. Tuoteryhmät ja positiot on kuvattu vain tarjouspyynnön liitteellä 2 Tuoteliite. Lisäksi tarjouspyyntödokumentin kohdassa \\\"Tarjouspalvelun tiedot\\\" otsikon \\\"Hankintamenettely\\\" alla on teknisistä syistä mainittu, että osatarjoukset ryhmittäin ei ole sallittu. Osatarjoukset on kuitenkin sallittu, kuten tässä tarjouspyynnössä ja sen liitteissä on kuvattu, eli tarjoajan ei tarvitse tuoteryhmän sisällä tarjota jokaiseen positioon. Tarjousten vertailu tehdään positioittain.\\nJos sama tarjoaja tulee valituksi sopimustoimittajaksi useammassa kuin yhdessä positiossa, hankintayksikkö varaa oikeuden tehdä em. positioista yhden sopimuksen.\\n\\nHankinnan kohteeseen kuuluu lisäksi lisätuotteet, joiden hankintamäärien arvioidaan olevan vähäisiä, esimerkiksi värjäysmaljojen mahdolliset lisätarvikkeet.\\n\\nSopimuskausi on yksi (1) vuosi, jonka jälkeen sopimus jatkuu toistaiseksi voimassa olevana.\\n\\n\\nYHTEISHANKINNAN TIEDOT\\n\\nKyseessä on useamman hankintayksikön yhteishankinta. Tässä tarjouspyynnössä pyydettyjä tuotteita tulevat käyttämään pääasiassa HUS-yhtymän (HUS), Etelä-Karjalan hyvinvointialueen ja Kymenlaakson hyvinvointialueen alueella toimivat HUS Diagnostiikkakeskuksen yksiköt. Sopimuksen piiriin kuuluvat kuitenkin myös HUS-yhtymän muut yksiköt.\\nTarkemmat tiedot tarjouspyynnön liitteessä 3 Sopimusluonnos.\\n\\nHankinnan kohde ja sitä koskevat vaatimukset on kuvattu yksityiskohtaisesti tarjouspyynnössä ja sen liitteissä.,\", \"descriptionSv\": \"\", \"isCorrigendum\": false, \"linkedNotices\": \"422180-2023\", \"procedureType\": \"open\", \"sendingSystem\": \"Cloudia Kilpailutus\", \"estimatedValue\": null, \"expirationDate\": \"2024-10-05T07:30:09.382Z\", \"parentNoticeId\": null, \"circularEconomy\": true, \"endUserInvolved\": null, \"isEuProcurement\": true, \"noticeOjsNumber\": \"\", \"contractFolderId\": \"b8a71be9-3933-4af9-8419-45a238750396\", \"descriptionOther\": \"\", \"organisationType\": \"ra\", \"previousEFormsId\": [], \"tedPublicationId\": \"201555-2024\", \"tenderingInHilma\": false, \"previousSearchIds\": [], \"organisationNameEn\": \"\", \"organisationNameFi\": \"HUS-yhtymä\", \"organisationNameSv\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"organisationAddress\": \"Uutistie 3C 01770 Vantaa FIN\", \"procurementTypeCode\": \"supplies\", \"winnerOrganisations\": \"Mekalasi Oy (0111498-2)//Immuno Diagnostic Oy (0499964-0)//Fisher Scientific Oy (2281126-9)//Mediq Suomi Oy (2285192-2)\", \"innovationConsidered\": false, \"organisationNutsCode\": \"FI1B1\", \"previousFullEFormsId\": [], \"previousNoticeNumber\": [], \"isNationalProcurement\": false, \"justWorkingConditions\": true, \"organisationNameOther\": \"\", \"organisationDepartment\": \"\", \"listedGreenCriteriaUsed\": false, \"noticeResultTotalAmount\": 223700.0, \"oldProcurementProjectId\": 0, \"procurementDocumentsUrl\": null, \"previousContractFolderId\": [], \"previousTedPublicationId\": [], \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"refOldNoticeTedPublicationId\": \"422180-2023\", \"solutionNewToMarketOrIndustry\": false, \"isPrivateSmallValueProcurement\": false, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"isNationalSmallValueProcurement\": false, \"noticeResultTotalAmountCurrency\": \"EUR\", \"organisationNationalRegistrationNumber\": \"1567535-0\", \"overallMaximumFrameworkContractsAmount\": null, \"overallMaximumFrameworkContractsCurrency\": null, \"overallApproximateFrameworkContractsAmount\": null, \"overallApproximateFrameworkContractsCurrency\": null}',45,NULL,'2026-09-04 10:19:13','2026-09-05 14:59:03');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (40,'2024-007855','HILMA','RFI','OPEN','Sustainable Flow CO2 Tool','Sustainable Flow CO2 Tool The purpose of this Prior Information Notice is to seek potential candidates to regarding Satakunta University (SAMK) planned joint procurement for Sustainable Flow CO2 Tool. The \"Sustainable Flow CO2 Tool\" is a digital application designed to address the issue of CO2 emissions within the maritime cluster, specifically port environments. This tool shall offer comprehensive functionalities aimed at monitoring, forecasting, simulating, optimizing, and reporting emissions, ensuring environmental sustainability and regulatory compliance: Emissions Calculation: Utilizing advanced analytics, the tool will accurately quantify CO2 emissions from transportation activities, providing comprehensive insights that will help the ports improve their operations and lower emissions. The data is collected from various sources within the ports and entered into the digital tool via APIs or manually. Advanced Analytics: The tool will identify trends and opportunities for emission reduction in the ports (i.e., via Power BI). The tool must also be able to simulate the emission impact of different emission-lowering solutions, for example, shore power and solar panels. Sustainability Reporting: Port authorities can, via the digital tool, generate detailed sustainability reports, fostering transparency and accountability. The reports must adhere to current CSRD and ISO 14083:2023 standards on both a national and international level. Guidance Tool: The digital tool will include a guidance tool that will facilitate end users (ports) to make decisions in their work towards becoming greener businesses.,','Satakunnan ammattikorkeakoulu Oy','ANY',1,5,NULL,NULL,420000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-007855','[\"72000000\", \"63721000\"]','[\"tool\", \"emissions\", \"sustainable\", \"flow\", \"digital\", \"ports\", \"sustainability\", \"emission\", \"within\", \"port\", \"comprehensive\", \"reporting\", \"advanced\", \"analytics\", \"their\", \"power\", \"must\", \"reports\", \"guidance\", \"satakunnan\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/samk?id=505347&tpk=25e777e9-e0f1-4ce9-84ca-48fdf4956bd8\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-007855\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-7855\", \"lots\": [{\"id\": \"PAR-0000\", \"titleEn\": \"Sustainable Flow CO2 Tool\", \"titleFi\": \"\", \"titleSv\": \"\", \"cpvCodes\": \"72000000 63721000\", \"currency\": \"EUR\", \"deadline\": null, \"lowCarbon\": null, \"nutsCodes\": \"FI196\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"The purpose of this Prior Information Notice is to seek potential candidates to \\nregarding Satakunta University (SAMK) planned joint procurement for \\nSustainable Flow CO2 Tool. \\nThe \\\"Sustainable Flow CO2 Tool\\\" is a digital application designed to address the issue of CO2 emissions within the maritime cluster, specifically port environments. This tool shall offer comprehensive functionalities aimed at monitoring, forecasting, simulating, optimizing, and reporting emissions, ensuring environmental sustainability and regulatory compliance:\\n\\nEmissions Calculation: Utilizing advanced analytics, the tool will accurately quantify CO2 emissions from transportation activities, providing comprehensive insights that will help the ports improve their operations and lower emissions. The data is collected from various sources within the ports and entered into the digital tool via APIs or manually.\\n\\nAdvanced Analytics: The tool will identify trends and opportunities for emission reduction in the ports (i.e., via Power BI). The tool must also be able to simulate the emission impact of different emission-lowering solutions, for example, shore power and solar panels.\\n\\nSustainability Reporting: Port authorities can, via the digital tool, generate detailed sustainability reports, fostering transparency and accountability. The reports must adhere to current CSRD and ISO 14083:2023 standards on both a national and international level.\\n\\nGuidance Tool: The digital tool will include a guidance tool that will facilitate end users (ports) to make decisions in their work towards becoming greener businesses.\", \"descriptionFi\": \"\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 420000.0, \"expirationDate\": \"2024-10-05T07:30:07.597Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": null, \"lotResultTotalAmount\": null, \"justWorkingConditions\": null, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": null, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": null, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": null, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibil