INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (41,'2024-147606','HILMA','RFP','OPEN','Kristiinankaupungin Skatan alueen vesihuoltohanke','Rakennuskohde sijaitsee Kristiinankaupungissa Skatan alueella. Uusi vesihuoltolinja kulkee Skatantien vieressä Björkskäretin päädystä Kapteenintielle, Kapteenintien ja Kaninsaarentien kautta takaisin Skatantielle ja Skatantien vartta Korkeasaarentien risteykseen. Urakassa rakennetaan paineja viettojätevesiviemärilinjaa, runko- ja jakeluvesijohtoja sekä niihin liittyviä verkoston osia. Rakennuskohde sijaitsee Kristiinankaupungissa Skatan alueella. Uusi vesihuoltolinja kulkee Skatantien vieressä Björkskäretin päädystä Kapteenintielle, Kapteenintien ja Kaninsaarentien kautta takaisin Skatantielle ja Skatantien vartta Korkeasaarentien risteykseen. Urakassa rakennetaan paineja viettojätevesiviemärilinjaa, runko- ja jakeluvesijohtoja sekä niihin liittyviä verkoston osia.','Kristinestad Stad - KRS-Vatten / Kristiinankaupungin kaupunki - KRS-Vesi','ANY',5,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147606','[\"45000000\"]','[\"skatantien\", \"kristiinankaupungin\", \"skatan\", \"rakennuskohde\", \"sijaitsee\", \"kristiinankaupungissa\", \"alueella\", \"uusi\", \"vesihuoltolinja\", \"kulkee\", \"vieressä\", \"björkskäretin\", \"päädystä\", \"kapteenintielle\", \"kapteenintien\", \"kaninsaarentien\", \"kautta\", \"takaisin\", \"skatantielle\", \"vartta\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/krs?id=516779&tpk=c303d3d0-a3ca-4562-8a10-9851bba21b6a\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/noti