INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (46,'2024-007740','HILMA','OTHER','OPEN','Radiologisen angiolaitteen päivitys Hämeenlinnan röntgenyksikköön','Radiologisen angiolaitteen päivitys Hämeenlinnan röntgenyksikköön Suorahankinnan kohteena on Kanta-Hämeen hyvinvointialueen keskussairaalan röntgen yksikössä sijaitsevan radiologisen angiografialaiteen Philips Allura L4L:n päivitys. Hankinta toteutetaan hankintalain 40 §:n 2 mom. 2 kohdan perusteella: Teknisestä tai yksinoikeuden suojaamiseen liittyvästä syystä vain tietty toimittaja voi toteuttaa hankinnan; lisäedellytyksenä on, että järkeviä vaihtoehtoisia tai korvaavia ratkaisuja ei ole eikä kilpailun puuttuminen johdu hankinnan ehtojen keinotekoisesta kaventamisesta mukaisella suorahankintamenettelyllä. Suorahankinnan perusteena on laitepäivitys, jonka ainoa mahdollinen toimittaja on Philips Oy. Asiantuntijaryhmä on vertaillut eri vaihtoehtoja ja todennut, että laitteen päivittäminen on selvästi kokonaistaloudellisesti edullisin ratkaisu. Päivityksen yhteydessä toiminnalliset ominaisuudet paranevat, joka helpottaa ja sujuvoittaa toimenpiteiden toteuttamista. Kuvanlaadun paraneminen puolestaan lisää potilasturvallisuutta ja säteilyhygieniaa merkittävästi. Päivittäminen tulee huomattavasti edullisemmaksi kuin kokonaan uuden laitteen hankkiminen. Laitteiston tekniseen ylläpitoon hankitaan samassa yhteydessä Technology Maximizer -ohjelmistopäivityssopimus neljälle (4) vuodelle.,','Kanta-Hämeen hyvinvointialue','ANY',3,2,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-007740','[\"33111000\", \"33111720\"]','[\"radiologisen\", \"päivitys\", \"angiolaitteen\", \"hämeenlinnan\", \"röntgenyksikköön\", \"suorahankinnan\", \"kanta\", \"hämeen\", \"philips\", \"toimittaja\", \"hankinnan\", \"laitteen\", \"päivittäminen\", \"yhteydessä\", \"kohteena\", \"hyvinvointialueen\", \"keskussairaalan\", \"röntgen\", \"yksikössä\", \"sijaitsevan\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-007740\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-7740\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Radiologisen angiolaitteen päivitys Hämeenlinnan röntgenyksikköön\", \"titleSv\": \"\", \"cpvCodes\": \"33111000 33111720\", \"currency\": null, \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI1C2\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Suorahankinnan kohteena on Kanta-Hämeen hyvinvointialueen keskussairaalan röntgen yksikössä sijaitsevan radiologisen angiografialaiteen Philips Allura L4L:n päivitys. Hankinta toteutetaan hankintalain 40 §:n 2 mom. 2 kohdan perusteella:\\nTeknisestä tai yksinoikeuden suojaamiseen liittyvästä syystä vain tietty toimittaja voi toteuttaa hankinnan; lisäedellytyksenä on, että järkeviä vaihtoehtoisia tai korvaavia ratkaisuja ei ole eikä kilpailun puuttuminen johdu hankinnan ehtojen keinotekoisesta kaventamisesta mukaisella suorahankintamenettelyllä.\\n\\nSuorahankinnan perusteena on laitepäivitys, jonka ainoa mahdollinen toimittaja on Philips Oy. Asiantuntijaryhmä on vertaillut eri vaihtoehtoja ja todennut, että laitteen päivittäminen on selvästi kokonaistaloudellisesti edullisin ratkaisu. Päivityksen yhteydessä toiminnalliset ominaisuudet paranevat, joka helpottaa ja sujuvoittaa toimenpiteiden toteuttamista. Kuvanlaadun paraneminen puolestaan lisää potilasturvallisuutta ja säteilyhygieniaa merkittävästi. Päivittäminen tulee huomattavasti edullisemmaksi kuin kokonaan uuden laitteen hankkiminen.\\n\\nLaitteiston tekniseen ylläpitoon hankitaan samassa yhteydessä Technology Maximizer -ohjelmistopäivityssopimus neljälle (4) vuodelle.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2024-10-03T07:30:04.187Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"Philips Oy (0889447-5)\", \"innovationConsidered\": true, \"lotResultTotalAmount\": 0.0, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"29\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Radiologisen angiolaitteen päivitys Hämeenlinnan röntgenyksikköön\", \"titleSv\": \"\", \"cpvCodes\": \"33111000 33111720\", \"currency\": null, \"deadline\": null, \"eFormsId\": \"b5be6e2b-3c4a-4dfb-8756-4b88a7552d61\", \"isEForms\": true, \"mainType\": \"ContractAwardNotices\", \"noticeId\": 7740, \"lowCarbon\": false, \"nutsCodes\": \"FI1C2\", \"titleOther\": \"\", \"isCancelled\": false, \"procedureId\": 3690, \"biodiversity\": false, \"dateModified\": \"2024-04-03T07:30:04.