\"sendingSystem\": \"Cloudia Kilpailutus\", \"estimatedValue\": 0.0, \"expirationDate\": \"2024-08-09T12:00:00Z\", \"parentNoticeId\": null, \"circularEconomy\": false, \"endUserInvolved\": null, \"isEuProcurement\": false, \"noticeOjsNumber\": null, \"contractFolderId\": null, \"descriptionOther\": null, \"organisationType\": \"OtherType\", \"previousEFormsId\": [], \"tedPublicationId\": null, \"tenderingInHilma\": null, \"previousSearchIds\": [], \"organisationNameEn\": null, \"organisationNameFi\": \"Mikkelin Kehitysyhtiö Miksei Oy\", \"organisationNameSv\": null, \"solutionNewToBuyer\": true, \"employmentCondition\": false, \"organisationAddress\": \"Maaherrankatu 9-11 50100 Mikkeli FI\", \"procurementTypeCode\": \"services\", \"winnerOrganisations\": \"\", \"innovationConsidered\": true, \"organisationNutsCode\": \"FI1D1\", \"previousFullEFormsId\": [], \"previousNoticeNumber\": [], \"isNationalProcurement\": true, \"justWorkingConditions\": false, \"organisationNameOther\": null, \"organisationDepartment\": null, \"listedGreenCriteriaUsed\": false, \"noticeResultTotalAmount\": null, \"oldProcurementProjectId\": 101000, \"procurementDocumentsUrl\": \"https://tarjouspalvelu.fi/mikkeli?id=516001&tpk=ba025f55-b4b0-458b-9d60-2203aab63444\", \"previousContractFolderId\": [], \"previousTedPublicationId\": [], \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": true, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"refOldNoticeTedPublicationId\": null, \"solutionNewToMarketOrIndustry\": true, \"isPrivateSmallValueProcurement\": false, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"isNationalSmallValueProcurement\": false, \"noticeResultTotalAmountCurrency\": null, \"organisationNationalRegistrationNumber\": \"0600598-8\", \"overallMaximumFrameworkContractsAmount\": null, \"overallMaximumFrameworkContractsCurrency\": null, \"overallApproximateFrameworkContractsAmount\": null, \"ov