INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (49,'2024-147518','HILMA','RFP','OPEN','Tammelan Tammitarhan päiväkodin leikkipihan luonnonmukaistaminen / Urakka','Tammelan kunta pyytää urakkatarjouksia Tammitarhan päiväkodin leikkipihan luonnonmukaistamisesta liitteenä olevien asiakirjojen mukaisesti. Päiväkoti sijaitsee osoitteessa Nuuttikulmantie 19A, 30100 Forssa. Urakan sisältö ja vaatimukset on kuvattu tarkemmin liitteenä olevissa tarjouspyyntöasiakirjoissa. Tammitarhan päiväkodin piha-alueella on leikkipiha, jota laajennetaan luonnonmukaisella alueella ja näin parannetaan lasten ja aikuisten liikuntaedellytyksiä. Luonnonmukaistettavaan piha-alueeseen istutetaan kasvillisuutta ja lisätään luontomateriaaleja kuten erilaisia kiviä ja puunrunkoja. Luonnonmateriaalien on tarkoitus houkutella lapsia leikkimään ja liikkumaan monipuolisesti. Puiksi valitaan nopeasti kasvavia puita, jotka tuovat pihaan luonnonvarjoa ja suojaa. Lisäksi pihalle istutetaan marjapensaita ja hedelmäpuita. Istutettavien puiden riittävä tuenta tulee huomioida. Puiden ja pensaiden alustat katetaan männynkuorikatteella. Pihalle asennetaan myös kasvatuslaatikoita, joissa lapset voivat kasvattaa esim. kukkia ja hyötykasveja. Urakkaan sisältyy urakka-alueen luonnonmukaistamisen suunnittelu ja toteutus kaivuutöineen käyttövalmiiksi, rakenteineen ja istutuksineen. Urakkaan sisältyy myös yleissuunnitelmassa esitetty riippusilta ja sen turva-alustat asennettuna käyttökuntoon välinevalmistajan asennusohjeen mukaisesti. Urakan sisältö ja vaatimukset on kuvattu tarkemmin liitteenä olevissa tarjouspyyntöasiakirjoissa.','Tammelan kunta','ANY',2,2,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147518','[\"45112723\", \"45112710\", \"45112711\"]','[\"tammelan\", \"tammitarhan\", \"päiväkodin\", \"liitteenä\", \"leikkipihan\", \"urakka\", \"kunta\", \"mukaisesti\", \"urakan\", \"sisältö\", \"vaatimukset\", \"kuvattu\", \"tarkemmin\", \"olevissa\", \"tarjouspyyntöasiakirjoissa\", \"piha\", \"alueella\", \"istutetaan\", \"pihalle\", \"puiden\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/juhaconsulting?id=517860&tpk=be1cc476-c42f-4df3-a3d9-fbe40030c818\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-147518\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-147518\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"45112710 45112711 45112723\", \"currency\": null, \"deadline\": \"2024-08-23T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1C2\", \"titleOther\": null, \"biodiversity\": true, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Tammitarhan päiväkodin piha-alueella on leikkipiha, jota laajennetaan luonnonmukaisella alueella ja näin parannetaan lasten ja aikuisten liikuntaedellytyksiä. Luonnonmukaistettavaan piha-alueeseen istutetaan kasvillisuutta ja lisätään luontomateriaaleja kuten erilaisia kiviä ja puunrunkoja. Luonnonmateriaalien on tarkoitus houkutella lapsia leikkimään ja liikkumaan monipuolisesti. Puiksi valitaan nopeasti kasvavia puita, jotka tuovat pihaan luonnonvarjoa ja suojaa. Lisäksi pihalle istutetaan marjapensaita ja hedelmäpuita. Istutettavien puiden riittävä tuenta tulee huomioida. Puiden ja pensaiden alustat katetaan männynkuorikatteella. Pihalle asennetaan myös kasvatuslaatikoita, joissa lapset voivat kasvattaa esim. kukkia ja hyötykasveja.   Urakkaan sisältyy urakka-alueen luonnonmukaistamisen suunnittelu ja toteutus kaivuutöineen käyttövalmiiksi, rakenteineen ja istutuksineen. Urakkaan sisältyy myös yleissuunnitelmassa esitetty