INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (50,'2024-147517','HILMA','RFP','OPEN','Tammelan Tammitarhan päiväkodin leikkivälineet ja varusteet','Tammitarhan päiväkodin piha-alueella on jo olemassa olevia leikkivälineitä. Hankinnalla parannetaan päiväkodin liikuntaedellytyksiä lisäämällä leikkipihalle temppuilu- ja pelipaikkoja, jotka parantavat lasten ja henkilöstön fyysistä aktiivisuutta, liikuntamahdollisuuksia ja taitoja kuten koordinaatiota, tasapainoa, nopeutta, voimaa ja kestävyyttä. Lasten ikähaarukka 1 - 7 v. Hankintaan sisältyy leikkivälineet ja varusteet sekä niiden perustusten kaivuu- ja täyttötyöt, tarvittavat turva-alustat kaivuineen sekä leikkivälineiden ja varusteiden asennus käyttökuntoon välinevalmistajan asennusohjeen mukaan. Hankinnan sisältö ja vaatimukset on kuvattu tarkemmin liitteenä olevissa tarjouspyyntöasiakirjoissa. Tammitarhan päiväkodin piha-alueella on jo olemassa olevia leikkivälineitä. Hankinnalla parannetaan päiväkodin liikuntaedellytyksiä lisäämällä leikkipihalle temppuilu- ja pelipaikkoja, jotka parantavat lasten ja henkilöstön fyysistä aktiivisuutta, liikuntamahdollisuuksia ja taitoja kuten koordinaatiota, tasapainoa, nopeutta, voimaa ja kestävyyttä. Lasten ikähaarukka 1 - 7 v. Hankintaan sisältyy leikkivälineet ja varusteet sekä niiden perustusten kaivuu- ja täyttötyöt, tarvittavat turva-alustat kaivuineen sekä leikkivälineiden ja varusteiden asennus käyttökuntoon välinevalmistajan asennusohjeen mukaan. Tarjouksen tulee sisältää seuraavat leikkivälineet ja varusteet: - Peliareena, 1 kpl: - Kiipeilyteline, 1 kpl: - Karuselli, 1 kpl: - Hiekkalaatikko, 1 kpl: - Katos, 1 kpl: Lisäksi optiona: - Trampoliini, 1 kpl: Option tarjoaminen on pakollista. Tilaaja päättää optiona trampoliinin hankinnasta määrärahojen puitteissa. Hankinnan sisältö ja vaatimukset on kuvattu tarkemmin liitteenä olevissa tarjouspyyntöasiakirjoissa.','Tammelan kunta','ANY',10,2,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147517','[\"43325000\"]','[\"päiväkodin\", \"leikkivälineet\", \"varusteet\", \"lasten\", \"tammitarhan\", \"tammelan\", \"piha\", \"alueella\", \"olemassa\", \"olevia\", \"leikkivälineitä\", \"hankinnalla\", \"parannetaan\", \"liikuntaedellytyksiä\", \"lisäämällä\", \"leikkipihalle\", \"temppuilu\", \"pelipaikkoja\", \"jotka\", \"parantavat\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/juhaconsulting?id=517755&tpk=6f23eb81-ce4b-40a4-9693-33b47ae3a851\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-147517\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-147517\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"43325000\", \"currency\": null, \"deadline\": \"2024-08-23T07:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1C2\", \"titleOther\": null, \"biodiversity\": true, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Tammitarhan päiväkodin piha-alueella on jo olemassa olevia leikkivälineitä. Hankinnalla parannetaan päiväkodin liikuntaedellytyksiä lisäämällä leikkipihalle temppuilu- ja pelipaikkoja, jotka parantavat lasten ja henkilöstön fyysistä aktiivisuutta, liikuntamahdollisuuksia ja taitoja kuten koordinaatiota, tasapainoa, nopeutta, voimaa ja kestävyyttä. Lasten ikähaarukka 1 - 7 v.  Hankintaan sisältyy leikkivälineet ja varusteet sekä niiden perustusten kaivuu- ja täyttötyöt, tarvittavat turva-alustat kaivuineen sekä leikkivälineiden ja varusteiden asennus käyttökuntoon välinevalmistajan asennusohjeen mukaan.   Tarjouksen tulee sisältää seuraavat leikkivälineet ja varusteet: - P