INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (55,'2024-147630','HILMA','OTHER','OPEN','Kansallisten hankintojen suorahankintailmoitus','Toteutettavassa T&K -hankkeessa sovelletaan ja kehitetään ProDigial-tutkimusohjelmassa muodostettua ”tahdikkaan implementoinnin TAIMI-mallia”. Väyläviraston osalta tämä kohdentuu kunnossapitokäsitteeseen liittyvän sanastotyön tuotosten muodostamisen sekä käyttöönoton tukemiseen ja tehostamiseen. Väyläviraston lisäksi väyläverkon kunnossapidon kannalta on keskeistä yhteistyö ELY-keskusten ja sanastotyötä toteuttavan terminologin kanssa. Lisäksi kunnossapitokäsitteiden sanastotyö koskee ja hyödyttää kuntia ja koko rakennetun ympäristön toimialaa, mikä on syytä pitää hankkeen ajan eräänä näkökulmana. Päätuotoksina projektissa tuotetaan • Runko jalkautussuunnitelmalle. • Jalkautussuunnitelman rikastuva ja päivitettävä sisältö. • Tahdikkaan jalkautuksen yleinen materiaali Väylävirastolle. Päätuotosten lisäksi tuotoksina odotetaan muodostuvan mm: • Valittavien testauskohteiden työketjujen hahmotus ja todennäköisesti sen myötä sujuvoituminen. • Jatkuvan parantamisen kyvykkyyden kypsyystason nousu mukana olevien tahojen osalta, mikä luo pohjaa tuottavuuden ja kestävyyden parantamiseen.','Väylävirasto','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147630','[\"73000000\"]','[\"lisäksi\", \"tahdikkaan\", \"väyläviraston\", \"osalta\", \"mikä\", \"väylävirasto\", \"kansallisten\", \"hankintojen\", \"suorahankintailmoitus\", \"toteutettavassa\", \"hankkeessa\", \"sovelletaan\", \"kehitetään\", \"prodigial\", \"tutkimusohjelmassa\", \"muodostettua\", \"implementoinnin\", \"taimi\", \"mallia\", \"tämä\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-147630\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-147630\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"73000000\", \"currency\": null, \"deadline\": \"2024-07-14T10:23:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"\", \"descriptionSv\": null, \"procedureType\": null, \"estimatedValue\": 0.0, \"expirationDate\": \"2024-07-14T10:23:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": null, \"solutionNewToBuyer\": true, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": 0, \"winnerOrganisations\": \"Ramboll Finland Oy (0101197-5)\", \"innovationConsidered\": true, \"lotResultTotalAmount\": 0.0, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": true, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"9905\", \"isPlan\": false, \"planId\": 0, \"titleEn\": null, \"titleFi\": \"Kansallisten hankintojen suorahankintail