INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (64,'2024-147102','HILMA','RFP','OPEN','VAV / Kukinkuja 8 Ikkunoiden ja parveke- / terassiovien uusiminen','Kiinteistön ikkunoiden ja parveke- / terassiovien uusimistyöt liitteenä olevien suunnitelmien osoittamassa laajuudessa. kts.Urakkaohjelma ja Työselitykset Kiinteistöt ovat VAV Asunnot Oy:n omistamia ja isännöimiä. Työt käsittävät kiinteistön ikkunoiden ja parveke- / terassiovien uusimistyöt liitteenä olevien suunnitelmien osoittamassa laajuudessa. Korjattavat kiinteistöt luovutetaan urakoitsijalle siinä kunnossa, kuin ne tarjoushetkellä ovat. Urakkamuoto on kokonaisurakka (pääurakka).YSE 3 §:n mukaiset työmaapalvelut sisältyvät pääurakkaan. Pääurakoitsija toimii myös kohteen päätoteuttajana. Hankintaan sovelletaan Hankintalain 96 §:n säädöstä poikkeuksellisen alhaisista tarjouksista sekä niiden mahdollisesta hylkäämisestä. Urakoitsijan tulee tutustua kohteeseen ennen tarjouksen antamista ja hänen tulee tarjouksessaan ottaa huomioon siellä vallitsevat olosuhteet. Huoneistot ovat asutettuja. Kohdetiedot: Kukinkuja 8, 01620 Vantaa','VAV Asunnot Oy','ANY',2,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147102','[\"45000000\"]','[\"ikkunoiden\", \"parveke\", \"terassiovien\", \"ovat\", \"kukinkuja\", \"kiinteistön\", \"uusimistyöt\", \"liitteenä\", \"olevien\", \"suunnitelmien\", \"osoittamassa\", \"laajuudessa\", \"kiinteistöt\", \"asunnot\", \"tulee\", \"uusiminen\", \"urakkaohjelma\", \"työselitykset\", \"omistamia\", \"isännöimiä\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/vav?id=516255&tpk=e83ec9f9-36c4-4ff0-9776-f756bfcac