INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (81,'2025-020569','HILMA','RFP','OPEN','Tietokonetomografialaite (CT-laite/TT-laite)','Tietokonetomografialaite (CT-laite/TT-laite) HANKINNAN KOHDE Hankinnan kohteena on tietokonetomografialaite (myöhemmin CT-laite) Terveyden ja hyvinvointilaitoksen oikeuslääkintäyksikön Helsingin toimipisteeseen. CT-laite on tarkoitettu vainajien oikeuslääketieteellisiin kuvauksiin. Tarjottu CT-laite voi olla uusi tai tehdaskunnostettu. CT-laite hankintaan kokonaispalveluna tarjouspyynnössä ja sen liitteissä määritellyn mukaisesti. Hankinnan kohde on kuvattu tarkemmin tarjouspyynnössä ja sen liitteissä, erityisesti liitteessä 1 \"Hankinnan kohteen kuvaus\". SOPIMUSKAUSI Sopimus on määräaikaisena voimassa viisi (5) vuotta. Tämän jälkeen Tilaaja voi jatkaa sopimuskautta kahdella (2) enintään kahden (2) vuoden optiokaudella. Ks. myös tarjouspyynnön liitteenä A olevan sopimuksen luku 4.,','Terveyden ja hyvinvoinnin laitos','ANY',3,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2025-020569','[\"33110000\", \"48100000\", \"50000000\", \"51000000\", \"72260000\"]','[\"laite\", \"hankinnan\", \"tietokonetomografialaite\", \"kohde\", \"terveyden\", \"tarjouspyynnössä\", \"liitteissä\", \"kohteena\", \"myöhemmin\", \"hyvinvointilaitoksen\", \"oikeuslääkintäyksikön\", \"helsingin\", \"toimipisteeseen\", \"tarkoitettu\", \"vainajien\", \"oikeuslääketieteellisiin\", \"kuvauksiin\", \"tarjottu\", \"uusi\", \"tehdaskunnostettu\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/thl?id=518920&tpk=c21cb161-d56e-4ffb-ba42-b31ad20fe1cc\", \"name\": \"Procurement Documents\"}, 