INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (92,'2025-020644','HILMA','OTHER','OPEN','Sivakka-yhtymä Oy / Kodinkoneiden hankinta','Hankinnan kohteena ovat kodinkoneet oululaisen Sivakan omistamien taloyhtiöiden tarpeisiin. Sivakka koostuu seuraavista yhtiöistä: Sivakka-yhtymä Oy, Oulun Sivakka Oy ja Oulun Tervatalot Oy. Yhtiöiden omistuksessa on noin 210 kiinteistöä ja 8400 asuntoa. Hankinta-on jaettu kahteen osa-alueeseen: 1) yksittäiskohteiden kodinkoneet 2) korjaus- ja uudiskohteiden kodinkoneet Hankinnasta muodostetaan puitejärjestely. Molempiin osa-alueisiin valitaan kilpailutuksen tuloksen mukaisesti kaksi (2) kokonaistaloudellisesti edullisimman tarjouksen jättänyttä tarjoajaa., I. Kodinkoneet yksittäisiin kohteisiin Yksittäisiä kodinkonetilauksia tehdään vuodessa noin 800-900 kappaletta. Yksittäiset konetilaukset ovat korvauskoneita, joita tilaaja hankkii rikkoutuneiden koneiden tilalle n. 700 kappaletta / vuosi sekä asukasetukoneita, joita hankintaan noin 100 kappaletta / vuosi. Yksittäiset koneet hankitaan asuttuihin asuntoihin toimintakuntoon asennettuina. Asukasetukoneet ovat laadukkaampia kodinkoneita, joita tarjotaan asukkaille, jotka ovat asuneet Sivakan asunnoissa yli 5 vuotta. Asukasetuina toimitetut koneet ovat olleet lähinnä keraamisia kiertoilmaliesiä, induktioliesiä ja astianpesukoneita. Yksittäiskoneiden toimitusaika on enintään 24 tuntia tilauksesta. Toimitukseen sisältyy mahdollinen kiinteistön avaimen nouto Oulussa sijaitsevasta lukkoliikkeestä, jonne avain toimituksen jälkeen myös palautetaan. Mahdollisesta avaimen noudosta ilmoitetaan tilauksen yhteydessä. Kuljetusmaksut sisältyvät toimitettavien laitteiden hintaan lukuun ottamatta liitteen 1. \"Vyöhykekartta\" mukaisia B-vyöhykkeellä sijaitsevia kohteita (Ylikiiminki, Haukipudas, Yli-Ii sekä Oulunsalon Salonpää), joihin toimitetuista tilauksista toimittaja voi periä erillisen kuljetusmaksun. Hankinnassa mukana olevista kohdekiinteistöistä noin 6 % sijaitsee B-vyöhykkeellä., II. Kodinkoneet korjaus- ja uudiskohteisiin Korjaus- ja uudiskohteisiin hankittavat koneet tilataan suuremmissa erissä. Tilauksia tehdään noin 200 - 300 kappaletta/vuosi. Koneet hankitaan työmaalle toimitettuina ilman asennusta. Korjauskohteisiin toimitettavat koneet tilataan viimeistään kuukausi ennen toimitusta. Tilattavat erät sisältävät 5-10 asunnon kodinkonetoimitukset. Uudiskohteisiin toimitettavat koneet tilataan viimeistään kolme (3) kuukautta ennen toimitusta. Ennakkotieto tarvittavasta konemäärästä on saatavilla noin 1,5 vuotta ennen toimitusajankohtaa. Tilaaja tarkentaa toimitusaikaa vielä 3-6 kuukautta ennen toimitusta. Kuljetusmaksut sisältyvät laitteiden hintaan.,','Sivakka-yhtymä Oy','ANY',2,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2025-020644','[\"39700000\"]','[\"sivakka\", \"noin\", \"koneet\", \"ovat\", \"kodinkoneet\", \"yhtymä\", \"kappaletta\", \"ennen\", \"korjaus\", \"joita\", \"vuosi\", \"uudiskohteisiin\", \"tilataan\", \"toimitusta\", \"hankinta\", \"sivakan\", \"oulun\", \"tehdään\", \"yksittäiset\", \"tilaaja\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2025-020644\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-20644\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"I. Kodinkoneet yksittäisiin kohteisiin\", \"titleSv\": \"\", \"cpvCodes\": \"39700000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": true, \"nutsCodes\": \"FI1D9\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Yksittäisiä kodinkonetilauksia tehdään vuodessa noin 800-900 kappaletta. Yksittäiset konetilaukset ovat korvauskoneita, joita tilaaja hankkii rikkoutuneiden koneiden tilalle n. 700 kappaletta / vuosi sekä asukasetukoneita, joita hankintaan noin 100 kappaletta / vuosi. Yksittäiset koneet hankitaan asuttuihin asuntoihin toimintakuntoon asennettuina. \\n\\nAsukasetukoneet ovat laadukkaampia kodinkoneita, joita tarjotaan asukkaille, jotka ovat asuneet Sivakan asunnoissa yli 5 vuotta. Asukasetuina toimitetut koneet ovat olleet lähinnä keraamisia kiertoilmaliesiä, induktioliesiä ja astianpesukoneita.\\n\\nYksittäiskoneiden toimitusaika on enintään 24 tuntia tilauksesta. Toimitukseen sisältyy mahdollinen kiinteistön avaimen nouto Oulussa sijaitsevasta lukkoliikkeestä, jonne avain toimituksen jälkeen myös palautetaan. Mahdollisesta avaimen noudosta ilmoitetaan tilauksen yhteydessä.\\n\\nKuljetusmaksut sisältyvät toimitettavien laitteiden hintaan lukuun ottamatta liitteen 1. \\\"Vyöhykekartta\\\" mukaisia B-vyöhykkeellä sijaitsevia kohteita (Ylikiiminki, Haukipudas, Yli-Ii sekä Oulunsalon Salonpää), joihin toimitetuista tilauksista toimittaja voi periä erillisen kuljetusmaksun. Hankinnassa mukana olevista kohdekiinteistöistä noin 6 % sijaitsee B-vyöhykkeellä.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2025-08-18T08:05:07.098Z\", \"circularEconomy\": true, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": 4, \"winnerOrganisations\": \"Unit Scandinavia (1464584-6)//Gigantti Oy Ab (1523846-8)\", \"innovationConsidered\": false, \"lotResultTotalAmount\": 1700000.0, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": false, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": true, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": true, 