INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (96,'2023-127211','HILMA','RFP','OPEN','Turun seudun pääpyöräreittien opasteiden toteutus 2023, KU','Rakennushanke käsittää Turun seudun pääpyöräreittien opastuksen toteutuksen pyöräilyn pääreiteille 3, 5, 6, 7, 8 ja 23 sekä osittain reiteille 11 ja 21. Reitit sijoittuvat pääsääntöisesti ELYn hallinnoimalle verkolle, mutta niillä on myös kuntien verkoille sijoittuvia osuuksia. Reitti 3 sijoittuu Turkuun, Raisioon, Maskuun ja Nousiaisiin, reitti 5 Turkuun ja Ruskoon, reitti 6 Turkuun, reitti 7 Turkuun ja Lietoon, reitti 8 Turkuun, reitti 11 Kaarinaan ja Paimioon, reitti 21 Turkuun ja reitti 23 Turkuun, Raisioon, Kaarinaan ja Lietoon. Rakennustyön laajuus käy tarkemmin selville suunnitelmista. Urakkasuoritukseen kuuluu sopimusasiakirjoissa on määritelty kokonaisuus kaikkine tiejärjestelyineen, varusteineen ja laitteineen. Tarkempi kuvaus on tarjouspyynnön asiakirjoissa. Rakennushanke käsittää Turun seudun pääpyöräreittien opastuksen toteutuksen pyöräilyn pääreiteille 3, 5, 6, 7, 8 ja 23 sekä osittain reiteille 11 ja 21. Reitit sijoittuvat pääsääntöisesti ELYn hallinnoimalle verkolle, mutta niillä on myös kuntien verkoille sijoittuvia osuuksia. Reitti 3 sijoittuu Turkuun, Raisioon, Maskuun ja Nousiaisiin, reitti 5 Turkuun ja Ruskoon, reitti 6 Turkuun, reitti 7 Turkuun ja Lietoon, reitti 8 Turkuun, reitti 11 Kaarinaan ja Paimioon, reitti 21 Turkuun ja reitti 23 Turkuun, Raisioon, Kaarinaan ja Lietoon. Rakennustyön laajuus käy tarkemmin selville suunnitelmista. Urakkasuoritukseen kuuluu sopimusasiakirjoissa on määritelty kokonaisuus kaikkine tiejärjestelyineen, varusteineen ja laitteineen. Tarkempi kuvaus on tarjouspyynnön asiakirjoissa.','Elinkeino-, liikenne- ja ympäristökeskus','ANY',1,1,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-127211','[\"45200000\"]','[\"reitti\", \"turkuun\", \"raisioon\", \"lietoon\", \"kaarinaan\", \"turun\", \"seudun\", \"pääpyöräreittien\", \"rakennushanke\", \"käsittää\", \"opastuksen\", \"toteutuksen\", \"pyöräilyn\", \"pääreiteille\", \"osittain\", \"reiteille\", \"reitit\", \"sijoittuvat\", \"pääsääntöisesti\", \"elyn\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/elykeskus?id=456395&tpk=e3358403-fb41-4391-8c1c-53182a49b9f2\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-127211\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-127211\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"45200000\", \"currency\": null, \"deadline\": \"2023-05-19T09:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI1C1\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Rakennushanke käsittää Turun seudun pääpyöräreittien opastuksen toteutuksen pyöräilyn pääreiteille 3, 5, 6, 7, 8 ja 23 sekä osittain reiteille 11 ja 21. Reitit sijoittuvat pääsääntöisesti ELYn hallinnoimalle verkolle, mutta niillä on myös kuntien verkoille sijoittuvia osuuksia.   Reitti 3 sijoittuu Turkuun, Raisioon, Maskuun ja Nousiaisiin, reitti 5 Turkuun ja Ruskoon, reitti 6 Turkuun, reitti 7 Turkuun ja Lietoon, reitti 8 Turkuun, reitti 11 Kaarinaan ja Paimioon, reitti 21 Turkuun ja reitti 23 Turkuun, Raisioon, Kaarinaan ja Lietoon. Rakennustyön laajuus käy tarkemmin selville suunnitelmista.     Urakkasuoritukseen kuuluu sopimusasiakirjoissa on määritelty kokonaisuus kaikkine tiejärjestelyineen, varusteineen ja laitteineen. Tarkempi kuvaus on tarjouspyynnön asiakirjoissa.\", \"descriptionSv\": null, \"procedureType\": \"open\", \"estimatedValue\