INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (101,'2023-127167','HILMA','RFP','OPEN','Kivilompolon siivouspalvelut','Tulli pyytää tarjousta Kivilompolon siivoukseen liittyen 1.10.2023 alkaen. Sopimus päättyy 31.12.2028. Työt kohteessa alkavat 1.10.2023. Kivilompolon siivouspalveluihin valitaan yksi (1) sopimustoimittaja. Tilaaja ei sitoudu tiettyyn määrään tai arvoon. Kohteen esittelyn tarkemmasta ajankohdasta on kerrottu tarkemmin muut tiedot välilehdellä. Sopimuksen kohteena ovat seuraavat palvelut Kivilompolossa: 1. Ylläpitosiivous 2. Perussiivous 3. Tarvikehankinnat 4. Vaihtomatot','Tulli','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-127167','[\"90900000\"]','[\"kivilompolon\", \"tulli\", \"siivouspalvelut\", \"pyytää\", \"tarjousta\", \"siivoukseen\", \"liittyen\", \"alkaen\", \"sopimus\", \"päättyy\", \"työt\", \"kohteessa\", \"alkavat\", \"siivouspalveluihin\", \"valitaan\", \"yksi\", \"sopimustoimittaja\", \"tilaaja\", \"sitoudu\", \"tiettyyn\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/tulli?id=457113&tpk=8e2c0913-1f06-4d88-ba78-0833cfcb6e13\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-127167\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-127167\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"90900000\", \"currency\": null, \"deadline\": \"2023-06-05T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1D7\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Sopimuksen kohteena ovat seuraavat palvelut Kivilompolossa:  1. Ylläpitosiivous 2. Perussiivous 3. Tarvikehankinnat 4. Vaihtomatot\", \"descriptionSv\": null, \"procedureType\": \"open\", \"estimatedValue\": 0.0, \"expirationDate\": \"2023-06-05T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": null, \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": 0, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"200\", \"isPlan\": false, \"planId\": 0, \"titleEn\": null, \"titleFi\": \"Kivilompolon siivouspalvelut\", \"titleSv\": null, \"cpvCodes\": \"90900000\", \"currency\": null, \"deadline\": \"2023-06-05T09:00:00Z\", \"eFormsId\": null, \"isEForms\": false, \"mainType\": \"ContractNotices\", \"noticeId\": 127167, \"lowCarbon\": false, \"nutsCodes\": \"FI1D7\", \"titleOther\": null, \"isCancelled\": false, \"procedureId\": 0, \"biodiversity\": false, \"dateModified\": \"2023-05-03T07:00:10.368Z\", \"fullEFormsId\": null, \"noticeNumber\": \"2023-1271