INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (106,'2023-126861','HILMA','RFP','OPEN','Pienet LITUt Päijät-Häme 2023, KU','Urakka on kokonaishintapohjainen kokonaisurakka (KU). Pienten liikenneturvallisuutta parantavien kohteiden rakentaminen. Hankkeen toimenpiteillä pyritään vähentämään liikenneonnettomuuksien määrää, parantamaan liikenneturvallisuutta sekä lieventämään niiden vakavuusastetta. Hankkeessa parannetaan linja-autopysäkkejä sekä jalankulun yhteyksiä mm. parantamalla suojateitä. Kohteista osa toteutetaan optiokohteina. Yhteishankinta Heinolan, Iitin ja Lahden kanssa. Urakkasuoritukseen kuuluu sopimusasiakirjoissa on määritelty kokonaisuus kaikkine tiejärjestelyineen, varusteineen ja laitteineen. Tarkempi kuvaus on tarjouspyynnön asiakirjoissa. Pienten liikenneturvallisuutta parantavien kohteiden rakentaminen. Hankkeen toimenpiteillä pyritään vähentämään liikenneonnettomuuksien määrää, parantamaan liikenneturvallisuutta sekä lieventämään niiden vakavuusastetta. Hankkeessa parannetaan linja-autopysäkkejä sekä jalankulun yhteyksiä mm. parantamalla suojateitä. Kohteista osa toteutetaan optiokohteina. Kohteet sijaitsevat Heinolassa, Iitissä ja Lahdessa. Rakennusalueet ja niiden tarkka sijainti käy ilmi suunnitelma-asiakirjoista. Urakkaan kuuluu kohteen rakentaminen siinä laajuudessa kuin se on tarjouspyyntöasiakirjoissa määritelty kaikkien tiejärjestelyineen, varusteineen ja laitteineen. Urakan toteutus on vuoden 2023 aikana. Tarkempi kuvaus on tarjouspyynnön asiakirjoissa.','Elinkeino-, liikenne- ja ympäristökeskus','ANY',2,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-126861','[\"45200000\"]','[\"liikenneturvallisuutta\", \"rakentaminen\", \"niiden\", \"pienten\", \"parantavien\", \"kohteiden\", \"hankkeen\", \"toimenpiteillä\", \"pyritään\", \"vähentämään\", \"liikenneonnettomuuksien\", \"määrää\", \"parantamaan\", \"lieventämään\", \"vakavuusastetta\", \"hankkeessa\", \"parannetaan\", \"linja\", \"autopysäkkejä\", \"jalankulun\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/elykeskus?id=456738&tpk=1dbe3d88-2729-402b-b2b3-82ba5b6a58fc\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-126861\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-126861\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"45200000\", \"currency\": null, \"deadline\": \"2023-05-16T10:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1C3\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Pienten liikenneturvallisuutta parantavien kohteiden rakentaminen. Hankkeen toimenpiteillä pyritään vähentämään liikenneonnettomuuksien määrää, parantamaan liikenneturvallisuutta sekä lieventämään niiden vakavuusastetta.  Hankkeessa parannetaan linja-autopysäkkejä sekä jalankulun yhteyksiä mm. parantamalla suojateitä.  Kohteista osa toteutetaan optiokohteina.  Kohteet sijaitsevat Heinolassa, Iitissä ja Lahdessa. Rakennusalueet ja niiden tarkka sijainti käy ilmi suunnitelma-asiakirjoista.  Urakkaan kuuluu kohteen rakentaminen siinä laajuudessa kuin se on tarjouspyyntöasiakirjoissa määritelty kaikkien tiejärjestelyineen, varusteineen ja laitteineen.  Urakan toteutus on vuoden 2023 aikana.  Tarkempi kuvaus on tarjouspyynnön asiakirjoissa.\", \"descriptionSv\": null, \"procedureType\": \"open\", \"estimatedValue\": 0.0, \"expirationDate\": \"2023-05-16T10:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": null, \"solutionNewToBuyer\": false, \"employmentCondition\": fa