INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (107,'2023-126849','HILMA','OTHER','OPEN','Kardex-hissivarastoautomaatin integraatio Marelaan','Keski-Suomen hyvinvointialueen materiaalivarastoissa on käytössä CGI:n toimittama Marela-ohjelmisto, joka toimii materiaalihallinnon keskusvarastojen toiminnanohjausjärjestelmänä. Hyvinvointialueuudistuksessa Äänekosken kaupungilta hankintayksikölle siirtynyt Kardex-hissivarastoautomaatti tulee integroida Marela-järjestelmään, jotta Marela voi toimia logistisena toiminnanohjausjärjestelmänä myös sen osalta. Hankintayksikkö on pyytänyt CGI Suomi Oy:ltä tarjouksen Marelan ja Kardexin integraatiosta. Saatu tarjous sisältää tarvittavat lisenssit, käyttöönottoprojektin sekä ylläpidon. Hankinnan ennakoitu kokonaisarvo on 68.000 € (alv 0 %) laskettuna neljälle vuodelle. Hankintayksikkö toimii hankinnassa tilaajana ja tekee hankintapäätöksen Marelan ja Kardexin integraation suorahankinnasta CGI Suomi Oy:ltä.','Keski-Suomen hyvinvointialue','ANY',3,15,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-126849','[\"72000000\"]','[\"marela\", \"kardex\", \"keski\", \"suomen\", \"toimii\", \"toiminnanohjausjärjestelmänä\", \"hankintayksikkö\", \"suomi\", \"marelan\", \"kardexin\", \"hissivarastoautomaatin\", \"integraatio\", \"marelaan\", \"hyvinvointialueen\", \"materiaalivarastoissa\", \"käytössä\", \"toimittama\", \"ohjelmisto\", \"materiaalihallinnon\", \"keskusvarastojen\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-126849\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-126849\", \"lots\": [{\"id\": null, \"titleEn\": null, \"