INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (111,'2025-020839','HILMA','OTHER','OPEN','Helen-konsernin voimalaitoksiin, lämpökeskuksiin, sähköasemiin ja kiinteistöihin liittyvien rakennesuunnittelupalveluiden hankinta','Helen-konsernin voimalaitoksiin, lämpökeskuksiin, sähköasemiin ja kiinteistöihin liittyvien rakennesuunnittelupalveluiden hankinta Tämä on jälki-ilmoitus tehdystä hankinnasta. Hankinnan kohteena ovat rakennesuunnittelupalvelut Tilaajan kohteissa. Suunnittelupalvelun toimeksiannot liittyvät pääasiassa Tilaajan voimalaitoksiin, lämpö- ja jäähdytyslaitoksiin, energiavarastoihin, sähköasemiin, muuntamorakennuksiin, kytkinlaitoksiin, maanalaisiin laitoksiin ja kalliotunneleiden uudisrakentamiseen, muutos ja parannustöihin sekä saneerauksiin liittyvät rakennesuunnittelupalveluihin. Puitesopimuksen kesto on 3 vuotta, jonka jälkeen sopimusta on mahdollista (optiot) jatkaa kahdella (2) vuodella sekä yhdellä (1) vuodella (2 + 1 v.), yhteensä kolme (3) vuotta. Tilaajan tekemien puitejärjestelyyn perustuvien rakennesuunnittelutoimeksiantojen arvot vaihtelevat arviolta 10 000 - 300 000 euron (alv 0 %) välillä/toimeksianto. Yksittäiset toimeksiannot saattavat olla isompia. Hankinta sisältää yhteishankintaa. Helen Oy:n tytäryrityksillä kuten Helen Sähköverkko Oy:llä, Oy Mankala Ab:lla ja Helsingin Energiatunnelit Oy:llä on oikeus tehdä toimeksiantoja tulevan puitesopimuksen ehdoilla. Palvelun toimeksiannot liittyvät pääasiassa Helen Oy:n ja sen tytäryrityksen Helen Sähköverkko Oy:n tarpeisiin. Helen Oy:n muut tytäryritykset tekevät toimeksiantoja vähäisemissä määrin.,','Helen Oy','ANY',5,4,NULL,NULL,NULL,'EU