INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (115,'2025-020955','HILMA','RFP','OPEN','HUS 797-2023 / Kuulovammaisten henkilöiden kotiin asennettavat apuvälineet sekä niiden asennus-, vaihto- ja huoltopalvelut','HUS 797-2023 / Kuulovammaisten henkilöiden kotiin asennettavat apuvälineet sekä niiden asennus-, vaihto- ja huoltopalvelut HANKINNAN KOHDE HUS-yhtymä (jäljempänä HUS) kilpailuttaa HUSin Apuvälinekeskuksen (jäljempänä \"Tilaaja\") kuulovammaisten henkilöiden kotiin asennettavat apuvälineet sekä niiden asennus-, vaihto- ja huoltopalvelut. Tarvittavat apuvälineet on tarkemmin määritelty tarjouspyynnön liitteessä 1 (tarjouslomake). Hankinnan keskeinen sisältö: - Tarvittavien apuvälineiden (ks. liite 1) toimitus - Apuvälineiden asennus, vaihto ja huolto - Apuvälineiden käytön opastus - Nykyisin käytössä olevien apuvälineiden korjaus, vaihto ja huolto - Asiakkailta palautuneiden käyttökelpoisten apuvälineiden säilytys ja uudelleenasennus toisiin työkohteisiin. - Asennus-, vaihto- ja huoltotöissä mahdollisesti syntyvien jätteiden poiskuljetus sekä korjauskohteen tarvittava jälkisiivous Lisähankintamahdollisuutena hankintaan sisältyy olemassa olevien palovaroittimien paristojen kunnon tarkastus ja paristojen vaihto. HANKINTAYKSIKKÖ HUSin Apuvälinekeskus vastaa erikoissairaanhoidon, osasta Länsi-Uudenmaan hyvinvointialueen (Espoo, Raasepori, Hanko, Inkoo) sekä Keski-Uudenmaan hyvinvointialueen tarvitsemien apuvälineiden hankinnasta. Lisäksi Apuvälinekeskus vastaa Länsi-Uudenmaan hyvinvointialueella Espoon alueen vammaispalvelun kodinmuutostöistä. HANKINTASOPIMUS Tämän tarjouspyynnön perusteella tullaan valitsemaan yksi (1) sopimuskumppani, jonka kanssa allekirjoitetaan tarjouspyynnön liitteenä oleva hankintasopimus. HANKINNAN ENNAKOITU KOKONAISARVO Hankinnan ennakoitu kokonaisarvo on laskettu neljälle (4) vuodelle (alv 0 %). Tilaajalla ei ole määräostovelvoitetta (ts. arvio sopimuskauden hankintamääristä ei sido Tilaajaa). Tilausmäärät voivat vaihdella vuosittain. SOPIMUSKAUSI Sopimus on voimassa kaksi (2) vuotta määräaikaisena, jonka jälkeen se jatkuu toistaiseksi voimassaolevana.,','HUS-yhtymä','ANY',3,4,NULL,NULL,280000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2025-020955','[\"33196000\"]','[\"vaihto\", \"apuvälineiden\", \"asennus\", \"apuvälineet\", \"hankinnan\", \"kuulovammaisten\", \"henkilöiden\", \"kotiin\", \"asennettavat\", \"niiden\", \"huoltopalvelut\", \"tarjouspyynnön\", \"uudenmaan\", \"yhtymä\", \"jäljempänä\", \"husin\", \"huolto\", \"olevien\", \"paristojen\", \"apuvälinekeskus\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/huslogistiikka?id=499487&tpk=b009fdfa-5b4a-48b1-a9b1-9768145f8658\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2025-020955\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-20955\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"HUS 797-2023 / Kuulovammaisten henkilöiden kotiin asennettavat apuvälineet sekä niiden asennus-, vaihto- ja huoltopalvelut\", \"titleSv\": \"\", \"cpvCodes\": \"33196000\", \"currency\": \"EUR\", \"deadline\": \"2025-03-31T07:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"HANKINNAN KOHDE\\n\\nHUS-yhtymä (jäljempänä HUS) kilpailuttaa HUSin Apuvälinekeskuksen (jäljempänä \\\"Tilaaja\\\") kuulovammaisten henkilöiden kotiin asennettavat apuvälineet sekä niiden asennus-, vaihto- ja huoltopalvelut. Tarvittavat apuvälineet on tarkemmin määritelty tarjouspyynnön liitteessä 1 (tarjouslomake).\\n\\nHankinnan keskeinen sisältö:\\n\\n- Tarvittavien apuvälineiden (ks. liite 1) toimitus\\n- Apuvälineiden asennus, vaihto ja huolto\\n- Apuvälineiden käytön opastus\\n- Nykyisin käytössä olevien apuvälineiden korjaus, vaihto ja huolto\\n- Asiakkailta palautuneiden käyttökelpoisten apuvälineiden säilytys ja uudelleenasennus toisiin työkohteisiin.\\n- Asennus-, vaihto- ja huoltotöissä mahdollisesti syntyvien jätteiden poiskuljetus sekä korjauskohteen tarvittava jälkisiivous\\n\\nLisähankintamahdollisuutena hankintaan sisältyy olemassa olevien palovaroittimien paristojen kunnon tarkastus ja paristojen vaihto.\\n\\nHANKINTAYKSIKKÖ\\n\\nHUSin Apuvälinekeskus vastaa erikoissairaanhoidon, osasta Länsi-Uudenmaan hyvinvointialueen (Espoo, Raasepori, Hanko, Inkoo) sekä Keski-Uudenmaan hyvinvointialueen tarvitsemien apuvälineiden hankinnasta. Lisäksi Apuvälinekeskus vastaa Länsi-Uudenmaan hyvinvointialueella Espoon alueen vammaispalvelun kodinmuutostöistä.\\n\\nHANKINTASOPIMUS\\n\\nTämän tarjouspyynnön perusteella tullaan valitsemaan yksi (1) sopimuskumppani, jonka kanssa allekirjoitetaan tarjouspyynnön liitteenä oleva hankintasopimus.\\n\\nHANKINNAN ENNAKOITU KOKONAISARVO\\n\\nHankinnan ennakoitu kokonaisarvo on laskettu neljälle (4) vuodelle (alv 0 %). Tilaajalla ei ole määräostovelvoitetta (ts. arvio sopimuskauden hankintamääristä ei sido Tilaajaa). Tilausmäärät voivat vaihdella vuosittain. \\n\\nSOPIMUSKAUSI\\n\\nSopimus on voimassa kaksi (2) vuotta määräaikaisena, jonka jälkeen se jatkuu toistaiseksi voimassaolevana.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 280000.0, \"expirationDate\": \"2025-03-31T07:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": true, \"lotResultTotalAmount\": null, \"justWorkingConditions\":