INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (118,'2025-020793','HILMA','RFI','OPEN','Bentley Systems:n Oasis Montaj, Leapfrog Geo, Aarhus Geosoftware -ohjelmistojen sekä VOXl ja Central -pilvipalvelujen käyttöoikeuksien suorahankinta.','Bentley Systems:n Oasis Montaj, Leapfrog Geo, Aarhus Geosoftware -ohjelmistojen sekä VOXl ja Central -pilvipalvelujen käyttöoikeuksien suorahankinta. Kyseessä on Bentley Systems:n Oasis Montaj, Leapfrog Geo sekä Aarhus Geosoftware -ohjelmistojen sekä VOXI- ja Central pilvipalvelujen käyttöoikeuksien suorahankinta. Hankinta voi sisältää lisäksi muiden ohjelmistotoimittajan GTK:ssa nykyisellään käytössä olevien tai tarvittavien ohjelmistojen ja palveluiden vuokrausta tai ylläpidon hankintaa. GTK:n tuleva käyttötarve kattaa useamman vuoden. Suorahankinnalla neuvottelemalla toimittajan kanssa tarkemmista sopimusehdoista geofysiikan ja geologisen mallintamisen ohjelmistokokonaisuuden hankitaan 1.3.2025 alkavalle hankintakaudelle. Bentley Systems International Limited (Bentley) tarjoaa valikoiman erikoistuneita ohjelmistotuotteita, joita Geologian tutkimuskeskus on käyttänyt yli 30 vuoden ajan. Ohjelmiston toimittajalla on maailmanlaajuinen yksinoikeus ohjelmistoihin ja sen jakeluun eikä markkinoilla ole järkeviä vaihtoehtoisia tai korvaavia ohjelmistoja, ohjelmistokokonaisuuksia tai muita käyttävissä olevia ratkaisuja, joita hankintayksikön toiminnan kannalta olisi mahdollista käyttää. Ohjelmistokokonaisuus on Geologian tutkimuskeskuksen toiminnan kannalta välttämätön.,','Geologian tutkimuskeskus','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2025-020793','[\"48100000\"]','[\"bentley\", \"systems\", \"ohjelmistojen\", \"geologian\", \"oasis\", \"montaj\", \"leapfrog\", \"aarhus\", \"geosoftware\", \"central\", \"pilvipalvelujen\", \"käyttöoikeuksien\", \"suorahankinta\", \"tutkimuskeskus\", \"voxl\", \"vuoden\", \"joita\", \"toiminnan\", \"kannalta\", \"kyseessä\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2025-020793\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-20793\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Bentley Systems:n Oasis Montaj, Leapfrog Geo, Aarhus Geosoftware -ohjelmistojen sekä VOXl  ja Central -pilvipalvelujen käyttöoikeuksien suorahankinta.\", \"titleSv\": \"\", \"cpvCodes\": \"48100000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": null, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Kyseessä on Bentley Systems:n Oasis Montaj, Leapfrog Geo sekä Aarhus Geosoftware -ohjelmistojen sekä VOXI- ja Central pilvipalvelujen käyttöoikeuksien suorahankinta. Hankinta voi sisältää lisäksi muiden ohjelmistotoimittajan GTK:ssa nykyisellään käytössä olevien tai tarvittavien ohjelmistojen ja palveluiden vuokrausta tai ylläpidon hankintaa. GTK:n tuleva käyttötarve kattaa useamman vuoden.\\n\\nSuorahankinnalla neuvottelemalla toimittajan kanssa tarkemmista sopimusehdoista geofysiikan ja geologisen mallintamisen ohjelmistokokonaisuuden hankitaan 1.3.2025 alkavalle hankintakaudelle. Bentley Systems International Limited (Bentley) tarjoaa valikoiman erikoistuneita ohjelmistotuotteita, joita Geologian tutkimuskeskus on käyttänyt yli 30 vuoden ajan.\\n\\nOhjelmiston toimittajalla on maailmanlaajuinen yksinoikeus ohjelmistoihin ja sen jakeluun eikä markkinoilla ole järkeviä vaihtoehtoisia tai korvaavia ohjelmistoja, ohjelmistokokonaisuuksia tai muita käyttävissä olevia ratkaisuja, joita hankintayksikön toiminnan kannalta olisi mahdollista käyttää. Ohjelmist