INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (278,'DEMO-TRANS-001','TED','RFP','OPEN','Public Transport Ticketing and Journey Planner Platform — Helsinki Region','HSL (Helsinki Region Transport Authority) is procuring a new integrated public transport ticketing and journey planning platform. The system must support MaaS integration, open GTFS-RT data feeds and account-based ticketing. Contract value estimated EUR 18M, duration 5 years.','HSL – Helsinki Region Transport','LARGE',1,1,'2026-09-02','2026-11-14',18000000.00,'EUR','https://ted.europa.eu/en/notice/-/detail/2026-DEMO-T1','[\"72000000\", \"60000000\"]','[\"MaaS\", \"ticketing\", \"public transport\", \"GTFS\", \"journey planning\"]','procurement@hsl.fi','+358 9 4766 4000','[{\"url\": \"https://ted.europa.eu/en/notice/2026-DEMO-T1/pdf\", \"name\": \"Contract Notice PDF (ENG)\"}, {\"url\": \"https://ted.europa.eu/fi/notice/2026-DEMO-T1/pdf\", \"name\": \"Contract Notice PDF (Finnish)\"}, {\"url\": \"https://ted.europa.eu/en/notice/-/detail/2026-DEMO-T1\", \"name\": \"Technical Requirements v1.2 (PDF)\"}]','{\"source\": \"demo_seed\"}',87,NULL,'2026-09-04 10:46:24','2026-09-04 10:46:24');
