INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (283,'DEMO-EDU-002','TED','RFI','OPEN','Prior Information Notice: National Research Computing Infrastructure 2027','CSC – IT Center for Science announces a Prior Information Notice for the next generation national research computing infrastructure. The procurement will cover HPC cluster hardware, GPU compute capacity, petascale storage and interconnect. Estimated total value EUR 120M over 7 years.','CSC – IT Center for Science','LARGE',6,1,'2026-09-04','2026-12-01',120000000.00,'EUR','https://ted.europa.eu/en/notice/-/detail/2026-DEMO-EDU2','[\"72000000\", \"30000000\"]','[\"HPC\", \"supercomputer\", \"research computing\", \"GPU\", \"data center\"]','hankinta@csc.fi','+358 9 457 2001','[{\"url\": \"https://ted.europa.eu/en/notice/2026-DEMO-EDU2/pdf\", \"name\": \"PIN Notice PDF (ENG)\"}, {\"url\": \"https://ted.europa.eu/fi/notice/2026-DEMO-EDU2/pdf\", \"name\": \"PIN Notice PDF (Finnish)\"}, {\"url\": \"https://ted.europa.eu/en/notice/-/detail/2026-DEMO-EDU2\", \"name\": \"Technical Consultation Document\"}]','{\"source\": \"demo_seed\"}',90,NULL,'2026-09-04 10:46:24','2026-09-04 10:46:24');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (284,'DEMO-FIN-001','HILMA','RFP','OPEN','Tarjouspyyntö: Taloushallinnon SaaS-järjestelmä kunnille','Tampereen kaupunki johtavana hankintayksikkönä kilpailuttaa taloushallinnon SaaS-järjestelmän 12 kunnalle. Hankinta kattaa kirjanpidon, laskutuksen, budjetoinnin ja raportoinnin. Arvioitu kokonaisarvo 2 M€ / 4 vuotta.','Tampereen kaupunki (yhteiShankinta)','SME',1,3,'2026-07-28','2026-09-25',2000000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-DEMO-FIN1','[\"72000000\", \"66000000\"]','[\"ERP\", \"financial management\", \"SaaS\", \"accounting\", \"municipal\"]','yhteiShankinnat@tampere.fi','+358 3 5656 0000','[{\"url\": \"https://tarjouspalvelu.fi/tampere?id=600600\", \"name\": \"Tarjouspyyntö (PDF)\"}, {\"url\": \"https://tarjouspalvelu.fi/tampere?id=600600&att=req\", \"name\": \"Liite 1 – Vaatimusmäärittely (PDF)\"}, {\"url\": \"https://tarjouspalvelu.fi/tampere?id=600600&att=contract\", \"name\": \"Liite 2 – Sopimusluonnos (PDF)\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-DEMO-FIN1\", \"name\": \"HILMA Notice\"}]','{\"source\": \"demo_seed\"}',78,NULL,'2026-09-04 10:46:24','2026-09-04 10:46:24');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (285,'DEMO-DEF-001','TED','RFP','OPEN','Drone Detection and Counter-UAS System for Border Guard','The Finnish Border Guard is procuring a drone detection and counter-UAS system for deployment along the eastern border. The system must integrate with existing surveillance infrastructure, support multi-sensor fusion and AI-based classification. Security-cleared suppliers only. Estimated EUR 9M.','Finnish Border Guard (Rajavartiolaitos)','LARGE',1,13,'2026-08-30','2026-11-07',9000000.00,'EUR','https://ted.europa.eu/en/notice/-/detail/2026-DEMO-DEF1','[\"38000000\", \"72000000\"]','[\"drone detection\", \"counter-UAS\", \"border security\", \"AI surveillance\"]','hankinta@raja.fi','+358 295 421 000','[{\"url\": \"https://ted.europa.eu/en/notice/2026-DEMO-DEF1/pdf\", \"name\": \"Contract Notice PDF (ENG)\"}, {\"url\": \"https://ted.europa.eu/fi/notice/2026-DEMO-DEF1/pdf\", \"name\": \"Contract Notice PDF (Finnish)\"}, {\"url\": \"https://ted.europa.eu/en/notice/-/detail/2026-DEMO-DEF1\", \"name\": \"Security Requirements Document\"}]','{\"source\": \"demo_seed\"}',80,NULL,'2026-09-04 10:46:24','2026-09-04 10:46:24');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (286,'DEMO-OULU-001','FinnishCities','RFP','OPEN','Oulun älykaupunki: IoT-sensorit ja datanhallinnan alusta','Oulun kaupunki kilpailuttaa IoT-sensoreiden laajennuksen ja datanhallinnan alustan älykaupunkistrategian toteuttamiseksi. Hankinta sisältää 2000 uutta ilmanlaatu-, liikenteen ja energiamittaria sekä pilvi-alustan datan käsittelyyn.','Oulun kaupunki / Yhdyskunta- ja ympäristöpalvelut','SME',1,5,'2026-08-05','2026-10-05',1200000.00,'EUR','https://www.ouka.fi/hankintailmoitukset/2026-DEMO-OULU1','[\"38000000\", \"72000000\"]','[\"IoT\", \"smart city\", \"sensors\", \"data platform\", \"air quality\"]','hankinnat@ouka.fi','+358 8 558 410 00','[{\"url\": \"https://tarjouspalvelu.fi/oulu?id=600700\", \"name\": \"Tarjouspyyntö (PDF)\"}, {\"url\": \"https://tarjouspalvelu.fi/oulu?id=600700&att=arch\", \"name\": \"IoT-arkkitehtuuri (PDF)\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-DEMO-OULU1\", \"name\": \"HILMA Notice\"}]','{\"source\": \"demo_seed\"}',77,NULL,'2026-09-04 10:46:24','2026-09-04 10:46:24');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (287,'DEMO-TURKU-001','FinnishCities','RFI','OPEN','Tietopyyntö: Digitaalinen kaksonen Turun satamalle','Turun Satama Oy pyytää tietoja digitaalisen kaksosen (digital twin) toimittajilta sataman operatiivista suunnittelua varten. Ratkaisu integroituu AIS-järjestelmään ja laiturinohjausjärjestelmiin. Tietopyyntö edeltää hankintamenettelyä.','Turun Satama Oy','SME',1,14,'2026-08-12','2026-10-12',NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-DEMO-TURKU1','[\"72000000\", \"63000000\"]','[\"digital twin\", \"port\", \"maritime\", \"simulation\", \"AIS\"]','kilpailutus@portofturku.fi','+358 2 267 3100','[{\"url\": \"https://tarjouspalvelu.fi/turkusatama?id=600800\", \"name\": \"Tietopyyntö (PDF)\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-DEMO-TURKU1\", \"name\": \"HILMA Notice\"}]','{\"source\": \"demo_seed\"}',73,NULL,'2026-09-04 10:46:24','2026-09-04 10:46:24');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (438,'57b18ddbc5d88cb84f0e','FinnishCities','RFP','OPEN','Tarjouspalvelu-portaali','Pirkanmaan hyvinvointialue vastaa sosiaali- ja terveydenhuollosta sekä pelastustoimesta. Asiakkaille kohdentuvien palvelujen lisäksi hyvinvointialue hankkii palvelutuotannon tarvitsemia palveluja, aineita, tarvikkeita ja tavaroita. Hankintojen arvo on hyvinvointialueella noin 1,4 miljardia euroa vuodessa.','City of Tampere – Wellbeing','ANY',3,3,NULL,NULL,NULL,'EUR','http://tarjouspalvelu.fi/Default/Index',NULL,'[\"hyvinvointialue\", \"tarjouspalvelu\", \"portaali\", \"pirkanmaan\", \"vastaa\", \"sosiaali\", \"terveydenhuollosta\", \"pelastustoimesta\", \"asiakkaille\", \"kohdentuvien\", \"palvelujen\", \"lisäksi\", \"hankkii\", \"palvelutuotannon\", \"tarvitsemia\", \"palveluja\", \"aineita\", \"tarvikkeita\", \"tavaroita\", \"hankintojen\"]',NULL,NULL,NULL,'{\"text\": \"Pirkanmaan hyvinvointialue vastaa sosiaali- ja terveydenhuollosta sekä pelastustoimesta. Asiakkaille kohdentuvien palvelujen lisäksi hyvinvointialue hankkii palvelutuotannon tarvitsemia palveluja, aineita, tarvikkeita ja tavaroita. Hankintojen arvo on hyvinvointialueella noin 1,4 miljardia euroa vuodessa. Pirkanmaan hyvinvointialueen hankinnat löytyvät tarjouspalvelu.fi-sivustolta Tuomi Logistiikka Oy:n julkaisemana: Tarjouspalvelu-portaali Kansallisen ja EU-kynnysarvon ylittävät hankinnat ilmoitetaan HILMAssa: Hilma - Julkiset hankinnat Keskeiset asiakirjat Pirkanmaan hyvinvointialueen hankintaohjelma 2026 - 2029 (pdf) Pirkanmaan hyvinvointialueen hankintasuunnitelma 2026 - 2027 (pdf) Sosiaalihuollon kirjaamisen opas (pdf, Pirkanmaan hyvinvointialueelle palveluja tuottaville yksityisille palveluntuottajille Kantaan kirjaamisen tueksi)\"}',47,NULL,'2026-09-04 17:00:16','2026-09-04 17:00:16');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (439,'04f2d224b07356c677d3','FinnishCities','RFP','OPEN','Pirha tutkihankintoja.fi-palvelussa','','City of Tampere – Wellbeing','ANY',3,3,NULL,NULL,NULL,'EUR','https://tutkihankintoja.fi/hankintayksikot/Pirkanmaan%20hyvinvointialue',NULL,'[\"pirha\", \"tutkihankintoja\", \"palvelussa\", \"city\", \"tampere\", \"wellbeing\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Pirha tutkihankintoja.fi-palvelussa\"}',42,NULL,'2026-09-04 17:00:16','2026-09-04 17:00:16');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (440,'dd85f8fd0ea589a14fdc','FinnishCities','RFP','OPEN','Hankintakalenteri','Tarjoamme kuntalaisille erilaisia palveluja ja kilpailutamme ne hankintalain ja kaupungin oman hankintaohjeistuksen mukaisesti. Tehtäviimme kuuluu myös hankkia palveluja ja tavaroita omaan palveluntuotantoomme. Hankinnoilla haluamme tukea paikallista yrittäjyyttä ja elinvoiman kasvua.','City of Kouvola','ANY',10,14,NULL,NULL,NULL,'EUR','https://www.kouvola.fi/wp-content/uploads/2026/05/hankintakalenteri-2026.xlsx',NULL,'[\"palveluja\", \"hankintakalenteri\", \"tarjoamme\", \"kuntalaisille\", \"erilaisia\", \"kilpailutamme\", \"hankintalain\", \"kaupungin\", \"oman\", \"hankintaohjeistuksen\", \"mukaisesti\", \"tehtäviimme\", \"kuuluu\", \"hankkia\", \"tavaroita\", \"omaan\", \"palveluntuotantoomme\", \"hankinnoilla\", \"haluamme\", \"tukea\"]',NULL,NULL,NULL,'{\"text\": \"Tarjoamme kuntalaisille erilaisia palveluja ja kilpailutamme ne hankintalain ja kaupungin oman hankintaohjeistuksen mukaisesti. Tehtäviimme kuuluu myös hankkia palveluja ja tavaroita omaan palveluntuotantoomme. Hankinnoilla haluamme tukea paikallista yrittäjyyttä ja elinvoiman kasvua. Hankintakalenteri Näet suunnitteilla olevat hankinnat ja voimassa olevat vuosisopimukset hankintakalenterista. Hankintakalenterin tavoitteena on lisätä kaupungin ja yrittäjien välistä vuoropuhelua. Jos löydät kalenterista sinua kiinnostavan hankinnan, ota yhteyttä kalenterissa nimettyyn yhteyshenkilöön. Tutustu hankintakalenteriin tästä (xlsx, 49 kt) Tarjouspyynnöt Katso kaikki voimassa olevat avoimet tarjouspyynnöt Cloudia tarjouspalvelusta . Hankintaohjeistus Ohjeistus koostuu hankintaohjelmasta, hankintaohjeesta ja hankintakäsikirjasta. Hankintaohjelma (pdf, 708 kt) perustuu kaupunkistrategiaan. Hankintaohjelmassa linjataan, kuinka hankinnoilla pyrimme lisäämään kaupungin elinvoimaa ja hyvinvointia. Ohjelman tavoitteena on myös hankintatoimintamme kehittäminen. Hankintaohje sisältää yleisiä ohjeita hankintavaltuuksista, hankintaohjelman toimeenpanosta sekä sopimusaikaisesta toiminnasta. Hankintaohj\"}',47,NULL,'2026-09-04 17:16:30','2026-09-04 17:16:30');
