INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (443,'4b96b47277cb26691e12','FinnishCities','RFP','OPEN','Hankinta-asiamiespalvelu','','City of Kouvola','ANY',10,14,NULL,NULL,NULL,'EUR','https://kinno.fi/hankinta-asiamiespalvelu',NULL,'[\"hankinta\", \"asiamiespalvelu\", \"city\", \"kouvola\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinta-asiamiespalvelu\"}',42,NULL,'2026-09-04 17:16:30','2026-09-04 17:16:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (444,'1d5962c166ace9f4ada9','FinnishCities','RFP','OPEN','Hankinta-asiamiehen uutiskirje 1/2022','','City of Kouvola','ANY',10,14,NULL,NULL,NULL,'EUR','http://uutiskirje.kinno.fi/a/s/188749449-33a3f01ba66064a40b523d5f7f908421/4947103',NULL,'[\"hankinta\", \"asiamiehen\", \"uutiskirje\", \"city\", \"kouvola\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinta-asiamiehen uutiskirje 1/2022\"}',42,NULL,'2026-09-04 17:16:30','2026-09-04 17:16:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (464,'2026-056258','HILMA','RFI','OPEN','Kutsu markkinainfoon ja tekniseen vuoropuheluun: Taloushallinto- ja HR-ratkaisujen tulevat hankinnat','Espoon seudun koulutuskuntayhtymä Omnia (hankintayksikkö) suunnittelee talous- ja HR-järjestelmiensä ja -palveluiden kilpailutusta. Omnia kutsuu kiinnostuneita toimittajia osallistumaan markkinainfotilaisuuteen ja tekniseen vuoropuheluun koskien Omnian tulevia talous- ja HR-ratkaisujen hankintoja. MARKKINAINFOTILAISUUS Markkinainfo järjestetään 1.10.2026 klo 15.00–16.00 etätilaisuutena Teamsillä. Tilaisuudessa esitellään: - hankintojen nykyinen valmistelutilanne - alustavat tavoitteet ja aikataulut - suunniteltu kilpailutusmalli - keskeiset hankinnan kohteet ja rajaukset TEKNINEN VUOROPUHELU Markkinainfon jälkeen Omnia tarjoaa halukkaille toimittajille mahdollisuuden osallistua hankintojen valmistelua tukevaan tekniseen vuoropuheluun. Tekniset vuoropuhelut toteutetaan ensisijaisesti kirjallisesti ja hankintakohtaisesti siten, että taloushallinnon ja HR-ratkaisujen hankinnat käsitellään erillisinä kokonaisuuksina. Teknisten vuoropuhelujen tarkoituksena on kerätä markkinoiden näkemyksiä hankinnan valmistelun tueksi sekä mahdollistaa alustavien hankinta-asiakirjojen kommentointi ennen varsinaisten kilpailutusten käynnistämistä. Kommentoitava aineisto voi sisältää esimerkiksi alustavia vaatimusmäärittelyjä, sopimusluonnoksia ja arviointimalleja. Tekniseen vuoropuheluun osallistuville toimittajille toimitetaan erikseen kommentoitava aineisto sekä tarkemmat ohjeet ja aikataulu. Tekniseen vuoropuheluun on mahdollista osallistua, vaikka ei osallistuisi markkinainfotilaisuuteen. Hankintayksikkö voi pyytää teknisen vuoropuhelun yhteydessä toimittajilta myös alustavia arvioita ratkaisujen kustannustasoista hankinnan ennakoidun arvon arvioinnin tueksi. ILMOITTAUTUMINEN Ilmoittautuminen markkinainfoon ja/tai tekniseen vuoropuheluun viimeistään 30.9.2026 klo 16.00: https://forms.cloud.microsoft/e/TU1Wnxnscg, Taloushallintopalveluiden ja -järjestelmien hankinta SaaS-palveluna Hankinnan kohteena tulevat olemaan Omnian taloushallinnon järjestelmät sekä niihin liittyvät palvelut. Kilpailutuksen piiriin kuuluvat Omnian tämänhetkisten suunnitelmien mukaan seuraavat osa-alueet: osto- ja myyntilasku, kirjanpito mukaan lukien käyttöomaisuuden hallinta, talouden suunnittelu ja raportointi, maksuliikenne ja arkistointi, sekä optiona kassatoiminnot, henkilöstösuunnittelun toiminnot sekä likviditeetin hallinta- ja seurantajärjestelmä. Omnian tavoiteaikataulun mukaisesti talouden suunnittelu tulisi pystyä aloittamaan uudella järjestelmällä syksyllä 2027 ja täysimittainen tuotantokäyttö 1.1.2028. Käyttöönottoprojektin aikana tulee rakentaa tarvittavat integraatiot sekä kouluttaa henkilöstö järjestelmien käyttöön., HR-järjestelmäkokonaisuus SaaS-palveluna ja palkanlaskenta kokonaispalveluna Hankinnan tavoitteena on löytää luotettava ja nykyaikainen palkanlaskennan kumppani, jolta saadaan palkanlaskennan palvelu kokonaispalveluna, laadukas järjestelmäkokonaisuus sekä hyvät käyttömahdollisuudet eri käyttäjäryhmille esim. HR-käyttäjille, esihenkilöille ja työntekijöille. Palkanlaskennan kokonaispalvelulla tarkoitetaan, että palkanlaskennan kumppani tekee palkanlaskennan alusta loppuun sekä hoitaa viranomaisraportoinnit ja muun palkanlaskentaan liittyvän kolmansien osapuolten raportoinnin (sisältäen palkka-avoimuusdirektiivin vaatimusten mukaisen raportoinnin) sekä toimenpiteet Omnian valtuutuksella. Kokonaispalvelun tulee tukea henkilöstön johtamista, työnantajamielikuvaa ja esihenkilötyötä. Tärkeitä ominaisuuksia ovat mm. SSO-kirjautuminen, SaaS-ympäristö sekä käyttäjäystävällisyys. Toimittaja myös kehittää palveluaan ja tarjoamaansa järjestelmää aktiivisesti. Käyttäjien käyttöliittymän sekä palkkapalveluiden käyttökieli on suomi. Ratkaisun on oltava tietosuojalainsäädännön (GDPR) mukainen. Tiedon tallentamisen, tiedonhaun ja raporttitiedon tuottamisen tulee olla käyttäjälähtöistä, sujuvaa ja helppoa. Käytettävien järjestelmien ja sovellusten toimintojen tulee aktiivisesti tukea ja ohjata käyttäjiään. Järjestelmään kertyvien tietojen on oltava käyttäjilleen tehokkaasti saatavilla, käyttipä niitä toimistotiloissa tai etätyöskentelyssä. Käyttöliittymän/työpöytänäkymät tulee voida muokata helposti eri käyttötarpeisiin sopiviksi: esimerkiksi HR-käyttäjälle, esihenkilöille ja taloudelle ovat tarjolla kunkin tehtävän hoitoa tukevat näkymät.,','Espoon seudun koulutuskuntayhtymä Omnia','SME',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056258','[\"48000000\", \"48450000\", \"48812000\", \"72000000\", \"79211100\", \"79631000\", \"48442000\"]','[\"tekniseen\", \"vuoropuheluun\", \"omnian\", \"hankinnan\", \"tulee\", \"palkanlaskennan\", \"ratkaisujen\", \"omnia\", \"järjestelmien\", \"saas\", \"markkinainfoon\", \"tulevat\", \"hankinnat\", \"espoon\", \"seudun\", \"koulutuskuntayhtymä\", \"hankintayksikkö\", \"talous\", \"markkinainfotilaisuuteen\", \"hankintojen\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/omnia?id=623663&tpk=dadae702-2393-47e4-afc5-bffbb478a2ad\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056258\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56258\", \"lots\": [{\"id\": \"PAR-0001\", \"titleEn\": \"\", \"titleFi\": \"Taloushallintopalveluiden ja -järjestelmien hankinta SaaS-palveluna\", \"titleSv\": \"\", \"cpvCodes\": \"48000000 48442000 48812000 72000000 79211100\", \"currency\": null, \"deadline\": null, \"lowCarbon\": null, \"nutsCodes\": \"\", \"titleOther\": \"\", 