INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (465,'2026-056257','HILMA','RFP','OPEN','Tulostus ja informaatiopalvelut','Tulostus ja informaatiopalvelut Numera Palvelut Oy (myöhemmin Numera tai Hankintayksikkö) pyytää tarjoustanne Tulostus ja informaatiopalveluita (Monitoimilaitteet ja niihin liittyvät palvelut) koskevaan yhteishankintaan tarjouspyyntöasiakirjojen mukaan. Hankintaa ei ole jaettu osakokonaisuuksiin, vaan valitaan yksi toimittaja, jonka kanssa Numera laatii keskinäiset hankintasopimukset.: Kilpailutus suoritetaan avoimella menettelyllä. Kilpailutuksen valintaperusteena käytetään kokonaistaloudellista edullisuutta ja vertailuperusteena [parasta hinta-laatusuhdetta]. Tarkemmat tiedot pisteytyksestä ja vertailuperusteista on esitetty tarjouspyynnön osiossa Hankinnan kohteen kriteerit. Mikäli useampi tarjoaja ansaitsee tarjouksellaan täsmälleen saman pistemäärän, Hankintayksikkö arpoo voittajan. Arvonta on hankitalain oikeuskäytännössä hyväksytty tapa. Rinnakkaisia tarjouksia, vaihtoehtoisia tarjouksia ei hyväksytä. Hankintasopimus on voimassa määräaikaisena kaksi (2) vuotta. Sen jälkeen sopimus jatkuu toistaiseksi voimassa olevana. Yhteishankintaa käyttävät ja siihen mahdollisesti sopimuskauden aikana mukaan tulevat Numeran asiakasyhteisöt on ilmoitettu sopimusluonnoksen liitteellä yksi (1). Hankintasopimus astuu voimaan hankintapäätöksen tultua lainvoimaiseksi tai markkinaoikeuden antaessa hankintapäätökselle täytäntöönpanoluvan ja molempien sopijapuolten allekirjoitettua kirjallisen hankintasopimuksen. Sopimuksen irtisanomisaika on molempien sopijapuolten osalta kuusi (6) kuukautta. Sopimuksessa mukana oleva asiakas voi irtisanoa sopimuksen osaltaan 6 kk irtisanomisajalla. Tarjoaja sitoutuu tarjouksellaan kaikkiin tarjouspyyntöasiakirjojen sekä mahdollisesti hankintamenettelyn aikana annettujen lisätietojen mukaisiin ehtoihin. Hankintayksiköllä on oikeus tarkastaa tarjoajan tarjousasiakirjoissaan antamat tiedot ennen hankintapäätöksen tekemistä. Mikäli annetut tiedot eivät pidä paikkaansa, tarjoaja voidaan joutua sulkemaan hankintamenettelystä. Hankinnan pääasiallisena kohteena ovat yhtenäisen käytön mukaiset monitoimilaitteet (painotettuna A4-kokoiset laitteet) tulostamiseen ja skannaukseen, asiakirjojen työnkulun ohjaamiseen, sekä em. laitteisiin ja niiden palveluihin liittyvät tuki- ja lisäpalvelut (esim. turvatulostaminen, hallintaratkaisut, väri- ja tarvikeratkaisut, tilausjärjestelmä yms.). Hankinnan keskiössä ovat kustannustehokkaat, A4-tulostamista tukevat laitteet, X-arkistoskannaus (terveydenhuollon XDS-ratkaisut) yksittäisiä laitteita, jotka sovitaan tapauskohtaisesti, GDPR:n huomioiminen toiminnassa, tuki- ja huoltopalvelut sekä muut tulostuspalveluiden lisäpalvelut asiakirjojen mukaisesti. Tämä hankinta ei sisällä tulostuspaperin, painotöiden tai painopalvelujen (esim. digi- ja offset-paino) hankintaa. Hankintaa on mahdollista laajentaa neuvottelumenettelyn aikana optiona USB:lla työasemiin kytkettävien tulostimien osalta. Option käyttöönotosta päättää Numera. Tarjouspalvelun käyttöön liittyvissä kysymyksissä ja ongelmatilanteissa tarjoajan tulee olla yhteydessä palveluntuottajan (Cloudia Oy / Tarjouspalvelu.fi) Helpdeskiin: puh. 020 766 1075, tuki@cloudia.fi.,','Numera Palvelut Oy','ANY',1,2,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056257','[\"30120000\", \"30100000\", \"30125100\", \"38520000\", \"48773000\"]','[\"numera\", \"tulostus\", \"palvelut\", \"hankintaa\", \"tiedot\", \"hankinnan\", \"tarjoaja\", \"aikana\", \"tuki\", \"informaatiopalvelut\", \"hankintayksikkö\", \"monitoimilaitteet\", \"liittyvät\", \"