INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (470,'2026-056251','HILMA','RFP','OPEN','Monilokeroastioiden tyhjennys- ja kuljetuspalvelut Ab Stormossen Oy:n toimialueella','Monilokeroastioiden tyhjennys- ja kuljetuspalvelut Ab Stormossen Oy:n toimialueella Hankinta koskee Ab Stormossen Oy:n toimialueella sijaitsevien pientalokiinteistöjen 370 litran monilokeroastioiden tyhjennys- ja kuljetuspalvelua. Toimialueeseen kuuluvat Vaasa, Mustasaari, Isokyrö, Vöyri, Maalahti ja Korsnäs. Palveluun kuuluvat monilokeroastioihin kerättyjen biojätteen, metallin, kartongin ja muovin tyhjentäminen sovitun noutopäiväsuunnitelman mukaisesti, jätejakeiden pitäminen erillään sekä niiden kuljettaminen ja purkaminen Tilaajan osoittamiin vastaanottopaikkoihin. Palveluun kuuluvat lisäksi monilokeroastioiden kaksi vuosittaista pesua palvelukuvauksessa määriteltyinä pesukausina, ajo-opastusjärjestelmän käyttö, tyhjennysten, pesujen ja poikkeamien kirjaaminen, raportointi sekä muut tarjouspyyntöasiakirjoissa määritellyt tehtävät. Palvelu hankitaan koko toimialueen kattavana kokonaisuutena. Tarjouspyyntöasiakirjoissa esitetyt palvelun laajuutta, keräysalueen rakennetta ja toteuttamista koskevat tiedot annetaan tarjousten laatimista varten. Tarjousten hintavertailu perustuu Cloudiassa ilmoitettuun yksikköhintaan ja vertailukertoimeen yksi (1). Laajuustiedot ja vertailukerroin eivät muodosta Tilaajalle vähimmäisostovelvoitetta. Toteutuvat määrät voivat muuttua sopimuskauden aikana, eikä määrien muuttuminen vaikuta tarjottuun yksikköhintaan kulloinkin voimassa olevan hintajakson aikana. Laskutus perustuu toteutuneisiin ja Tilaajan hyväksymiin tyhjennyksiin sekä sopimuksen mukaiseen yksikköhintaan.,','Ab Stormossen Oy','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056251','[\"90512000\"]','[\"stormossen\", \"monilokeroastioiden\", \"tyhjennys\", \"toimialueella\", \"kuuluvat\", \"yksikköhintaan\", \"kuljetuspalvelut\", \"palveluun\", \"tilaajan\", \"tarjouspyyntöasiakirjoissa\", \"tarjousten\", \"perustuu\", \"aikana\", \"hankinta\", \"koskee\", \"sijaitsevien\", \"pientalokiinteistöjen\", \"litran\", \"kuljetuspalvelua\", \"toimialueeseen\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/stormossen?id=625009&tpk=960d386f-a817-413e-a267-ce95d237dee6\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056251\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56251\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Monilokeroastioiden tyhjennys- ja kuljetuspalvelut Ab Stormossen Oy:n toimialueella\", \"titleSv\": \"\", \"cpvCodes\": \"90512000\", \"currency\": null, \"deadline\": \"2026-10-09T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI19A\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Hankinta koskee Ab Stormossen Oy:n toimialueella sijaitsevien pientalokiinteistöjen 370 litran monilokeroastioiden tyhjennys- ja kuljetuspalvelua. Toimialueeseen kuuluvat Vaasa, Mustasaari, Isokyrö, Vöyri, Maalahti ja Korsnäs.\\n\\nPalveluun kuuluvat monilokeroastioihin kerättyjen biojätteen, metallin, kartongin ja muovin tyhjentäminen sovitun noutopäiväsuunnitelman mukaisesti, jätejakeiden pitäminen erillään sekä niiden kuljettaminen ja purkaminen Tilaajan osoittamiin vastaanottopaikkoihin. Palveluun kuuluvat lisäksi monilokeroastioiden kaksi vuosittaista pesua palvelukuvauksessa määriteltyinä pesukausina, ajo-opastusjärjestelmän käyttö, tyhjennysten, pesujen ja poikkeamien kirjaaminen, raportointi sekä muut tarjouspyyntöasiakirjoissa määritellyt tehtävät.\\n\\nPalvelu hankitaan koko toimialueen kattavana kokonaisuutena. Tarjouspyyntöasiakirjoissa esitetyt palvelun laajuutta, keräysalueen rakennetta ja toteuttamista koskevat tiedot annetaan tarjousten laatimista varten. Tarjousten hintavertailu perustuu Cloudiassa ilmoitettuun yksikköhintaan ja vertailukertoimeen yksi (1). Laajuustiedot ja vertailukerroin eivät muodosta Tilaajalle vähimmäisostovelvoitetta. Toteutuvat määrät voivat muuttua sopimuskauden aikana, eikä määrien muuttuminen vaikuta tarjottuun yksikköhintaan kulloinkin voimassa olevan hintajakson aikana. Laskutus perustuu toteutuneisiin ja Tilaajan hyväksymiin tyhjennyksiin sekä sopimuksen mukaiseen yksikköhintaan.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-10-09T09:00:00Z\", \"circularEconomy\": true, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": false, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmis