INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (479,'2026-056387','HILMA','RFI','OPEN','TIETOPYYNTÖ: Asiakkuudenhallinta- ja asiakaspalvelujärjestelmä Helsingin Asumisoikeus Oy:n käyttöön','TIETOPYYNTÖ: Asiakkuudenhallinta- ja asiakaspalvelujärjestelmä Helsingin Asumisoikeus Oy:n käyttöön Tämä asiakirja ei ole hankintailmoitus tai tarjouspyyntö vaan hankintalain 65 §:n mukainen markkinakartoitus, jonka hankintayksikkö toteuttaa tässä tietopyynnössä kerrotun mukaisesti. Tällä tietopyynnöllä on tarkoitus selvittää otsikon mukaiseen hankintaan liittyviä kysymyksiä. Tietopyynnön tavoitteena on saada kattavasti hankinnan kohdetta koskevaa tietoa tukemaan hankinnan valmistelua, jotta mahdollinen tarjouskilpailu voidaan toteuttaa mahdollisimman tarkoituksenmukaisesti. Hankintayksikkö ei sitoudu toteuttamaan hankintaa. Päätökset mahdollisen hankintaprosessin käynnistämisestä tehdään markkinakartoituksen jälkeen. HANKINNAN ALUSTAVAN KUVAUKSEN TIIVISTELMÄ Hankinnan kohteena on uusi asiakkuudenhallinta- ja asiakaspalvelujärjestelmä Helsingin Asumisoikeus Oy:n käyttöön. Järjestelmän on tarkoitus tukea ja tehostaa Hason asiakkuudenhallinnan kokonaisprosessia myynnistä ja vuokrauksesta asumisenaikaiseen asiakaspalveluun sekä palvelupyyntöjen, yhteydenottojen ja kumppaniverkoston tehtävien käsittelyyn. Uudella ratkaisulla tavoitellaan nykyistä läpinäkyvämpää, mitattavampaa ja tehokkaampaa toimintamallia sekä nykyisen palvelupyyntöjen käsittelyjärjestelmän korvaamista. Hankittavan järjestelmän tulee palvella Hason sisäisiä käyttäjiä, asukkaita, hakijoita, asumisoikeuden haltijoita sekä ulkoisia palvelukumppaneita. Järjestelmän avulla käsitellään muun muassa asiakaspalveluun, asumiseen, myyntiin, vikailmoituksiin, reklamaatioihin, tilavarauksiin, muutostöihin, laskutukseen ja kumppaneiden toimenpiteisiin liittyviä asioita. Järjestelmän tulee tukea palvelupyyntöjen ohjaamista Hason palvelurakenteessa pyynnön tyypin, sisällön ja kiireellisyyden perusteella. Hankinnan tavoitteena on saada käyttöön helppokäyttöinen, kustannustehokas ja skaalautuva ratkaisu, joka tukee monikanavaista asiointia, asiakaspalvelun ja myynnin työskentelyä, prosessien automatisointia, tekoälyn hyödyntämistä sekä tiedolla johtamista. Ratkaisun tulee mahdollistaa asiakas- ja palvelutietojen hallinta, tarvittavat integraatiot muihin järjestelmiin, käyttöoikeuksien hallinta eri käyttäjäryhmille sekä tietoturvallinen henkilötietojen käsittely. Hankinnan kohteen alustava kuvaus on Liitteessä 1 Hankekuvaus, HASO-asiakaspalvelujärjestelmä-määrittely.,','Helsingin Asumisoikeus Oy','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056387','[\"48000000\"]','[\"hankinnan\", \"asiakaspalvelujärjestelmä\", \"helsingin\", \"asumisoikeus\", \"käyttöön\", \"järjestelmän\", \"asiakkuudenhallinta\", \"hason\", \"palvelupyyntöjen\", \"tulee\", \"tietopyyntö\", \"hankintayksikkö\", \"toteuttaa\", \"tarkoitus\", \"liittyviä\", \"tavoitteena\", \"saada\", \"tukea\", \"asiakaspalveluun\", \"hallinta\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/haso?id=625128&tpk=810bde52-7182-4507-989c-55dc05a80f21\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056387\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56387\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"TIETOPYYNTÖ: Asiakkuudenhallinta- ja asiakaspalvelujärjestelmä Helsingin Asumisoikeus Oy:n käyttöön\", \"titleSv\": \"\", \"cpvCodes\": \"48000000\", \"currency\": null, \"deadline\": \"2026-09-15T10:00:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"\", \"titleOther\": \"\", \"