INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (480,'2026-056384','HILMA','RFP','OPEN','Sähköinen lomakejärjestelmä, Siun sote','Sähköinen lomakejärjestelmä, Siun sote Hankinnan kohteena on Pohjois-Karjalan hyvinvointialueelle hankittava sähköinen lomakejärjestelmä SaaS-palveluna. Järjestelmän avulla voidaan toteuttaa, julkaista ja hallinnoida sähköisiä asiointilomakkeita sekä sisäisiä ja hallinnollisia lomakkeita. Järjestelmään liittyy lomakkeiden käsittelyyn ja hyväksyntään liittyviä työnkulkuja, käsittelyjonoja ja päätöksentekoa tukevia vaiheita. Siun sote tuottaa sosiaali-ja terveyspalvelut noin 170 000 asukkaalle Pohjois-Karjalan alueella ja työllistää noin 8 000 työntekijää. Järjestelmää käyttävät sekä Siun soten työntekijät että asioivat henkilöt ja yhteistyökumppanit. Hankinnan tavoitteena on siirtyä nykyistä laajemmin paperisista ja sähköpostipohjaisista menettelyistä hallittuihin, tietoturvallisiin ja integroituihin sähköisiin lomakeprosesseihin sekä parantaa tiedon löydettävyyttä, käsiteltävyyttä ja elinkaarenhallintaa. Hankinnan kohde ja siihen kohdistuvat vaatimukset on kuvattu tarkemmin tarjouspyynnön liitteissä. Hankintasopimusluonnos on tarjouspyynnön liitteenä.,','Pohjois-Karjalan hyvinvointialue','ANY',3,10,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056384','[\"72000000\", \"48000000\"]','[\"siun\", \"pohjois\", \"karjalan\", \"sähköinen\", \"lomakejärjestelmä\", \"sote\", \"hankinnan\", \"noin\", \"tarjouspyynnön\", \"hyvinvointialue\", \"kohteena\", \"hyvinvointialueelle\", \"hankittava\", \"saas\", \"palveluna\", \"järjestelmän\", \"avulla\", \"voidaan\", \"toteu