INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (486,'2026-056369','HILMA','RFP','OPEN','Mänttä-Vilppulan kaupungin Mäntän kiinteistöjen talvikunnossapito','Mänttä-Vilppulan kaupungin Mäntän kiinteistöjen talvikunnossapito Mänttä-Vilppulan kaupunki pyytää tarjoustanne Mäntän taajaman kiinteistöjen piha-alueiden aurauksesta ja liukkaudentorjunnasta tämän tarjouspyynnön ja sen liitteenä olevien asiakirjojen mukaisesti kolmelle talvikaudelle ajalle 2026-2029. Sopimusta voidaan jatkaa yhdellä optiovuodella. Optiovuosien käytöstä päätetään keväällä 2029. Optiovuoden käyttämisestä tulee olla molempien sopijapuolten suostumus. Mikäli kaupungin omistamien kiinteistöjen määrään tulee muutoksia, tilaaja voi muuttaa urakan laajuutta. Tilaaja pidättää itsellään oikeuden lisätä taikka vähentää sopimuksen mukaisia kunnossapitokohteita, jolloin kiinteistöjen piha-alueiden aurauksen ja liukkaudentorjunnan tarve joko nousee tai laskee suhteessa talvihoidon laskennalliseen kokonaismäärään, kuitenkin enintään +/- 20%.,','Mänttä-Vilppulan kaupunki','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056369','[\"70332000\"]','[\"mänttä\", \"vilppulan\", \"kiinteistöjen\", \"kaupungin\", \"mäntän\", \"kaupunki\", \"talvikunnossapito\", \"piha\", \"alueiden\", \"tulee\", \"tilaaja\", \"pyytää\", \"tarjoustanne\", \"taajaman\", \"aurauksesta\", \"liukkaudentorjunnasta\", \"tämän\", \"tarjouspyynnön\", \"liitteenä\", \"olevien\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/manttavilppula?id=619443&tpk=e896682f-d439-4a01-a9e8-01b1946edc33\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://ww