INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (488,'2026-056366','HILMA','RFP','OPEN','Mänttä-Vilppulan kaupungin Kolhon kiinteistöjen talvikunnossapito','Mänttä-Vilppulan kaupungin Kolhon kiinteistöjen talvikunnossapito Mänttä-Vilppulan kaupunki pyytää tarjoustanne Kolhon taajaman kiinteistöjen piha-alueiden aurauksesta ja liukkaudentorjunnasta tämän tarjouspyynnön ja sen liitteenä olevien asiakirjojen mukaisesti kolmelle talvikaudelle ajalle 2026-2029. Sopimusta voidaan jatkaa kahdella optiovuodella. Optiovuosien käytöstä päätetään keväällä 2029. Optiovuoden käyttämisestä tulee olla molempien sopijapuolten suostumus. Mikäli kaupungin omistamien kiinteistöjen määrään tulee muutoksia, tilaaja voi muuttaa urakan laajuutta. Tilaaja pidättää itsellään oikeuden lisätä taikka vähentää sopimuksen mukaisia kunnossapitokohteita, jolloin kiinteistöjen piha-alueiden aurauksen ja liukkaudentorjunnan tarve joko nousee tai laskee suhteessa talvihoidon laskennalliseen kokonaismäärään, kuitenkin enintään +/- 20%.,','Mänttä-Vilppulan kaupunki','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056366','[\"70332000\"]','[\"mänttä\", \"vilppulan\", \"kiinteistöjen\", \"kaupungin\", \"kolhon\", \"kaupunki\", \"talvikunnossapito\", \"piha\", \"alueiden\", \"tulee\", \"tilaaja\", \"pyytää\", \"tarjoustanne\", \"taajaman\", \"aurauksesta\", \"liukkaudentorjunnasta\", \"tämän\", \"tarjouspyynnön\", \"liitteenä\", \"olevien\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/manttavilppula?id=621049&tpk=904a1ccc-b89a-4d5e-bd63-3ac517d71e9d\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://w