INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (491,'2026-056269','HILMA','RFI','OPEN','TIETOPYYNTÖ: Nestetyppipakastin näytesäilytykseen Itä-Suomen biopankille','TIETOPYYNTÖ: Nestetyppipakastin näytesäilytykseen Itä-Suomen biopankille Pohjois-Savon hyvinvointialueen Itä-Suomen biopankki suunnittelee nestetyppipakastimien hankintaa näytteiden säilytykseen. Nestetyppipakastimet sijoittuvat Kuopion Yliopistollisen sairaalan Itä-Suomen Biopankin tiloihin rakennus C0. Pakastimet tullaan kytkemään biopankin nestetyppilinjastoon. Pakastimia käytetään ihmisperäisten näytteiden säilyttämiseen nestetypen kaasufaasissa. Hankinnan valmisteluun liittyen toteutetaan markkinavuoropuhelu, jonka tarkoituksena on kartoittaa markkinoiden tarjontaa, teknisiä ratkaisuja sekä toimittajien näkemyksiä hankinnan toteuttamisesta. Tämä ei ole hankintailmoitus, eikä tarjouspyyntö, vaan tietopyyntö markkinoilla toimiville Tarjoajille. Tietopyynnön tarkoituksena on kartoittaa markkinoita ja kerätä tietoa. Tietopyynnöllä ei pyydetä, eikä siihen anneta tarjouksia, vaan tämän tietopyynnön tarkoituksena on mahdollistaa kommenttien esittäminen tulevasta hankinnasta sekä saada ajantasaista tietoa markkinoilla olevista ratkaisuista. Tietopyynnön tarkoitus on saada kattava kuva markkinatilanteesta tulevan kilpailutuksen järjestämistä varten sekä saada kommentteja tämän tietopyynnön liitteenä oleviin tarjouspyyntö materiaaleihin. Tietopyynnöllä saatuihin kommentteihin tai kysymyksiin ei vastata. Tietopyyntöön vastaamisesta tai mahdollisistaesittelyistä ei makseta korvausta. Tietopyyntö ei velvoita hankintayksikköä suorittamaan varsinaista hankintaa tai toteuttamaan hankintaa tietopyynnössä kuvatulla tavalla. Hankintayksikkö ei ole velvollinen ottamaan huomioon tietopyyntöön saatuja vastauksia tarjouspyynnön laadinnassa. Tietopyynnön liitteenä on tarjouspyynnön luonnosasiakirjoja, joihin pyydämme kommenttejanne. Tarjouspyyntöluonnoksessa sekä vähimmäisvaatimukset sisältävässä Excelissä olevat tekstit voivat muuttua varsinaisessa tarjouspyynnössä. Tietopyynnön vastaamisen yhteydessä Tarjoajan on mahdollista jättää liitetiedosto, esimerkiksi tarjolla olevan laitteen esite.,','Pohjois-Savon hyvinvointialue','ANY',3,8,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056269','[\"38000000\", \"39711124\"]','[\"tietopyynnön\", \"tietopyyntö\", \"suomen\", \"pohjois\", \"savon\", \"hankintaa\", \"tarkoituksena\", \"saada\", \"nestetyppipakastin\", \"näytesäilytykseen\", \"biopankille\", \"näytteiden\", \"biopankin\", \"hankinnan\", \"kartoittaa\", \"eikä\", \"tarjouspyyntö\", \"vaan\", \"markkinoilla\", \"tietoa\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/public/procedure/36719/enotice/56269\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056269\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56269\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"TIETOPYYNTÖ: Nestetyppipakastin näytesäilytykseen Itä-Suomen biopankille\", \"titleSv\": \"\", \"cpvCodes\": \"38000000 39711124\", \"currency\": null, \"deadline\": \"2026-09-21T09:00:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI1DB\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Pohjois-Savon hyvinvointialueen Itä-Suomen biopankki suunnittelee nestetyppipakastimien hankintaa näytteiden säilytykseen. Nestetyppipakastimet sijoittuvat Kuopion Yliopistollisen sairaalan Itä-Suomen Biopankin tiloihin rakennus C0. Pakastimet tullaan kytkemään biopankin nestetyppilinjastoon. Pakastimia käytetään ihmisperäisten näytteiden säilyttämiseen nestetypen kaasufaasissa. \\n\\nHankinnan valmisteluun liittyen toteutetaan markkinavuoropuhelu, jonka tarkoituksena on kartoittaa markkinoiden tarjontaa, teknisiä ratkaisuja sekä toimittajien näkemyksiä hankinnan toteuttamisesta. \\nTämä ei ole hankintailmoitus, eikä tarjouspyyntö, vaan tietopyyntö markkinoilla toimiville Tarjoajille. Tietopyynnön tarkoituksena on kartoittaa markkinoita ja kerätä tietoa. Tietopyynnöllä ei pyydetä, eikä siihen anneta tarjouksia, vaan tämän tietopyynnön tarkoituksena on mahdollistaa kommenttien esittäminen tulevasta hankinnasta sekä saada ajantasaista tietoa markkinoilla olevista ratkaisuista. \\n\\nTietopyynnön tarkoitus on saada kattava kuva markkinatilanteesta tulevan kilpailutuksen järjestämistä varten sekä saada kommentteja tämän tietopyynnön liitteenä oleviin tarjouspyyntö materiaaleihin. Tietopyynnöllä saatuihin kommentteihin tai kysymyksiin ei vastata. Tietopyyntöön vastaamisesta tai mahdollisistaesittelyistä ei makseta korvausta. Tietopyyntö ei velvoita hankintayksikköä suorittamaan varsinaista hankintaa tai toteuttamaan hankintaa tietopyynnössä kuvatulla tavalla. Hankintayksikkö ei ole velvollinen ottamaan huomioon tietopyyntöön saatuja vastauksia tarjouspyynnön laadinnassa. \\n\\nTietopyynnön liitteenä on tarjouspyynnön luonnosasiakirjoja, joihin pyydämme kommenttejanne. Tarjouspyyntöluonnoksessa sekä vähimmäisvaatimukset sisältävässä Excelissä olevat tekstit voivat muuttua varsinaisessa tarjouspyynnössä. Tietopyynnön vastaamisen yhteydessä Tarjoajan on mahdollista jättää liitetiedosto, esimerkiksi tarjolla olevan laitteen esite.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-09-21T09:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": null, \"lotResultTotalAmount\": null, \"justWorkingConditions\": null, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": null, \"includesFrameworkAgreement\": null, \"smeParticipationConsidered\": null, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": null, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": null, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"E1\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"TIETOPYYNTÖ: Nestetyppipakastin näytesäilytykseen Itä-Suomen biopankille\", \"titleSv\": \"\", \"cpvCodes\": \"38000000 39711124\", \"currency\": null, \"deadline\": \"2026-09-21T09:00:00Z\", \"eFormsId\": \"97084fd5-94c7-49a5-ad28-d933ec29b759\", \"isEForms\": true, \"mainType\": \"PriorInformationNotices\", \"noticeId\": 56269, \"lowCarbon\": null, \"nutsCodes\": \"FI1DB\", \"titleOther\": \"\", \"isCancelled\": false, \"procedureId\": 36719, \"biodiversity\": null, \"dateModified\": \"2026-09-04T11:31:56.165Z\", \"fullEFormsId\": \"97084fd5-94c7-49a5-ad28-d933ec29b759-01\", \"noticeNumber\": \"2026-056269\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2026-09-04T11:31:56.159Z\", \"descriptionEn\": \"\", \"descriptionFi\": \"TIETOPYYNTÖ: Nestetyppipakastin näytesäilytykseen Itä-Suomen biopankille Pohjois-Savon hyvinvointialueen Itä-Suomen biopankki suunnittelee nestetyppipakastimien hankintaa näytteiden säilytykseen. Nestetyppipakastimet sijoittuvat Kuopion Yliopistollisen sairaalan Itä-Suomen Biopankin tiloihin rakennus C0. Pakastimet tullaan kytkemään biopankin nestetyppilinjastoon. Pakastimia käytetään ihmisperäisten näytteiden säilyttämiseen nestetypen kaasufaasissa. \\n\\nHankinnan valmisteluun liittyen toteutetaan markkinavuoropuhelu, jonka tarkoituksena on kartoittaa markkinoiden tarjontaa, teknisiä ratkaisuja sekä toimittajien näkemyksiä hankinnan toteuttamisesta. \\nTämä ei ole hankintailmoitus, eikä tarjouspyyntö, vaan tietopyyntö markkinoilla toimiville Tarjoajille. Tietopyynnön tarkoituksena on kartoittaa markkinoita ja kerätä tietoa. Tietopyynnöllä ei pyydetä, eikä siihen anneta tarjouksia, vaan tämän tietopyynnön tarkoituksena on mahdollistaa kommenttien esittäminen tulevasta hankinnasta sekä saada ajantasaista tietoa markkinoilla olevista ratkaisuista. \\n\\nTietopyynnön tarkoitus on saada kattava kuva markkinatilanteesta tulevan kilpailutuksen järjestämistä varten sekä saada kommentteja tämän tietopyynnön liitteenä oleviin tarjouspyyntö materiaaleihin. Tietopyynnöllä saatuihin kommentteihin tai kysymyksiin ei vastata. Tietopyyntöön vastaamisesta tai mahdollisistaesittelyistä ei makseta korvausta. Tietopyyntö ei velvoita hankintayksikköä suorittamaan varsinaista hankintaa tai toteuttamaan hankintaa tietopyynnössä kuvatulla tavalla. Hankintayksikkö ei ole velvollinen ottamaan huomioon tietopyyntöön saatuja vastauksia tarjouspyynnön laadinnassa. \\n\\nTietopyynnön liitteenä on tarjouspyynnön luonnosasiakirjoja, joihin pyydämme kommenttejanne. Tarjouspyyntöluonnoksessa sekä vähimmäisvaatimukset sisältävässä Excelissä olevat tekstit voivat muuttua varsinaisessa tarjouspyynnössä. Tietopyynnön vastaamisen yhteydessä Tarjoajan on mahdollista jättää liitetiedosto, esimerkiksi tarjolla olevan laitteen esite.,\", \"descriptionSv\": \"\", \"isCorrigendum\": false, \"linkedNotices\": \"\", \"procedureType\": null, \"sendingSystem\": \"Hilma\", \"estimatedValue\": null, \"e