INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (507,'2026-056329','HILMA','OTHER','OPEN','KESKEYTYSILMOITUS Kiinteistöjen sähkötekniset työt, katuvalaistus ja ajoneuvosilmukoiden teko','Sansia Oy kilpailuttaa sähkötyöt tilaajien omistamien kiinteistöjen kunnossapitoon ja investointitöihin. Normaalien kiinteistöjen sähköteknisten töiden lisäksi puitejärjestelyyn kuuluvat omina osa-alueinaan katu- ja liikuntareittien ulkovalaistuksen kunnossapitoon ja pienimuotoisiin investointeihin sekä liikennevalojen ajoneuvosilmukoiden tekoon liittyvät työt. Tilaajana hankinnassa ovat Kuopion ev.lut. seurakuntayhtymä, Leppävirran kunta sekä Varkauden kaupunki. Hankinta on jaettu kuuteen osaan, tarjouksen voi jättää yhteen tai useampaan osaan: * osa 1. Kiinteistöjen sähkötekniset työt, Kuopion ev.lut. seurakuntayhtymä * osa 2. Kiinteistöjen sähkötekniset työt, Leppävirta * osa 3. Kiinteistöjen sähkötekniset työt, Varkaus * osa 4. Katu- ja liikuntareittien ulkovalaistuksen kunnossapito ja pienimuotoiset investoinnit, Leppävirta * osa 5. Katu- ja liikuntareittien ulkovalaistuksen kunnossapito ja pienimuotoiset investoinnit, Varkaus * osa 6. Ajoneuvosilmukoiden teko liikennevaloristeyksiin, Varkaus Jos tarjouksia ei saada riittävästi tai tarjouksia joudutaan hylkäämään, voi valittavien toimittajien määrä osa-alueittain olla vähemmän. Valittujen toimittajien kanssa perustetaan puitejärjestely. Hankintasopimuksen perusteella tilaaja tekee toimittajilta tilauksia, joiden kesto ja mahdolliset tilausta koskevat yksityiskohdat määräytyvät tilaajan tarpeiden mukaan. Puitejärjestelyn kesto on 1.1.2027 - 31.12.2029. Hankinta sisältää yhden vuoden option kaudelle 1.1.2030 - 31.12.2030. Jos hankinnan ennakoitu arvo sekä enimmäisarvo on saavutettu ennen määräaikaisen sopimuksen tai mahdollisesti käyttöön otetun optiokauden päättymisaikaa, puitejärjestely päättyy. Toimittajalla ei tällöin ole mitään vaatimuksia Asiakasta eikä Tilaajaa kohtaan., Osa 1. Kiinteistöjen sähkötekniset työt, Kuopion ev.lut. seurakuntayhtymä Osakokonaisuus sisältää sähkötekniset työt Kuopion ev.lut. seurakuntayhtymän (tilaaja) omistamien kiinteistöjen kunnossapitoon ja investointeihin. Hankinta koskee tilaajan kiinteistöjä ja toimitiloja sekä niissä sopimusaikana toteutettavia erikseen määriteltäviä, pääasiassa pieniä ja/tai urakkalaskennan kannalta epämääräisiä työsuorituksia /kokonaisuuksia. Osakokonaisuus on jaettu seuraaviin kohteisiin, joiden sähkötöitä tämän tarjouspyynnön sisältö koskee: - Juankoski - Kaavi - Karttula - Kuopio - Maaninka - Muuruvesi - Nilsiä - Riistavesi - Rytkyn leirikeskus - Tuusniemi Kunnossapitotöiden lisäksi sopimuksen kautta tilataan vuosittaisia investointitöitä, jotka eivät kuulu kohteen rakentamisen kokonaisurakkaan. Tarjoaja voi jättää tarjouksen koskien vain yhtä kohdetta tai kaikkia kohteita. Jokaiseen kohteeseen valitaan kolme (3) kokonaistaloudellisesti edullisinta ja vähimmäisvaatimukset täyttävää toimittajaa. Puitesopimuksen kesto on 1.1.2027 - 31.12.2029. Hankinta sisältää yhden vuoden option kaudelle 1.1.2030 - 31.12.2030., Osa 2. Kiinteistöjen sähkötekniset työt, Leppävirta Osakokonaisuus sisältää sähkötekniset työt Leppävirran kunnan (tilaaja) omistamien kiinteistöjen kunnossapitoon ja investointeihin. Hankinta koskee tilaajan kiinteistöjä ja toimitiloja sekä niissä sopimusaikana toteutettavia erikseen määriteltäviä, pääasiassa pieniä ja/tai urakkalaskennan kannalta epämääräisiä työsuorituksia /kokonaisuuksia. Kunnossapitotöiden lisäksi sopimuksen kautta tilataan vuosittaisia investointitöitä, jotka eivät kuulu kohteen rakentamisen kokonaisurakkaan. Osaan valitaan viisi (5) kokonaistaloudellisesti edullisinta ja vähimmäisvaatimukset täyttävää toimittajaa. Puitesopimuksen kesto on 1.1.2027 - 31.12.2029. Hankinta sisältää yhden vuoden option kaudelle 1.1.2030 - 31.12.2030., Osa 3. Kiinteistöjen sähkötekniset työt, Varkaus Osakokonaisuus sisältää sähkötekniset työt Varkauden kaupungin (tilaaja) omistamien kiinteistöjen kunnossapitoon ja investointeihin. Hankinta koskee tilaajan kiinteistöjä ja toimitiloja sekä niissä sopimusaikana toteutettavia erikseen määriteltäviä, pääasiassa pieniä ja/tai urakkalaskennan kannalta epämääräisiä työsuorituksia /kokonaisuuksia. Kunnossapitotöiden lisäksi sopimuksen kautta tilataan vuosittaisia investointitöitä, jotka eivät kuulu kohteen rakentamisen kokonaisurakkaan. Osaan valitaan viisi (5) kokonaistaloudellisesti edullisinta ja vähimmäisvaatimukset täyttävää toimittajaa. Puitesopimuksen kesto on 1.1.2027 - 31.12.2029. Hankinta sisältää yhden vuoden option kaudelle 1.1.2030 - 31.12.2030., Osa 4. Katu- ja liikuntareittien ulkovalaistuksen kunnossapito ja pienimuotoiset investoinnit, Leppävirta Osakokonaisuus sisältää Leppävirran kunnan (tilaaja) katu- ja liikuntaväylien valaistukseen liittyvät sähkötyöt. Työ tulee olemaan pääsääntöisesti katu- ja liikuntareittivalaistusverkon vika- ja vauriokorjausrakentamista, sekä pienimuotoista investointirakentamista. Osaan valitaan kolme (3) kokonaistaloudellisesti edullisinta ja vähimmäisvaatimukset täyttävää toimittajaa. Puitesopimuksen kesto on 1.1.2027 - 31.12.2029. Hankinta sisältää yhden vuoden option kaudelle 1.1.2030 - 31.12.2030., Osa 5. Katu- ja liikuntareittien ulkovalaistuksen kunnossapito ja pienimuotoiset investoinnit, Varkaus Osakokonaisuus sisältää Varkauden kaupungin (tilaaja) katu- ja liikuntaväylien valaistukseen liittyvät sähkötyöt. Työ tulee olemaan pääsääntöisesti katu- ja liikuntareittivalaistusverkon vika- ja vauriokorjausrakentamista, sekä pienimuotoista investointirakentamista. Tiettyyn huoltorytmiin tapahtuva perushuolto näille alueille tehdään Varkauden kaupungin oman sähköhuollon toimesta, eli se ei kuulu puitesopimustoimittajan tehtäviin. Osaan valitaan kolme (3) kokonaistaloudellisesti edullisinta ja vähimmäisvaatimukset täyttävää toimittajaa. Puitesopimuksen kesto on 1.1.2027 - 31.12.2029. Hankinta sisältää yhden vuoden option kaudelle 1.1.2030 - 31.12.2030., Osa 6. Ajoneuvosilmukoiden teko liikennevaloristeyksiin, Varkaus Osakokonaisuus sisältää Varkauden kaupungin (tilaaja) ajoneuvosilmukoiden teko liikennevalo-ohjattuihin risteyksiin. Silmukoita uusitaan/korjataan risteysalueiden asfaltointitöiden yhteydessä tapahtuvan vanhan tienpinnan poiston aikana rikkoutuneiden silmukoiden osalta sekä muulloinkin silmukoiden vikaantuessa. Osaan valitaan kolme (3) kokonaistaloudellisesti edullisinta ja vähimmäisvaatimukset täyttävää toimittajaa. Puitesopimuksen kesto on 1.1.2027 - 31.12.2029. Hankinta sisältää yhden vuoden option kaudelle 1.1.2030 - 31.12.2030.,','Sansia Oy','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056329','[\"45310000\", \"45316000\", \"45316213\"]','[\"sisältää\", \"kiinteistöjen\", \"työt\", \"hankinta\", \"sähkötekniset\", \"katu\", \"kesto\", \"osaan\", \"tilaaja\", \"yhden\", \"vuoden\", \"option\", \"kaudelle\", \"osakokonaisuus\", \"varkaus\", \"valitaan\", \"kokonaistaloudellisesti\", \"edullisinta\", \"vähimmäisvaatimukset\", \"täyttävää\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056329\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56329\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Osa 1. Kiinteistöjen sähkötekniset työt, Kuopion ev.lut. seurakuntayhtymä\", \"titleSv\": \"\", \"cpvCodes\": \"45310000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": null, \"nutsCodes\": \"FI1DB\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Osakokonaisuus sisältää sähkötekniset työt Kuopion ev.lut. seurakuntayhtymän (tilaaja