INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (512,'2026-056320','HILMA','RFI','OPEN','Markkinakartoitus/ Tietopyyntö: UPS + superkondensaattori laitteisto','Markkinakartoitus/ Tietopyyntö: UPS + superkondensaattori laitteisto Markkinakartoitus ja tietopyyntö tulevasta hankinnasta Markkinakartoituksella ja tietopyynnöllä Kainuun hyvinvointialue selvittää mahdollisia toimittajia tulevaa UPS- ja superkondensaattoria hankintaa varten. Markkinakartoituksen tarkoituksena on saada tietoa markkinoilla saatavilla olevista ratkaisuista ja niiden teknisistä ominaisuuksista, toimitusmalleista ja mahdollisista toimittajista. Tämä tietopyyntö ei ole hankintailmoitus eikä tarjouspyyntö eikä siihen vastaaminen sido vastaajaa eikä hankintayksikköä. UPS+ superkondensaattori laitteiston on tarkoitus rajoittaa CT-kuvauslaitteen ottamaa tehoa varavoima verkosta (RUPS) Teholuokka laitteistolle on noin. 200 -300 kW. Teho tarkentuu sähköteknisen suunnittelun edetessä. Laitteiston tulee kyetä rajoittamaan tehoa noin 7 -10 s. Laitteiston energiavarastoksi olemme valinneet superkondensaattorit. Laitteiston on myös normaalikäytössä kyettävä leikkaamaan teho piikkejä. Energiavaraston on kyettävä latautumaan laitteen käyttö rytmissä n.10-15 min. välein tapathuvilla käynnistyksillä. Uuden laitteen käyttöönotto arvioidaan tapahtuvan vuoden 2027 kevättalven aikana. Hankinnan kohde Hankintayksikkö suunnittelee UPS-järjestelmän ja siihen liittyvän superkondensaattoriratkaisun hankintaa turvaamaan kriittisten toimintojen sähkönsyötön häiriötilanteissa. Ratkaisulta edellytetään alustavasti muun muassa: -korkeaa käyttövarmuutta -soveltuvuutta ympärivuorokautiseen käyttöön -yhteensopivuutta olemassa olevan sähköjärjestelmän kanssa -mahdollisuutta valvontaan ja etähallintaan -huolto- ja tukipalveluiden saatavuutta Suomessa Tietopyynnön kysymykset ovat erillisessä liitteessä. Hankintayksikkö pyytää toimittajia täyttämään liitteenä oleva kysymyslomake ja lataamaan se tämän markkinakartoituksen yhteyteen. Voitte liittää asialle halutessanne myös omia liitteitänne. Vastaukset pyydetään toimittamaan viimeistään 20.9.2026. Hankintayksikkö voi markkinakartoituksen perusteella pyytää lisätietoja toimittajilta.,','Kainuun hyvinvointialue','SME',3,3,NULL,NULL,160000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056320','[\"45317300\"]','[\"tietopyyntö\", \"laitteiston\", \"markkinakartoitus\", \"superkondensaattori\", \"markkinakartoituksen\", \"eikä\", \"hankintayksikkö\", \"laitteisto\", \"kainuun\", \"hyvinvointialue\", \"toimittajia\", \"hankintaa\", \"siihen\", \"tehoa\", \"noin\", \"teho\", \"kyettävä\", \"laitteen\", \"pyytää\", \"tulevasta\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/kainuunhyvinvointialue?id=624875&tpk=2d242292-c447-4260-926a-b26727bee071\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056320\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56320\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Markkinakartoitus/ Tietopyyntö: UPS + superkondensaattori laitteisto\", \"titleSv\": \"\", \"cpvCodes\": \"45317300\", \"currency\": \"EUR\", \"deadline\": \"2026-09-20T20:59:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI1D8\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Markkinakartoitus ja tietopyyntö tulevasta hankinnasta\\n\\nMarkkinakartoituksella ja tietopyynnöllä Kainuun hyvinvointialue selvittää mahdollisia toimittajia tulevaa UPS- ja superkondensaattoria hankintaa varten.\\nMarkkinakartoituksen tarkoituksena on saada tietoa markkinoilla saatavilla olevista ratkaisuista ja niiden teknisistä ominaisuuksista, toimitusmalleista ja mahdollisista toimittajista.\\n\\nTämä tietopyyntö ei ole hankintailmoitus eikä tarjouspyyntö eikä siihen vastaaminen sido vastaajaa eikä hankintayksikköä.\\n\\nUPS+ superkondensaattori laitteiston on tarkoitus rajoittaa CT-kuvauslaitteen ottamaa tehoa varavoima verkosta (RUPS) Teholuokka laitteistolle on noin. 200 -300 kW. Teho tarkentuu sähköteknisen suunnittelun edetessä. Laitteiston tulee kyetä rajoittamaan tehoa noin 7 -10 s. Laitteiston energiavarastoksi olemme valinneet superkondensaattorit. Laitteiston on myös normaalikäytössä kyettävä leikkaamaan teho piikkejä.  Energiavaraston on kyettävä latautumaan laitteen käyttö rytmissä n.10-15 min. välein tapathuvilla käynnistyksillä. \\n\\nUuden laitteen käyttöönotto arvioidaan tapahtuvan vuoden 2027 kevättalven aikana.\\n\\nHankinnan kohde\\nHankintayksikkö suunnittelee UPS-järjestelmän ja siihen liittyvän superkondensaattoriratkaisun hankintaa turvaamaan kriittisten toimintojen sähkönsyötön häiriötilanteissa.\\nRatkaisulta edellytetään alustavasti muun muassa:\\n-korkeaa käyttövarmuutta\\n-soveltuvuutta ympärivuorokautiseen käyttöön\\n-yhteensopivuutta olemassa olevan sähköjärjestelmän kanssa\\n-mahdollisuutta valvontaan ja etähallintaan\\n-huolto- ja tukipalveluiden saatavuutta Suomessa\\n\\nTietopyynnön kysymykset ovat erillisessä liitteessä.\\nHankintayksikkö pyytää toimittajia täyttämään liitteenä oleva kysymyslomake ja lataamaan se tämän markkinakartoituksen \\nyhteyteen. \\n\\nVoitte liittää asialle halutessanne myös omia liitteitänne.\\n\\nVastaukset pyydetään toimittamaan viimeistään 20.9.2026.\\n\\nHankintayksikkö voi markkinakartoituksen perusteella pyytää lisätietoja toimittajilta.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 160000.0, \"expirationDate\": \"2026-09-20T20:59:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNe