INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (513,'2026-056319','HILMA','RFP','OPEN','Ristipellontien porttaaliperustusten paalutustyöt','Ristipellontien porttaaliperustusten paalutustyöt Helsingin kaupungin rakentamispalveluliikelaitos, Stara pyytää yksikköhintaista urakkatarjoustanne Ristipellontien/Vihdintie risteyksen porttaalin paalutuksen rakentamisesta suunnitelmien mukaisesti täysin valmiiksi. Aikataulu: 9-11/2026. Tarkempi aikataulu sovitaan myöhemmin. Antamalla yksikköhintaisen urakkatarjouksen urakoitsija vakuuttaa, että tarjoukseen sisältyvät kaikki urakan toteuttamisen kannalta oleelliset työvaiheet sekä työvaiheiden suorittamisessa tarvittavat materiaalit, koneet, laitteet ja työvoimat. Urakoitsijan on ennen tarjouksen antamista tutustuttava työkohteeseen ja sen työsuoritukselle tila ja muista rajoituksista. Tilaaja rakentaa samanaikaisesti risteysaluetta. Urakkaan kuuluu: paalujen hankinta, paalutustyöt, paalujen jatkaminen, kalliokärkien + paaluhattujen hankinta ja katkaisutyöt. Teräsputkipaalut D200 RR, seinämäpaksuus 12,5 mm, 4 kpl/ perustus.,','Stara (Helsingin kaupungin rakentamispalveluliikelaitos)','ANY',2,4,NULL,NULL,20000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056319','[\"45000000\"]','[\"ristipellontien\", \"paalutustyöt\", \"porttaaliperustusten\", \"helsingin\", \"kaupungin\", \"rakentamispalveluliikelaitos\", \"stara\", \"aikataulu\", \"paalujen\", \"hankinta\", \"pyytää\", \"yksikköhintaista\", \"urakkatarjoustanne\", \"vihdintie\", \"risteyksen\", \"porttaalin\", \"paalutuksen\", \"rakentamisesta\", \"suunnitelmien\", \"mukaisesti\"]',NULL,NULL,'[{\"url\": \"h