INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (614,'2026-056259','HILMA','RFP','OPEN','Laukaan kunnan työterveyspalveluiden hankinta / yhteishankinta (ml. nimetyt kuntakonserniin kuuluvat yhtiöt)','Laukaan kunnan työterveyspalveluiden hankinta / yhteishankinta (ml. nimetyt kuntakonserniin kuuluvat yhtiöt) Hankinnan kohteena on Laukaan kunnan ja nimettyjen kuntakonserniin kuuluvien yhtiöiden yhteishankinta työterveyspalvelujen tuottamisesta Tilaajalle ja sen henkilöstölle toteutettuna pääsääntöisesti palveluntarjoajan tiloissa Laukaassa. Selvyyden vuoksi todetaan, että Tilaaja varaa oikeuden päättää mahdollisten etäpalveluiden (digitaalisten palveluiden) käytöstä aina erikseen, eikä ko. etä-/digitaalisia Palveluita voida tuottaa ilman Tilaajan erillistä suostumusta. Ko. Palveluista sovitaan erikseen viimeistään toimintasuunnitelman laatimisen yhteydessä. Palveluntarjoajan niin toivoessa, Tilaajalla on mahdollisuus tarjota soveltuvia toimitiloja Palveluntuottajalle vuokrattavaksi tämän tarjouspyynnön mukaisten Palveluiden tuottamiseen. Mahdollisesta tilavuokrauksesta sovitaan kilpailutuksen voittajan kanssa erikseen. Jo kilpailutuksen aikana, mikäli tarvetta tiedustella tila-asioista, voitte olla yhteydessä Eero Raittilaan (eero.raittila@laukaa.fi). Työterveyshuollon palveluiden hankintaa ohjaa työnantajaa velvoittava työterveyshuollon lainsäädäntö (TTH 1382/2001). Työterveyshuollon palveluiden tulee sisältää TTH 1383/2001 12 §:n mukaiset toiminnot ennaltaehkäisevänä toimintana (KL1-toiminta). Hankinta sisältää option myös TTh1383/2001 14 §:n mukaisen työkykypainotteisen yleislääkäritasoisen sairaanhoidon (KL 2-toiminta) hankintaan sekä tätä laajemmat sairaanhoidon palvelut. Muut tiedot tarjouspyyntöasiakirjoissa.,','Laukaan kunta','ANY',3,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056259','[\"85147000\"]','[\"laukaan\", \"palveluiden\", \"kunnan\", \"hankinta\", \"yhteishankinta\", \"kuntakonserniin\", \"erikseen\", \"työterveyshuollon\", \"työterveyspalveluiden\", \"nimetyt\", \"kuuluvat\", \"yhtiöt\", \"palveluntarjoajan\", \"sovitaan\", \"yhteydessä\", \"kilpailutuksen\", \"eero\", \"sisältää\", \"toiminta\", \"sairaanhoidon\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/laukaa?id=626683&tpk=eb0bd8ed-064b-4115-99f6-c0000ef562d2\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056259\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56259\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Laukaan kunnan työterveyspalveluiden hankinta / yhteishankinta (ml. nimetyt kuntakonserniin kuuluvat yhtiöt)\", \"titleSv\": \"\", \"cpvCodes\": \"85147000\", \"currency\": null, \"deadline\": \"2026-09-28T09:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI198\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Hankinnan kohteena on Laukaan kunnan ja nimettyjen kuntakonserniin kuuluvien yhtiöiden yhteishankinta työterveyspalvelujen tuottamisesta Tilaajalle ja sen henkilöstölle toteutettuna pääsääntöisesti palveluntarjoajan tiloissa Laukaassa. Selvyyden vuoksi todetaan, että Tilaaja varaa oikeuden päättää mahdollisten etäpalveluiden (digitaalisten palveluiden) käytöstä aina erikseen, eikä ko. etä-/digitaalisia Palveluita voida tuottaa ilman Tilaajan erillistä suostumusta. Ko. Palveluista sovitaan erikseen viimeistään toimintasuunnitelman laatimisen yhteydessä. \\n\\nPalveluntarjoajan niin toivoessa, Tilaajalla on mahdollisuus tarjota soveltuvia toimitiloja Palveluntuottajalle vuokrattavaksi tämän tarjouspyynnön mukaisten Palveluiden tuottamiseen. Mahdollisesta tilavuokrauksesta sovitaan kilpailutuksen voittajan kanssa erikseen. Jo kilpailutuksen aikana, mikäli tarvetta tiedustella tila-asioista, voitte olla yhteydessä Eero Raittilaan (eero.raittila@laukaa.fi).  \\n\\nTyöterveyshuollon palveluiden hankintaa ohjaa työnantajaa velvoittava työterveyshuollon lainsäädäntö (TTH 1382/2001). Työterveyshuollon palveluiden tulee sisältää TTH 1383/2001 12 §:n mukaiset toiminnot ennaltaehkäisevänä toimintana (KL1-toiminta). \\n\\nHankinta sisältää option myös TTh1383/2001 14 §:n mukaisen työkykypainotteisen yleislääkäritasoisen sairaanhoidon (KL 2-toiminta) hankintaan sekä tätä laajemmat sairaanhoidon palvelut. \\n\\nMuut tiedot tarjouspyyntöasiakirjoissa.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-09-28T09:00:00Z\", \"circularEconomy\": true, \"endUserInvolved\": true, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": true, \"lotResultTotalAmount\": null, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": false, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": true, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCoun