INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (615,'2026-056260','HILMA','RFP','OPEN','Osaamisen kehittämisen hankinta 1. avaus','Osaamisen kehittämisen hankinta 1. avaus Hankinnan kohteena on Vantaan ja Keravan hyvinvointialueen (jäljempänä hyvinvointialue tai tilaaja) osaamisen kehittämisen hankinta. Kyseessä on hankintalain (Laki julkisista hankinnoista ja käyttöoikeussopimuksista 1397/2016) liitteen E mukainen kansallisen kynnysarvon ylittävä palveluhankinta. Hankinta toteutetaan dynaamisena hankintajärjestelynä, joka tarkoittaa hankintayksikön itsensä suunnittelemaa, hankintalain periaatteiden mukaista menettelyä hankinnan kohteena olevien palveluiden hankkimiseen. Dynaaminen hankintajärjestely voidaan avata yhden, useamman tai kaikkien osa-alueiden osalta. Tässä 1. avauksessa avataan kilpailulle ainoastaan hankinnan osa-alue 13. Itsenäisesti opiskeltavat valmiit verkko-oppimissisällöt (kirjastot) toimittajan valikoimasta. Kaikki soveltuvuusvaatimukset täyttäneet tarjoajat valitaan toimittajiksi. Sopimuskausi on toistaiseksi voimassa oleva. Tilaaja ei sitoudu tiettyihin vähimmäisostomääriin sopimuskaudella, vaan palveluja hankitaan tarpeen mukaan.,','Vantaan ja Keravan hyvinvointialue','ANY',1,4,NULL,NULL,5000000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056260','[\"80511000\", \"80420000\", \"80532000\", \"80533100\", \"80562000\"]','[\"hankinta\", \"osaamisen\", \"kehittämisen\", \"hankinnan\", \"avaus\", \"kohteena\", \"vantaan\", \"keravan\", \"hyvinvointialue\", \"tilaaja\", \"hankintalain\", \"hyvinvointialueen\", \"jäljempänä\", \"kyseessä\", \"laki\", \"julkisista\", \"hankinnoist