INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (618,'2026-056342','HILMA','RFP','OPEN','Hiekoitussepelin hankinta','Helsingin yliopiston kiinteistöpalvelut Oy kilpailuttaa hiekoitussepelin hankinnan Helsingin yliopistokonsernin käyttöön. Hankinnan kohteena on liukkaudenestoon käytettävä hiekoitussepeli toimitettuna siiloihin, hiekkahuoneeseen tai aumaan. Tarkempi palvelukuvaus on tarjouspyynnön liitteenä. Hankinta on jaettu osiin ja mikäli yksi toimittaja tulee valituksi useampaan osaan, yhdistetään nämä osat yhdelle hankintasopimukselle., Helsingin yliopiston kampukset Hankinnan kohteena on hiekoitussepelin toimitus siiloihin ja hiekkatilaan Viikin, Keskustan, Kumpulan ja Meilahden kampuksilla., Hyytiälän metsäasema Hankinnan kohteena on hiekoitussepelin toimitus siiloihin Hyytiälän metsäasemalla., Tvärminnen eläintieteellinen asema Hankinnan kohteena on hiekoitussepelin toimitus siiloon Tvärminnen eläintieteellisellä asemalla., Lammin biologinen asema Hankinnan kohteena on hiekoitussepelin toimitus aumaan Lammin biologisella asemalla., Kasvitieteelliset puutarhat Hankinnan kohteena on hiekoitussepelin toimitus siiloihin Kaisaniemen ja Kumpulan kasvitieteellisillä puutarhoilla. Käytävien materiaaliksi on arkkitehtisuunnittelun tuloksena valittu Raaseporin Meltolan kivilouhimon punagraniitti, joten kulttuurihistoriallisesti tärkeässä ja suojellussa ympäristössä on välttämätöntä säilyttää alkuperäinen materiaali ja väri. Käytävät toimivat osana geologista tiedepolkua, jossa esitellään suomalaisia kivilajeja. Aitouden säilyttämiseksi on hiekoitussepeli oltava samalta louhokselta kuin käytävien perustukseen käytetty materiaali.,','Helsingin yliopiston kiinteistöpalvelut Oy','ANY',1,4,NULL,NULL,220000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056342','[\"14212300\", \"14212320\"]','[\"hiekoitussepelin\", \"hankinnan\", \"kohteena\", \"toimitus\", \"helsingin\", \"siiloihin\", \"yliopiston\", \"hankinta\", \"kiinteistöpalvelut\", \"hiekoitussepeli\", \"aumaan\", \"kumpulan\", \"hyytiälän\", \"tvärminnen\", \"asema\", \"asemalla\", \"lammin\", \"käytävien\", \"materiaali\", \"kilpailuttaa\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/helsinginyliopisto?id=613468&tpk=e93a7409-b776-4855-aab6-b5c693abdef6\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056342\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56342\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Helsingin yliopiston kampukset\", \"titleSv\": \"\", \"cpvCodes\": \"14212300\", \"currency\": \"EUR\", \"deadline\": \"2026-10-05T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Hankinnan kohteena on hiekoitussepelin toimitus siiloihin ja hiekkatilaan Viikin, Keskustan, Kumpulan ja Meilahden kampuksilla.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 180000.0, \"expirationDate\": \"2026-10-05T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeP