INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (620,'2026-056339','HILMA','RFP','OPEN','Kultarannan tapahtumapaviljongin arkkitehtuurikutsukilpailu','Kultarannan tapahtumapaviljongin arkkitehtuurikutsukilpailu Tasavallan presidentin kanslia järjestää yksivaiheisen suppean arkkitehtuurikutsukilpailun uuden tapahtumapaviljongin suunnittelusta Naantalin Kultarantaan. Kilpailu toteutetaan yhteistyönä Suomen Arkkitehtiliiton (SAFA) kanssa ja sen kilpailusääntöjen mukaisesti. Kilpailun tavoitteena on löytää Kultarannan uudelle, noin 800 m2 laajuiselle, tapahtumapaviljongille arvokkaaseen ympäristöön sopiva ratkaisu jatko- ja toteutussuunnittelun pohjaksi. Tavoitteet on kuvattu yksityiskohtaisemmin hankintailmoituksen liitteenä olevassa kilpailuohjelman luonnoksessa. Kilpailuun voivat ilmoittautua ehdokkaat, jotka täyttävät osallistumishakemuslomakkeessa määritellyt tehtävän edellyttämät soveltuvuusvaatimukset ja vähimmäisehdot. Vaatimukset täyttävistä ehdokkaista arvotaan kuusi (6) työryhmää varsinaiseen kilpailuun. Kilpailuehdotusten arvosteluperusteet esitetään kilpailuohjelman luonnoksessa. Kilpailuohjelmaa täsmennetään ennen kilpailun alkua yhdessä myöhemmin valittavan Suomen Arkkitehtiliiton nimeämän tuomariston jäsenen kanssa.,','Tasavallan presidentin kanslia','SME',5,1,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056339','[\"71000000\", \"71230000\"]','[\"kultarannan\", \"tapahtumapaviljongin\", \"arkkitehtuurikutsukilpailu\", \"tasavallan\", \"presidentin\", \"kanslia\", \"suomen\", \"arkkitehtiliiton\", \"kanssa\", \"kilpailun\", \"kilpailuohjelman\", \"luonnoksessa\", \"kilpailuun\", \"järjestää\", \"yksivaiheisen\", \"suppean\", \"arkkitehtuurikutsukilpailun\", \"uuden\", \"suunnittelusta\", \"naantalin\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/presidentti?id=626296&tpk=a451bd17-7dbb-4209-807e-3e9c97d36245\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056339\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56339\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Kultarannan tapahtumapaviljongin arkkitehtuurikutsukilpailu\", \"titleSv\": \"\", \"cpvCodes\": \"71000000 71230000\", \"currency\": null, \"deadline\": \"2026-10-12T10:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI1C1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Tasavallan presidentin kanslia järjestää yksivaiheisen suppean arkkitehtuurikutsukilpailun uuden tapahtumapaviljongin suunnittelusta Naantalin Kultarantaan. Kilpailu toteutetaan yhteistyönä Suomen Arkkitehtiliiton (SAFA) kanssa ja sen kilpailusääntöjen mukaisesti.\\n \\nKilpailun tavoitteena on löytää Kultarannan uudelle, noin 800 m2 laajuiselle, tapahtumapaviljongille arvokkaaseen ympäristöön sopiva ratkaisu jatko- ja toteutussuunnittelun pohjaksi. Tavoitteet on kuvattu yksityiskohtaisemmin hankintailmoituksen liitteenä olevassa kilpailuohjelman luonnoksessa.\\n\\nKilpailuun voivat ilmoittautua ehdokkaat, jotka täyttävät osallistumishakemuslomakkeessa määritellyt tehtävän edellyttämät soveltuvuusvaatimukset ja vähimmäisehdot. Vaatimukset täyttävistä ehdokkaista arvotaan kuusi (6) työryhmää varsinaiseen kilpailuun. \\n\\nKilpailuehdotusten arvosteluperusteet esitetään kilpailuohjelman luonnoksessa. Kilpailuohjelmaa täsmennetään ennen kilpailun alkua  yhdessä myöhemmin valittavan Suomen Arkkitehtiliiton nimeämän tuomariston jäsenen kanssa.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-10-12T10:00:00Z