INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (625,'2026-056330','HILMA','RFP','OPEN','Otanmäki-Humpinsuo OYK:n vaatima vesihuoltokapasiteetin kasvattaminen','Otanmäki-Humpinsuo OYK:n vaatima vesihuoltokapasiteetin kasvattaminen Hankinnan kohteena on Otanmäki-Humpinsuo-osayleiskaava-alueen toteutuksen vaatiman vesihuoltokapasiteetin kasvattamisen vaatimien toimenpiteiden suunnittelu. Kajaanin kaupunki on kaavoittanut Otanmäki-Humpinsuo osayleiskaavan ja osana sitä Otanmäki-Alussuo asemakaavaan, jotka mahdollistavat datakeskustoimintojen sijoittamisen alueelle, jonka nykyinen vesihuoltokapasiteetti ei ole riittävä suunnitelluille toiminnoille. Kajaanin Vesi -liikelaitos kilpailuttaa Otanmäki-Humpinsuo osayleiskaavan vaatiman vesihuoltokapasiteetin kasvattamiseen liittyvän vesihuoltosuunnittelukokonaisuuden, joka arvion mukaan sisältää (tarkentuu tarvittaessa suunnittelun edetessä) mm.: -Toimenpidetarpeiden tarkentamisen (ja mitoittamisen) Kajaanin Veden verkostomallilla (Fluidit) -Uuden alavesisäiliö- ja paineenkorottamosuunnittelun kohteen välittömään läheisyyteen -Jätevedenpumppaamosuunnittelua, kohteiden määrä ja laatu tarkennettava verkostomallilla -Olemassa olevan alavesisäiliön ja paineenkorottamoiden putkistomuutosten ja kapasiteetin lisäyksen suunnittelua tarvittavilta osin -Talousvesi- ja jätevesiverkostosuunnittelun tarvittavilta osin -Muutostoimenpiteiden vaatiman ohjausautomatiikan muutossuunnittelun Uudelle kaava-alueelle on alustavasti suunniteltu johdettavan talousvettä Kajaanin taajama-alueelta suunniteltavan syöttöjärjestelyn avulla ja olemassa olevaa yhdysvesijohtoa hyödyntäen nykyinen virtaussuunta kääntäen. Kaava-alueen läheisyyteen sijoitetaan alavesisäiliö ja paineenkorottamo. Tarvittaessa yhdysvesijohdon paineenkorottamoiden kapasiteettia lisätään. Kaava-alueen jätevedet viemäröidään Otanmäen nykyisen asemakaava-alueen ja olemassa olevan siirtoviemärin kautta Kajaanin Peuraniemen jätevedenpuhdistamolle. Viemäröinnin toteuttaminen vaatinee uuden viemärin rakentamista, vanhan saneerausta, jätevesipumppaamoiden rakentamista ja saneerausta sekä tarvittaessa kapasiteetin kasvattamista niin nykyisellä Otanmäen asemakaava-alueella kuin siirtoviemärillä. Kapasiteetin lisäämiseksi tarvittavista toimenpiteistä priorisoidaan ne, jotka ovat välttämättömiä Otanmäki-Alussuo asemakaava-alueen vaatiman vesihuollon kapasiteetin toteuttamiseksi. Nämä toimenpiteet suunnitellaan toteutukseen ja kilpailutukseen asti ja niistä laaditaan tarvittava tarjouspyyntömateriaali. Muu suunnittelu toteutetaan yleissuunnitelmatasolla.,','Kajaanin kaupunki / Kajaanin Vesi -liikelaitos','ANY',5,3,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056330','[\"71320000\"]','[\"otanmäki\", \"kajaanin\", \"humpinsuo\", \"alueen\", \"vesihuoltokapasiteetin\", \"vaatiman\", \"kapasiteetin\", \"tarvittaessa\", \"olemassa\", \"kaava\", \"asemakaava\", \"vaatima\", \"kasvattaminen\", \"suunnittelu\", \"kaupunki\", \"osayleiskaavan\", \"alussuo\", \"jotka\", \"alueelle\", \"nykyinen\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/kajaani?id=610016&tpk=c05107f1-a4fe-4f44-8d2e-84aee8042dcc\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056330\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56330\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Otanmäki-Humpinsuo OYK:n vaatima vesihuoltokapasiteetin kasvattaminen\", \"titleSv\": \"\", \"cpvCodes\": \"71320000\", \"currency\": null, \"deadline\": \"2026-09-24T11:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1D8\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Hankinnan kohteena on Otanmäki-Humpinsuo-osayleiskaava-alueen toteutuksen vaatiman vesihuoltokapasiteetin kasvattamisen vaatimien toimenpiteiden suunnittelu. Kajaanin kaupunki on kaavoittanut Otanmäki-Humpinsuo osayleiskaavan ja osana sitä Otanmäki-Alussuo asemakaavaan, jotka mahdollistavat datakeskustoimintojen sijoittamisen alueelle, jonka nykyinen vesihuoltokapasiteetti ei ole riittävä suunnitelluille toiminnoille. Kajaanin Vesi -liikelaitos kilpailuttaa Otanmäki-Humpinsuo osayleiskaavan vaatiman vesihuoltokapasiteetin kasvattamiseen liittyvän vesihuoltosuunnittelukokonaisuuden, joka arvion mukaan sisältää (tarkentuu tarvittaessa suunnittelun edetessä) mm.:\\n\\n-Toimenpidetarpeiden tarkentamisen (ja mitoittamisen) Kajaanin Veden verkostomallilla (Fluidit)\\n-Uuden alavesisäiliö- ja paineenkorottamosuunnittelun kohteen välittömään läheisyyteen\\n-Jätevedenpumppaamosuunnittelua, kohteiden määrä ja laatu tarkennettava verkostomallilla\\n-Olemassa olevan alavesisäiliön ja paineenkorottamoiden putkistomuutosten ja kapasiteetin lisäyksen suunnittelua tarvittavilta osin\\n-Talousvesi- ja jätevesiverkostosuunnittelun tarvittavilta osin \\n-Muutostoimenpiteiden vaatiman ohjausautomatiikan muutossuunnittelun\\n\\nUudelle kaava-alueelle on alustavasti suunniteltu johdettavan talousvettä Kajaanin taajama-alueelta suunniteltavan syöttöjärjestelyn avulla ja olemassa olevaa yhdysvesijohtoa hyödyntäen nykyinen virtaussuunta kääntäen. Kaava-alueen läheisyyteen sijoitetaan alavesisäiliö ja paineenkorottamo. Tarvittaessa yhdysvesijohdon paineenkorottamoiden kapasiteettia lisätään. Kaava-alueen jätevedet viemäröidään Otanmäen nykyisen asemakaava-alueen ja olemassa olevan siirtoviemärin kautta Kajaanin Peuraniemen jätevedenpuhdistamolle. Viemäröinnin toteuttaminen vaatinee uuden viemärin rakentamista, vanhan saneerausta, jätevesipumppaamoiden rakentamista ja saneerausta sekä tarvittaessa kapasiteetin kasvattamista niin nykyisellä Otanmäen asemakaava-alueella kuin siirtoviemärillä.\\n\\nKapasiteetin lisäämiseksi tarvittavista toimenpiteistä priorisoidaan ne, jotka ovat välttämättömiä Otanmäki-Alussuo asemakaava-alueen vaatiman vesihuollon kapasiteetin toteuttamiseksi. Nämä toimenpiteet suunnitellaan toteutukseen ja kilpailutukseen asti ja niistä laaditaan tarvittava tarjouspyyntömateriaali. Muu suunnittelu toteutetaan yleissuunnitelmatasolla.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-09-24T11:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"17\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Otanmäki-Humpinsuo OYK:n vaatima vesihuoltokapasiteetin kasvattaminen\", \"titleSv\": \"\", \"cpvCodes\": \"71320000\", \"currency\":