INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (627,'2026-056327','HILMA','RFP','OPEN','Nestekromatografi ja detektorit','Nestekromatografi ja detektorit HUS Diagnostiikkakeskuksen Erikoiskemian laboratorio hankkii yhden binääripumpulla varustetun erittäin korkean paineen nestekromatografin (UHPLC). Hankintaan sisältyy lisäksi optiot viidestä vastaavasta UHPLC-laitteistosta ja neljästä MS/MS-laitteistosta sekä yhdestä UV/VIS-detektorista ja kahdesta fluoresenssidetektorista, jotka ovat UHPLC-yhteensopivia. Tarjottujen laitteistojen tulee voida muodostaa yhteensopiva laitteistokokonaisuus. Optioiden käytöstä päätetään vuosien 2027-2030 aikana. Tämän lisäksi hankintaan sisältyy tarvittavat laitesidonnaiset tarvikkeet, huoltosopimus sekä työasema kaikkine ohjelmistoineen/kaikki ohjelmistot, jotka laitteisto tarvitsee toimiakseen aiotussa tarkoituksessaan, työasemalle asennettuina. Kokonaisuus hankitaan yhdeltä toimittajalta. Hankittavalla laitteistolla tullaan analysoimaan potilasnäytteitä.,','HUS-yhtymä','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056327','[\"33100000\", \"38000000\"]','[\"uhplc\", \"nestekromatografi\", \"detektorit\", \"hankintaan\", \"sisältyy\", \"lisäksi\", \"laitteistosta\", \"jotka\", \"yhtymä\", \"diagnostiikkakeskuksen\", \"erikoiskemian\", \"laboratorio\", \"hankkii\", \"yhden\", \"binääripumpulla\", \"varustetun\", \"erittäin\", \"korkean\", \"paineen\", \"nestekromatografin\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/huslogistiikka?id=602258&tpk=449f4874-d889-48e6-8a8c-468ae9aaa976\", \"name\": \"Procurement Documents\"}, {\"url\": \"htt