INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (628,'2026-056326','HILMA','RFP','OPEN','Oikomishoidon hammastekniset laboratoriotyöt','Oikomishoidon hammastekniset laboratoriotyöt Kanta-Hämeen hyvinvointialue pyytää tarjouksia oikomishoidon hammasteknisistä laboratoriotöistä (oikomiskojeet) tarjouspyyntöasiakirjojen mukaisesti. Hankinnan kohde on kuvattu tarkemmin liitteessä 1. Palvelukuvaus ja liitteessä 2. Hintaliite. Palvelualueet tarjouspyynnön julkaisuhetkellä ovat Hämeenlinnan palvelualue (toimipisteet: Jukola, Ahveniston sairaala, Turenki, Lammi ja Hattula Parola), Riihimäen palvelualue (toimipisteet: Riihimäki, Oitti, Loppi ja Tervakoski) ja Forssan palvelualue (toimipisteet: Forssa, Jokioinen, Ypäjä, Humppila ja Tammela). Arvioitu suunniteltu sopimuskausi on 1.11.2026- 31.10.2030. Hankitaan valitaan yksi (1) sopimustoimittaja ja lisäksi valitaan yksi (1) varatoimittaja, jonka kanssa sopimus tehdään vain, jos sopimus ensisijaisesti valitun toimittajan kanssa päättyy hankintayksiköstä johtumattomista sopimuksista. Tilaajalla ei sitoudu vähimmäisostomääriin vaan palvelua hankintaan Tilaajan tarpeen mukaisesti. Hankintaa ei ole jaettu osiin palvelun luonteen ja toteuttamistavan vuoksi. Palveluun sisältyy kuljetukset 5 krt viikossa vähintään 3 eri toimipisteeseen. Kahden toimittajan mallilla syntyisi tarpeettomia kustannuksia. Lisäksi hankinnan keskittämisellä haetaan säätöjä. Tarjouspyyntöä edelsi markkinavuoropuhelu, josta julkaistiin ilmoitus Hilma -palvelussa 11.5.2026.,','Kanta-Hämeen hyvinvointialue','ANY',3,2,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056326','[\"85130000\