INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (635,'2026-056310','HILMA','RFI','OPEN','Kutsu markkinavuoropuheluun: Oulun Tuotantokeittiö Oy, Lööki - etikettitarrat ja värinauhat','Kutsu markkinavuoropuheluun: Oulun Tuotantokeittiö Oy, Lööki - etikettitarrat ja värinauhat Tämä ei ole hankintailmoitus eikä tarjouspyyntö, vaan kutsu markkinavuoropuheluun. Tähän tietopyyntöön ei voi jättää tarjousta. Oulun Tuotantokeittiö Oy järjestää kaikille avoimen markkinavuoropuhelun- ja keskustelutilaisuuden elintarvikepakkausten etikettitarrojen ja värinauhojen hankinnasta. Hankinta ei sisällä laitteita. Tämä ilmoitus ei velvoita hankintayksiköitä toteuttamaan varsinaista hankintaa, eikä hankintayksikkö sitoudu tekemään tämän ilmoituksen mukaisia hankintoja. Päätös tarjouskilpailun käynnistämisestä tehdään esiselvityksen ja markkinakartoituksen jälkeen. Ilmoitetut tiedot hankinnasta tai hankintamenettelystä eivät ole hankintayksikköjä sitovia mahdollisessa myöhemmässä hankintamenettelyssä. Lopullinen sisältö tarkentuu mahdollisesti myöhemmin julkaistavaan lopulliseen tarjouspyyntöön. MARKKINAVUOROPUHELU Markkinavuoropuhelutilaisuus järjestetään 6.-7.10.2026. Teamsin välityksellä ja aikaa varataan aikaa 45 min / yhden toimittajan vuoropuheluun. Markkinavuoropuhelu tullaan toteuttamaan suomen kielellä. Markkinavuoropuhelutilaisuudessa esitellään tulevan hankinnan tarkoitus ja tavoitteet sekä yleisesti hankintaprosessi aikatauluineen (ei sitova). Alustava aikataulu uudelle sopimukselle on alkaen 1.2.2027. Markkinavuoropuhelun/tietopyynnön tarkoituksena on tiedottaa markkinoita tulevasta kilpailutuksesta, kartoittaa markkinoiden tilannetta, mahdollistaa kommenttien esittäminen tulevasta hankinnasta sekä saada hankintaa koskevaa tietoa, jotta varsinainen tarjouskilpailu voidaan toteuttaa mahdollisimman tarkoituksenmukaisella tavalla. Tietopyyntö ei velvoita Oulun Tuotantokeittiö Oy:tä toteuttamaan hankintaa tietopyynnössä kuvatulla tavalla. Oulun Tuotantokeittiö Oy voi jättää tarjouskilpailun kokonaan toteuttamatta. Oulun Tuotantokeittiö Oy ei ole velvollinen ottamaan huomioon tietopyyntöön saatuja vastauksia tarjouspyynnön laadinnassa. Tietopyyntöön vastaaminen ei sido toimittajaa tarjouskilpailuun osallistumiseen, eikä ole myöskään edellytyksenä myöhemmin varsinaiseen tarjouskilpailuun osallistumiselle. Tietopyyntöön vastaamatta jättäminen ei estä mahdolliseen tarjouskilpailuun osallistumista, eikä tietopyyntöön vastaaminen vaikuta tarjoajan asemaan varsinaisessa tarjouskilpailussa. Tällä tietopyynnöllä kerätyt tiedot säilyvät täysin luottamuksellisina ja niitä tullaan käyttämään ainoastaan hankinnan kehittämiseen ja suunnitteluun. Tietopyyntöön vastanneille ja/tai markkinavuoropuheluun osallistuville ei makseta korvausta eikä Oulun Tuotantokeittiö Oy korvaa tietopyyntöön vastaamisesta aiheutuvia kustannuksia.,','Oulun Tuotantokeittiö Oy','ANY',1,5,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056310','[\"30192300\", \"30192800\", \"30199400\"]','[\"oulun\", \"tuotantokeittiö\", \"tietopyyntöön\", \"eikä\", \"markkinavuoropuheluun\", \"kutsu\", \"hankinnasta\", \"toteuttamaan\", \"hankintaa\", \"tarjouskilpailuun\", \"lööki\", \"etikettitarrat\", \"värinauhat\", \"tämä\", \"jättää\", \"markkinavuoropuhelun\", \"velvoita\", \"tarjouskilpailun\", \"tiedot\", \"myöhemmin\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/monetra?id=626423&tpk=38e8b69f-5cd0-4c6f-bdd9-8731e1e8aca3\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056310\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56310\", \"lots\": [{\"id\": \"PAR-0000\", \"titleEn\": \"\", \"titleFi\": \"Kutsu markkinavuoropuheluun: Oulun Tuotantokeittiö Oy, Lööki - etikettitarrat ja värinauhat\", \"titleSv\": \"\", \"cpvCodes\": \"30192300 30192800 30199400\", \"currency\": null, \"deadline\": null, \"lowCarbon\": null, \"nutsCodes\": \"FI1D9\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Tämä ei ole hankintailmoitus eikä tarjouspyyntö, vaan kutsu markkinavuoropuheluun. Tähän tietopyyntöön ei voi jättää tarjousta.\\n\\nOulun Tuotantokeittiö Oy järjestää kaikille avoimen markkinavuoropuhelun- ja keskustelutilaisuuden elintarvikepakkausten etikettitarrojen ja värinauhojen hankinnasta. Hankinta ei sisällä laitteita.\\n\\nTämä ilmoitus ei velvoita hankintayksiköitä toteuttamaan varsinaista hankintaa, eikä hankintayksikkö sitoudu tekemään tämän ilmoituksen mukaisia hankintoja. Päätös tarjouskilpailun käynnistämisestä tehdään esiselvityksen ja markkinakartoituksen jälkeen. Ilmoitetut tiedot hankinnasta tai hankintamenettelystä eivät ole hankintayksikköjä sitovia mahdollisessa myöhemmässä hankintamenettelyssä. Lopullinen sisältö tarkentuu mahdollisesti myöhemmin julkaistavaan lopulliseen tarjouspyyntöön.\\n\\nMARKKINAVUOROPUHELU\\n\\nMarkkinavuoropuhelutilaisuus järjestetään 6.-7.10.2026. Teamsin välityksellä ja aikaa varataan aikaa 45 min / yhden toimittajan vuoropuheluun. Markkinavuoropuhelu tullaan toteuttamaan suomen kielellä.\\n\\nMarkkinavuoropuhelutilaisuudessa esitellään tulevan hankinnan tarkoitus ja tavoitteet sekä yleisesti hankintaprosessi aikatauluineen (ei sitova). Alustava aikataulu uudelle sopimukselle on alkaen 1.2.2027.\\n\\nMarkkinavuoropuhelun/tietopyynnön tarkoituksena on tiedottaa markkinoita tulevasta kilpailutuksesta, kartoittaa markkinoiden tilannetta, mahdollistaa kommenttien esittäminen tulevasta hankinnasta sekä saada hankintaa koskevaa tietoa, jotta varsinainen tarjouskilpailu voidaan toteuttaa mahdollisimman tarkoituksenmukaisella tavalla.\\n\\nTietopyyntö ei velvoita Oulun Tuotantokeittiö Oy:tä toteuttamaan hankintaa tietopyynnössä kuvatulla tavalla. Oulun Tuotantokeittiö Oy voi jättää tarjouskilpailun kokonaan toteuttamatta. Oulun Tuotantokeittiö Oy ei ole velvollinen ottamaan huomioon tietopyyntöön saatuja vastauksia tarjouspyynnön laadinnassa.\\n\\nTietopyyntöön vastaaminen ei sido toimittajaa tarjouskilpailuun osallistumiseen, eikä ole myöskään edellytyksenä myöhemmin varsinaiseen tarjouskilpailuun osallistumiselle. \\n\\nTietopyyntöön vastaamatta jättäminen ei estä mahdolliseen tarjouskilpailuun osallistumista, eikä tietopyyntöön vastaaminen vaikuta tarjoajan asemaan varsinaisessa tarjouskilpailussa.\\n\\nTällä tietopyynnöllä kerätyt tiedot säilyvät täysin luottamuksellisina ja niitä tullaan käyttämään ainoastaan hankinnan kehittämiseen ja suunnitteluun.\\n\\nTietopyyntöön vastanneille ja/tai markkinavuoropuheluun osallistuville ei makseta korvausta eikä Oulun Tuotantokeittiö Oy korvaa tietopyyntöön vastaamisesta aiheutuvia kustannuksia.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2027-03-06T08:05:04.441Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": null, \"lotResultTotalAmount\": null, \"justWorkingConditions\": null, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": null, \"includesFrameworkAgreement\": null, \"smeParticipationConsidered\": null, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": null, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEst