INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (636,'2026-056309','HILMA','RFP','OPEN','Ruokatuote','Ruokatuote Hankinnan kohteena on esivalmisteltujen ruokatuotekomponenttien tuottaminen Kangasalan, Nokian, Oriveden ja Ylöjärven kaupunkien sekä Lempäälän ja Pirkkalan kuntien ateria- ja siivouspalveluiden kohteisiin. Komponentit koskevat pääruokaa kuten: kastikkeet, keitot, kiusaukset, pastaruoat ja puurot. Lisäksi hankintaan kuuluu energialisäke (perunasose). Hankintaan eivät kuulu muut lisäkkeet, salaatit tai juomat.,','Kuntien Hankintapalvelut KuHa Oy','ANY',1,11,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056309','[\"15000000\"]','[\"kuntien\", \"ruokatuote\", \"hankintaan\", \"hankintapalvelut\", \"kuha\", \"hankinnan\", \"kohteena\", \"esivalmisteltujen\", \"ruokatuotekomponenttien\", \"tuottaminen\", \"kangasalan\", \"nokian\", \"oriveden\", \"ylöjärven\", \"kaupunkien\", \"lempäälän\", \"pirkkalan\", \"ateria\", \"siivouspalveluiden\", \"kohteisiin\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/kuha?id=623381&tpk=37063a7d-07f1-4a04-b9ee-ca81479d6622\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056309\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56309\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Ruokatuote\", \"titleSv\": \"\", \"cpvCodes\": \"15000000\", \"currency\": null, \"deadline\": \"2026-10-19T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Hankinnan ko