INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (638,'2026-056305','HILMA','RFI','OPEN','Ryhti-ohjelmistokehitys Bentley Systems Finland Oy:n OCM ja Sitowise Oy:n Louhi-järjestelmiin suorahankintana','Ryhti-ohjelmistokehitys Bentley Systems Finland Oy:n OCM ja Sitowise Oy:n Louhi-järjestelmiin suorahankintana Kuntien tulee toimittaa rakentamisen ja alueidenkäytön tietoja valtakunnalliseen Rakennetun ympäristön tietojärjestelmään (Ryhti) viimeistään 1.1.2029 alkaen. Tietojen toimittaminen edellyttää kuntien käytössä olevien ohjelmistojen kehittämistä, jota varten Ympäristöministeriö myöntää avustuksia kunnille kumppanitestaushankkeisiin. Porvoon kaupunki haki 30.3.2026 rahoitusta Kuntien ja maakuntien liittojen rakennetun ympäristön tiedonhallinnan uudistamiseen 5.hakukierroksella (va-ym-2026–5) Porvoon kaupungin kaupunkikehitysjohtajan 30.3.2026 allekirjoittamana ”Louhi alueiden käytön ja sitovien tonttijakojen ratkaisun kehittämiseen ja käyttöönottamiseen Porvoon kaupungilla eli LASTI-hankkeeseen. Ympäristöministeriö myönsi 16.6.2026 avustusta 295 000 €. LASTI-hankkeessa kehitetään Porvoon kaupungin Ryhti-prosessia alueidenkäytön tietojen osalta kaupungin käytössä olevia järjestelmiä kehittämällä ja yhteen toimivuutta parantamalla ja lopulta hankkeessa kehitetyt ominaisuudet käyttöönotetaan ja otetaan käyttöön kaupungilla Ryhti-prosessi. Kehitystyötä tehdään kahteen Porvoon kaupungin käytössä olevaan järjestelmään, missä OCM-järjestelmässä tuotetaan pääosa Ryhti-alueiden käytön tiedoista ja ominaisuuksista ja Louhi-järjestelmässä tehdään Ryhti-tiedon jatkokäsittelyä, elinkaaren hallintaa ja tiedon välitys Ryhti-järjestelmään rajapinnan kautta, • Bentley Systems Finland Oy:n OpenCities Map for Finland (OCM)-ohjelmistoa jatkokehitetään Ryhti-tietomallimuotoisten asemakaavojen tuotannon osalta ja kehitetään uutena ominaisuutena sitovien tonttijakojen toimintoja ja ominaisuuksia, sekä toimintoja GeoJSON lukuun, tiedon validointiin ja tallennukseen Louhi-jatkokäsittelyä varten. • Sitowise Oy:n Louhi Kaava sovellusta kehitetään kaavatietojen käsittelyä ja elinkaaren hallintaa ja toteutetaan uusina toimintoina sitovien tonttijakojen luku Louheen GeoJSON muodossa. Lisäksi toteutetaan tietojen täydentäminen, validointiin liittyviä toimintoja ja edellä mainittujen tietojen siirto rajapinnan kautta Ryhtiin. • Hankkeessa kehitetyt uudet ominaisuudet tulevat kaikkien edellä mainittuja järjestelmiä käyttävien käyttöön ilman kustannuksia. Lasti-hankkeen päähakijana toimii Porvoon kaupunki, eli Porvoo hankkeen teknisenä hallinnoijana ja vastaa hankkeeseen sisältyvän ostopalvelun hankinnasta ja ohjelmiston testaamisesta sekä siitä, että hankkeessa kehitetyt Ryhti-toiminnallisuudet ohjelmistoista otetaan tuotantokäyttöön. Yhteistyötahoina ja järjestelmä-/ohjelmistokehittäjinä ovat Sitowise Oy, sekä Bentley Systems Finland Oy ja GeoIDT, joka toimii Bentley Systems Finland Oy alihankkijana/konsulttina. Ympäristöministeriö voi korvata hankkeen kustannuksia täysimääräisesti myönnettyyn avustussummaan asti. Hankkeessa tehtävä tietojärjestelmien ja ohjelmistojen kehitystyö jaetaan korvauksetta muille Sitowisen ja Bentley Systems Finlandin käyttäjäkunnille. Hankkeessa tehtävä ohjelmistokehitystyö hankitaan Sitowise Oy ja Bentley Systems Finland Oy:ltä suorahankintana. Kehitystyö on jaettu kolmeen työpakettiin, joiden yhteenlaskettu kustannus ostopalveluiden osalta noin 283 751 € (alv 0). Porvoon kaupungin omat henkilötyökustannukset ovat 7098 €, lisäksi hankkeeseen kuuluvia matka- ja muita kuluja on 4651 € Perustelut suorahankinnalle. Hankintalain 40 §:n 2 momentin 2 kohdan mukaan hankintayksikkö voi valita suorahankinnan jos, teknisestä tai yksinoikeuden suojaamiseen liittyvästä syystä vain tietty toimittaja voi toteuttaa hankinnan. Lisäedellytyksenä on, että järkeviä vaihtoehtoisia tai korvaavia ratkaisuja ei ole tähän hankkeen toteuttamiseen saatavilla eikä kilpailun puuttuminen johdu hankinnan ehtojen keinotekoisesta kaventamisesta. Hankkeessa kehitetään kaupungin käytössä olevan Bentley Systems Finlandin OpenCities Map ja Sitowisen Louhi-järjestelmän Ryhti-kyvykkyyttä täyttämään lakisääteisiä velvoitteita. Sitowisen Louhi-järjestelmän immateriaalioikeuksien omistajana vain Sitowise Oy pystyy toteuttamaan järjestelmän kehitystyötä. Samoin Bentley Systems Finlandin OpenCities Map Finland järjestelmän immateriaalioikeuksien omistajana vain Bentley Systems Finland Oy pystyy toteuttamaan järjestelmän kehitystyötä. Kummallakin toimittajilla on yksinoikeus käytettyihin järjestelmänratkaisuihin, teknologiaan ja lähdekoodiin järjestelmiensä osalta.,','Porvoon kaupunki','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056305','[\"48000000\"]','[\"ryhti\", \"bentley\", \"systems\", \"finland\", \"louhi\", \"porvoon\", \"hankkeessa\", \"sitowise\", \"kaupungin\", \"järjestelmän\", \"tietojen\", \"käytössä\", \"kehitetään\", \"osalta\", \"hankkeen\", \"suorahankintana\", \"kuntien\", \"ympäristöministeriö\", \"kaupunki\", \"sitovien\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056305\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56305\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Ryhti-ohjelmistokehitys Bentley Systems Finland Oy:n OCM ja Sitowise Oy:n Louhi-järjestelmiin suorahankintana\", \"titleSv\": \"\", \"cpvCodes\": \"48000000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": null, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Kuntien tulee toimittaa rakentamisen ja alueidenkäytön tietoja valtakunnalliseen Rakennetun ympäristön tietojärjestelmään (Ryhti) viimeistään 1.1.2029 alkaen. Tietojen toimittaminen edellyttää kuntien käytössä olevien ohjelmistojen kehittämistä, jota varten Ympäristöministeriö myöntää avustuksia kunnille kumppanitestaushankkeisiin.\\n\\nPorvoon kaupunki haki 30.3.2026 rahoitusta Kuntien ja maakuntien liittojen rakennetun ympäristön tiedonhallinnan uudistamiseen 5.hakukierroksella (va-ym-2026–5) Porvoon kaupungin kaupunkikehitysjohtajan 30.3.2026 allekirjoittamana ”Louhi alueiden käytön ja sitovien tonttijakojen ratkaisun kehittämiseen ja käyttöönottamiseen Porvoon kaupungilla eli LASTI-hankkeeseen. Ympäristöministeriö myönsi 16.6.2026 avustusta 295 000 €. \\n\\nLASTI-hankkeessa kehitetään Porvoon kaupungin Ryhti-prosessia alueidenkäytön tietojen osalta kaupungin käytössä olevia järjestelmiä kehittämällä ja yhteen toimivuutta parantamalla ja lopulta hankkeessa kehitetyt ominaisuudet käyttöönotetaan ja otetaan käyttöön kaupungilla Ryhti-prosessi.  Kehitystyötä tehdään kahteen Porvoon kaupungin käytössä olevaan järjestelmään, missä OCM-järjestelmässä tuotetaan pääosa Ryhti-alueiden käytön tiedoista ja ominaisuuksista ja Louhi-järjestelmässä tehdään Ryhti-tiedon jatkokäsittelyä, elinkaaren hallintaa ja tiedon välitys Ryhti-järjestelmään rajapinnan kautta,\\n• Bentley Systems Finland Oy:n OpenCities Map for Finland (OCM)-ohjelmistoa jatkokehitetään Ryhti-tietomallimuotoisten asemakaavojen tuotannon osalta ja kehitetään uutena ominaisuutena sitovien tonttijakojen toimintoja ja ominaisuuksia, sekä toimintoja GeoJSON lukuun, tiedon validointiin ja tallennukseen Louhi-jatkokäsittelyä varten. \\n• Sitowise Oy:n Louhi Kaava sovellusta kehitetään kaavatietojen käsittelyä ja elinkaaren hallintaa ja toteutetaan uusina toimintoina sitovien tonttijakojen luku Louheen GeoJSON muodossa. Lisäksi toteutetaan tietojen täydentäminen, validointiin liittyviä toimintoja ja edellä mainittujen tietojen siirto rajapinnan kautta Ryhtiin. \\n• Hankkeessa kehitetyt uudet ominaisuudet tulevat kaikkien edellä mainittuja järjestelmiä käyttävien käyttöön ilman kustannuksia. \\n\\nLasti-hankkeen päähakijana toimii Porvoon kaupunki, eli Porvoo hankkeen teknisenä hallinnoijana ja vastaa hankkeeseen sisältyvän ostopalvelun hankinnasta ja ohjelmiston testaamisesta sekä siitä, että hankkeessa kehitetyt Ryhti-toiminnallisuudet ohjelmistoista otetaan tuotantokäyttöön. Yhteistyötahoina ja järjestelmä-/ohjelmistokehittäjinä ovat Sitowise Oy, sekä Bentley Systems Finland Oy ja GeoIDT, joka toimii Bentley Systems Finland Oy alihankkijana/konsulttina. \\n\\nYmpäristöministeriö voi korvata hankkeen kustannuksia täysimääräisesti myönnettyyn avustussummaan asti. Hankkeessa tehtävä tietojärjestelmien ja ohjelmistojen kehitystyö jaetaan korvauksetta muille Sitowisen ja Bentley Systems Finlandin käyttäjäkunnille. Hankkeessa tehtävä ohjelmistokehitystyö hankitaan Sitowise Oy ja Bentley Systems Finland Oy:ltä suorahankintana. Kehitystyö on jaettu kolmeen työpakettiin, joiden yhteenlaskettu kustannus ostopalveluiden osalta noin 283 751 € (alv 0). Porvoon kaupungin omat henkilötyökustannukset ovat 7098 €, lisäksi hankkeeseen kuuluvia matka- ja muita kuluja on 4651 €\\n\\nPerustelut suorahankinnalle. Hankintalain 40 §:n 2 momentin 2 kohdan mukaan hankintayksikkö voi valita suorahankinnan jos, teknisestä tai yksinoikeuden suojaamiseen liittyvästä syystä vain tietty toimittaja voi toteuttaa hankinnan. Lisäedellytyksenä on, että järkeviä vaihtoehtoisia tai korvaavia ratkaisuja ei ole tähän hankkeen toteuttamiseen saatavilla eikä kilpailun puuttuminen johdu hankinnan ehtojen keinotekoisesta kaventamisesta. \\n\\nHankkeessa kehitetään kaupungin käytössä olevan Bentley Systems Finlandin OpenCities Map ja Sitowisen Louhi-järjestelmän Ryhti-kyvykkyyttä täyttämään lakisääteisiä velvoitteita. Sitowisen Louhi-järjestelmän immateriaalioikeuksien omistajana vain Sitowise Oy pystyy toteuttamaan järjestelmän kehitystyötä. Samoin Bentley Systems Finlandin OpenCities Map Finland järjestelmän immateriaalioikeuksien omistajana vain Bentley Systems Finland Oy pystyy toteuttamaan järjestelmän kehitystyötä.  Kummallakin toimittajilla on yksinoikeus käytettyihin järjestelmänratkaisuihin, teknologiaan ja lähdekoodiin järjestelmiensä osalta.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2027-03-06T08:05:03.59Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"Sitowise Oy (2335445-0)//Bentley Systems Finland Oy (0774171-7)\", \"innovationConsidered\": null, \"lotResultTotalAmount\": 283751.0, \"justWorkingConditions\": null, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": null, \"includesFrameworkAgreement\": null, \"smeParticipationConsidered\": null, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": \"EUR\", \"solutionNewToMarketOrIndustry\": null, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": null, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"25\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Ryhti-ohjelmistokehitys Bentley Systems Finland Oy:n OCM ja Sitowise Oy:n Louhi-järjestelmiin suorahankintana\", \"titleSv\": \"\", \"cpvCodes\": \"48000000\", \"currency\": null, \"deadline\": null, \"eFormsId\": \"84400dad-6705-4a26-822b-32d0ecd4dcae\", \"isEForms\": true, \"mainType\": \"PriorInformationNotices\", \"noticeId\": 56305, \"lowCarbon\": null, \"nutsCodes\": \"\", \"titleOther\": \"\", \"isCancelled\": false, \"procedureId\": 36744, \"biodiversity\": null, \"dateModified\": \"2026-09-06T08:05:03.626Z\", \"fullEFormsId\": \"84400dad-6705-4a26-822b-32d0ecd4dcae-01\", \"noticeNumber\": \"2026-056305\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2026-09-06T08:05:03.59Z\", \"descriptionEn\": \"\", \"descriptionFi\": \"Ryhti-ohjelmistokehitys Bentley Systems Finland Oy:n OCM ja Sitowise Oy:n Louhi-järjestelmiin suorahankintana Kuntien tulee toimittaa rakentamisen ja alueidenkäytön tietoja valtakunnalliseen Rakennetun ympäristön tietojärjestelmään (Ryhti) viimeistään 1.1.2029 alkaen. Tietojen toimittaminen edellyttää kuntien käytössä olevien ohjelmistojen kehittämistä, jota varten Ympäristöministeriö myöntää avustuksia kunnille kumppanitestaushankkeisiin.\\n\\nPorvoon kaupunki haki 30.3.2026 rahoitusta Kuntien ja maakuntien liittojen rakennetun ympäristön tiedonhallinnan uudistamiseen 5.hakukierroksella (va-ym-2026–5) Porvoon kaupungin kaupunkikehitysjohtajan 30.3.2026 allekirjoittamana ”Louhi alueiden käytön ja sitovien tonttijakojen ratkaisun kehittämiseen ja käyttöönottamiseen Porvoon kaupungilla eli LASTI-hankkeeseen. Ympäristöministeriö myönsi 16.6.2026 avustusta 295 000 €. \\n\\nLASTI-hankkeessa kehitetään Porvoon kaupungin Ryhti-prosessia alueidenkäytön tietojen osalta kaupungin käytössä olevia järjestelmiä kehittämällä ja yhteen toimivuutta parantamalla ja lopulta hankkeessa kehitetyt ominaisuudet käyttöönotetaan ja otetaan käyttöön kaupungilla Ryhti-prosessi.  Kehitystyötä tehdään kahteen Porvoon kaupungin käytössä olevaan järjestelmään, missä OCM-järjestelmässä tuotetaan pääosa Ryhti-alueiden käytön tiedoista ja ominaisuuksista ja Louhi-järjestelmässä tehdään Ryhti-tiedon jatkokäsittelyä, elinkaaren hallintaa ja tiedon välitys Ryhti-järjestelmään rajapinnan kautta,\\n• Bentley Systems Finland Oy:n OpenCities Map for Finland (OCM)-ohjelmistoa jatkokehitetään Ryhti-tietomallimuotoisten asemakaavojen tuotannon osalta ja kehitetään uutena ominaisuutena sitovien tonttijakojen toimintoja ja ominaisuuksia, sekä toimintoja GeoJSON lukuun, tiedon validointiin ja tallennukseen Louhi-jatkokäsittelyä varten. \\n• Sitowise Oy:n Louhi Kaava sovellusta kehitetään kaavatietojen käsittelyä ja elinkaaren hallintaa ja toteutetaan uusina toimintoina sitovien tonttijakojen luku Louheen GeoJSON muodossa. Lisäksi toteutetaan tietojen täydentäminen, validointiin liittyviä toimintoja ja edellä mainittujen tietojen siirto rajapinnan kautta Ryhtiin. \\n• Hankkeessa kehitetyt uudet ominaisuudet tulevat kaikkien edellä mainittuja järjestelmiä käyttävien käyttöön ilman kustannuksia. \\n\\nLasti-hankkeen päähakijana toimii Porvoon kaupunki, eli Porvoo hankkeen teknisenä hallinnoijana ja vastaa hankkeeseen sisältyvän ostopalvelun hankinnasta ja ohjelmiston testaamisesta sekä siitä, että hankkeessa kehitetyt Ryhti-toiminnallisuudet ohjelmistoista otetaan tuotantokäyttöön. Yhteistyötahoina ja järjestelmä-/ohjelmistokehittäjinä ovat Sitowise Oy, sekä Bentley Systems Finland Oy ja GeoIDT, joka toimii Bentley Systems Finland Oy alihankkijana/konsulttina. \\n\\nYmpäristöministeriö voi korvata hankkeen kustannuksia täysimääräisesti myönnettyyn avustussummaan asti. Hankkeessa tehtävä tietojärjestelmien ja ohjelmistojen kehitystyö jaetaan korvauksetta muille Sitowisen ja Bentley Systems Finlandin käyttäjäkunnille. Hankkeessa tehtävä ohjelmistokehitystyö hankitaan Sitowise Oy ja Bentley Systems Finland Oy:ltä suorahankintana. Kehitystyö on jaettu kolmeen työpakettiin, joiden yhteenlaskettu kustannus ostopalveluiden osalta noin 283 751 € (alv 0). Porvoon kaupungin omat henkilötyökustannukset ovat 7098 €, lisäksi hankkeeseen kuuluvia matka- ja muita kuluja on 4651 €\\n\\nPerustelut suorahankinnalle. Hankintalain 40 §:n 2 momentin 2 kohdan mukaan hankintayksikkö voi valita suorahankinnan jos, teknisestä tai yksinoikeuden suojaamiseen liittyvästä syystä vain tietty toimittaja voi toteuttaa hankinnan. Lisäedellytyksenä on, että järkeviä vaihtoehtoisia tai korvaavia ratkaisuja ei ole tähän hankkeen toteuttamiseen saatavilla eikä kilpailun puuttuminen johdu hankinnan ehtojen keinotekoisesta kaventamisesta. \\n\\nHankkeessa kehitetään kaupungin käytössä olevan Bentley Systems Finlandin OpenCities Map ja Sitowisen Louhi-järjestelmän Ryhti-kyvykkyyttä täyttämään lakisääteisiä velvoitteita. Sitowisen Louhi-järjestelmän immateriaalioikeuksien omistajana vain Sitowise Oy pystyy toteuttamaan järjestelmän kehitystyötä. Samoin Bentley Systems Finlandin OpenCities Map Finland järjestelmän immateriaalioikeuksien omistajana vain Bentley Systems Finland Oy pystyy toteuttamaan järjestelmän kehitystyötä.  Kummallakin toimittajilla on yksinoikeus käytettyihin järjestelmänratkaisuihin, teknologiaan ja lähdekoodiin järjestelmiensä osalta.,\", \"descriptionSv\": \"\", \"isCorrigendum\": false, \"linkedNotices\": \"\", \"procedureType\": \"oth-single\", \"sendingSystem\": \"Cloudia Kilpailutus\", \"estimatedValue\": null, \"expirationDate\": \"2027-03-06T08:05:03.59Z\", \"parentNoticeId\": null, \"circularEconomy\": null, \"endUserInvolved\": null, \"isEuProcurement\": true, \"noticeOjsNumber\": \"\", \"contractFolderId\": \"7f31f4b4-aefa-428c-a1bc-d221cd640c8e\", \"descriptionOther\": \"\", \"organisationType\": \"body-pl-cga\", \"previousEFormsId\": [], \"tedPublicationId\": null, \"tenderingInHilma\": false, \"previousSearchIds\": [], \"organisationNameEn\": \"\", \"organisationNameFi\": \"Porvoon kaupunki\", \"organisationNameSv\": \"\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Raatihuoneenkatu 9 06100 Porvoo FIN\", \"procurementTypeCode\": \"supplies\", \"winnerOrganisations\": \"Sitowise Oy (2335445-0)//Bentley Systems Finland Oy (0774171-7)\", \"innovationConsidered\": null, \"organisationNutsCode\": \"FI1B1\", \"previousFullEFormsId\": [], \"previousNoticeNumber\": [], \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationNameOther\": \"\", \"organisationDepartment\": \"\", \"listedGreenCriteriaUsed\": null, \"noticeResultTotalAmount\": null, \"oldProcurementProjectId\": 0, \"procurementDocumentsUrl\": null, \"previousContractFolderId\": [], \"previousTedPublicationId\": [], \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": null, \"includesFrameworkAgreement\": null, \"smeParticipationConsidered\": null, \"refOldNoticeTedPublicationId\": null, \"solutionNewToMarketOrIndustry\": null, \"isPrivateSmallValueProcurement\": false, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": null, \"isNationalSmallValueProcurement\": false, \"noticeResultTotalAmountCurrency\": null, \"organisationNationalRegistrationNumber\": \"1061512-1\", \"overallMaximumFrameworkContractsAmount\": null, \"overallMaximumFrameworkContractsCurrency\": null, \"overallApproximateFrameworkContractsAmount\": null, \"overallApproximateFrameworkContractsCurrency\": null}',65,NULL,'2026-09-06 10:59:36','2026-09-06 10:59:36');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (639,'2026-056302','HILMA','RFP','OPEN','Tietomallikoordinointi, rakennusten inventointimittaus sekä -mallinnus ja visualisointipalvelut','Vaasan kaupunki / Talotoimi -liikelaitos pyytää tarjouksia rakennushankkeiden tietomallikoordinointi, rakennushankkeen inventointimittaus- ja mallinnuspalvelu sekä rakennushankkeen visualisointipalvelusta. Puitesopimuksen piiriin kuuluvien toimeksiantojen kohteina ovat pääasiassa Talotoimi –liikelaitoksen hallinnoimien Vaasan kaupungin omistamien julkisiin rakennuksiin (mm, kasvatuksen ja koulutuksen, kulttuuri-, liikunta- ja nuorisotoimen rakennukset sekä toimisto- ja liikerakennukset) kohdistuvien peruskorjaus- ja uudisrakennushankkeiden tietomallikoordinointi, inventointimittaus- ja mallinnuspalvelu sekä visualisointipalvelu. Jokaiseen osa-alueeseen valitaan enintään kolme (3) sopimuskumppania etusijajärjestyksellä. Toimeksiantojen tehtäväkuvaus ja toiminta sopimuskaudella on kuvattu tarjouspyynnön Liitteissä 1-3. Sopimuskausi on kolme (3) vuotta. Sopimuskausi alkaa sopimuksen allekirjoituksesta ja päättyy kolmen vuoden päästä sopimuksen allekirjoituksesta. Tilaaja varaa oikeuden jatkaa sopimusta yhdellä (1) optiovuodella varsinaisen sopimuskauden päättämisestä lukien. Optiovuoden käytöstä ilmoitetaan viimeistään kolme kuukautta ennen varsinaisen sopimuskauden päättymistä., Rakennushankkeiden tietomallikoordinointi Rakennushankkeiden tietomallikoordinointi. Osa-aluetta koskevat työt tilataan tarjouskilpailun tuloksen perusteella määritellyssä etusijajärjestyksessä. Pääsääntöisesti toimeksiannot suoritetaan puitesopimuksen mukaisilla hinnoilla aikapalkkioon perustuvalla korvauksella. Palveluntuottaja laatii Tilaajalle työmääräarvion, jonka tilaaja hyväksyy tai hylkää. Tilaaja pidättää oikeuden kilpailuttaa toimeksiannot joko puitesopimuskumppanien välisellä minikilpailutuksella tai julkisena hankintana avointa menettelyä käyttäen. Tietomallikoordinaattori ei voi toimia samanaikaisesti suunnittelijana samassa hankkeessa., Rakennushankkeiden inventointimittaus- ja mallinnuspalvelut Rakennushankkeiden inventointimittaus- ja mallinnuspalvelut. Osa-aluetta koskevat työt tilataan tarjouskilpailun tuloksen perusteella määritellyssä etusijajärjestyksessä. Pääsääntöisesti toimeksiannot suoritetaan puitesopimuksen mukaisilla hinnoilla aikapalkkioon perustuvalla korvauksella. Palveluntuottaja laatii Tilaajalle työmääräarvion, jonka tilaaja hyväksyy tai hylkää. Tilaaja pidättää oikeuden kilpailuttaa toimeksiannot joko puitesopimuskumppanien välisellä minikilpailutuksella tai julkisena hankintana avointa menettelyä käyttäen. Inventointimallintaja ei voi samanaikaisesti toimia Suunnittelijana kyseisessä hankkeessa., Rakennushankkeiden visualisointipalvelut Rakennushankkeiden visualisointipalvelut. Osa-aluetta koskevat työt tilataan tarjouskilpailun tuloksen perusteella määritellyssä etusijajärjestyksessä. Pääsääntöisesti toimeksiannot suoritetaan puitesopimuksen mukaisilla hinnoilla aikapalkkioon perustuvalla korvauksella. Palveluntuottaja laatii Tilaajalle työmääräarvion, jonka tilaaja hyväksyy tai hylkää. Tilaaja pidättää oikeuden kilpailuttaa toimeksiannot joko puitesopimuskumppanien välisellä minikilpailutuksella tai julkisena hankintana avointa menettelyä käyttäen. Visualisoija ei voi toimia samanaikaisesti suunnittelijana samassa hankkeessa.,','Vaasan Talotoimi -liikelaitos','ANY',1,13,NULL,NULL,600000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056302','[\"71000000\"]','[\"rakennushankkeiden\", \"tilaaja\", \"toimeksiannot\", \"tietomallikoordinointi\", \"inventointimittaus\", \"vaasan\", \"talotoimi\", \"puitesopimuksen\", \"oikeuden\", \"visualisointipalvelut\", \"liikelaitos\", \"kolme\", \"aluetta\", \"koskevat\", \"työt\", \"tilataan\", \"tarjouskilpailun\", \"tuloksen\", \"perusteella\", \"määritellyssä\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/teese?id=621538&tpk=af1820b7-6d4c-4ad3-b075-c5cac866a028\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056302\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56302\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Rakennushankkeiden tietomallikoordinointi\", \"titleSv\": \"\", \"cpvCodes\": \"71000000\", \"currency\": \"EUR\", \"deadline\": \"2026-11-02T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Rakennushankkeiden tietomallikoordinointi.\\n\\nOsa-aluetta koskevat työt tilataan tarjouskilpailun tuloksen perusteella määritellyssä etusijajärjestyksessä. Pääsääntöisesti toimeksiannot suoritetaan puitesopimuksen mukaisilla hinnoilla aikapalkkioon perustuvalla korvauksella. Palveluntuottaja laatii Tilaajalle työmääräarvion, jonka tilaaja hyväksyy tai hylkää.\\n\\nTilaaja pidättää oikeuden kilpailuttaa toimeksiannot joko puitesopimuskumppanien välisellä minikilpailutuksella tai julkisena hankintana avointa menettelyä käyttäen.\\n\\nTietomallikoordinaattori ei voi toimia samanaikaisesti suunnittelijana samassa hankkeessa.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 200000.0, \"expirationDate\": \"2026-11-02T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": true, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": fals