INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (646,'2026-056293','HILMA','RFI','OPEN','Tietopyyntö, Lasten ja nuorten psykologipalvelut, Pohjois-Karjalan hyvinvointialue','Tietopyyntö, Lasten ja nuorten psykologipalvelut, Pohjois-Karjalan hyvinvointialue Sansia Oy valmistelee lasten ja nuorten psykologipalveluhankintaa Pohjois-Karjalan hyvinvointialueelle. Tämä ei ole hankintailmoitus eikä tarjouspyyntö, vaan tietopyyntö mahdollisille tarjoajille. Tietopyynnön tarkoituksena on kartoittaa markkinoita ja kerätä tietoa sekä toimittajien kommentteja, jotta mahdollinen tuleva tarjouskilpailu voitaisiin toteuttaa tarkoituksenmukaisella tavalla. Tietopyynnöllä ei pyydetä, eikä siihen anneta, tarjouksia. Hankintayksikölle esitettyihin kommentteihin ja lisäkysymyksiin ei vastata. Tietopyyntö ei velvoita hankintayksikköä suorittamaan varsinaista hankintaa tai toteuttamaan hankintaa tietopyynnössä kuvatulla tavalla. Hankintayksikkö ei ole velvollinen ottamaan huomioon tietopyyntöön saatuja vastauksia tarjouspyynnön laadinnassa. Tietopyyntöön vastanneille ei makseta korvausta tietopyyntöön vastaamisesta tai mahdolliseen markkinavuoropuhelutilaisuuteen osallistumisesta. Tietopyyntöön vastaaminen ei sido toimittajaa tarjouskilpailuun osallistumiseen, eikä myöskään ole edellytyksenä myöhemmin varsinaiseen tarjouskilpailuun osallistumiselle. Tietopyyntöön vastaaminen tai vastaamatta jättäminen ei vaikuta tarjoajan asemaan varsinaisessa tarjouskilpailussa.,','Sansia Oy','ANY',3,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056293','[\"85121270\"]','[\"tietopyyntöön\", \"tietopyyntö\", \"lasten\", \"