INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (648,'2026-056290','HILMA','RFP','OPEN','e-Forms 2023 / EU / HUS 486-2023 Apteekin toiminnanohjausjärjestelmä ohjelmistopalveluna','e-Forms 2023 / EU / HUS 486-2023 Apteekin toiminnanohjausjärjestelmä ohjelmistopalveluna HUS pyytää tarjoustanne ohjelmistopalvelusta, jolla hoidetaan HUS Apteekin toiminnanohjausta kattaen liitteissä kuvatut toiminnan osa-alueet. Hankittavaan ohjelmistopalveluun konfiguroidaan HUS Apteekin lääkkeiden hallinnointia koskevia prosesseja ja tietoja. Ohjelmistopalvelun tulee integroitua HUSin muussa toiminnanohjauksessaan käyttämiin järjestelmiin (esim. Oracle Fusion Cloud). Tarjouspyynnön liitteissä (liite 0 ja liitteet 1: Nykytoiminnan kuvaus) on kuvattu nykytoiminnan laajuutta sanallisin kuvauksin eri toiminta-alueittain. Kuvauksien tarkoitus on perehdyttää tarjoajaa HUS Apteekin nykytoimintaan. Liitteissä (liitteet 2: Tavoitetilan kuvaus) on kuvattu hankinnan kohteelle asetettuja vaatimuksia toiminta-aluekohtaisesti erilaisin prosessikuvauksin ja listatuilla vaatimuksilla. Tämän tarkoituksena on ilmaista tarjoajille toiminnanohjaukselle asetettavia vähimmäisvaatimuksia. Lisäksi on kuvattu tavoitteita nykytoiminnan kehittämiseksi. Tarkoituksenamme on korvata nykyjärjestelmä ohjelmistopalvelulla (SaaS), joka mahdollistaa prosessien kehittämisen ja turvaa laadullisesti vakaan toiminnan. HUS hakee SaaS-pohjaista ohjelmistopalvelua, jonka tulee pohjautua tuotantokäytössä jo olevaan ja valmiiseen ohjelmistoon ja tilaajalle siitä konfiguroitavaan ratkaisuun. Hanke on suunniteltu aikataulultaan sellaiseksi, että ohjelmistopalvelu otetaan käyttöön vuoden 2028 aikana. Hanke käynnistetään määrittelyvaiheella, jossa tarkennetaan tehdyt kuvaukset voittaneen tarjoajan tarjoamaa ohjelmistopalvelua vasten ja näin varmistetaan, että kyseinen ohjelmistopalvelu täyttää asetetut vaatimukset ja tarjoaa selkeän kehityspolun. Tässä määrittelyvaiheessa myös tarkennetaan käyttöönottoprojektin suunnitelma sellaiselle tasolle, että osapuolet voivat sitoutua projektin toteutukseen. Määrittelyvaihe on aikaperusteisesti laskutettava, maksimissaan 50 000 euroa ja kestoltaan enintään neljä kuukautta. Liitteessä Käyttöönottoprojektin kuvaus on tarkemmin selostettu mitä määrittelyvaiheessa tulee tuottaa. Määrittelyvaiheen jälkeen molemmilla osapuolilla on, niin halutessaan, mahdollisuus luopua hankkeesta. Määrittelyvaiheen jälkeen tilaaja ja tarjoaja neuvottelevat tarjouspyynnössä esitetyllä tavoin hankkeelle tavoitetyömäärän ja -hinnan. Muissa tarjouspyynnön liitteissä on kuvattu käyttöönottoprojektiin, jatkuviin palveluihin ja tietoturvaan liittyviä vaatimuksia. Ohjelmistopalvelun tulee olla tavanomaisella tavalla integroitavissa erilaisiin hallinnollisiin järjestelmiin. Ohjelmistopalvelun liittymiä on esitetty liitteessä \"Integraatiot\". Oracle FINA -liittymät on yksittäisenä kuvattu tarkemmin liitteessä 2.9.3. Liite \"Sopimusluonnos\" kattaa sekä käyttöönottovaiheen että jatkuvien palveluiden aikaisen toiminnan. Liitteessä \"Hintalomake\" on kuvattu tarjousten Vertailuhinnan laskenta ja menettelyt Tavoitehinnan muodostamiseksi.,','HUS-yhtymä','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056290','[\"72210000\", \"48451000\", \"48812000\", \"72212451\", \"72268000\"]','[\"kuvattu\", \"apteekin\", \"liitteissä\", \"tulee\", \"liitteessä\", \"toiminnan\", \"ohjelmistopalvelun\", \"nykytoiminnan\", \"kuvaus\", \"forms\", \"toiminnanohjausjärjestelmä\", \"ohjelmistopalveluna\", \"järjestelmiin\", \"oracle\", \"tarjouspyynnön\", \"liite\", \"liitteet\", \"toiminta\", \"vaatimuksia\", \"saas\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/huslogistiikka?id=587732&tpk=67899d3d-1171-4f6e-b5ec-94d6f15e9e74\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056290\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56290\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"e-Forms 2023 / EU / HUS 486-2023 Apteekin toiminnanohjausjärjestelmä ohjelmistopalveluna\", \"titleSv\": \"\", \"cpvCodes\": \"72210000 48451000 48812000 72212451 72268000\", \"currency\": null, \"deadline\": \"2026-09-21T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"HUS pyytää tarjoustanne ohjelmistopalvelusta, jolla hoidetaan HUS Apteekin toiminnanohjausta kattaen liitteissä kuvatut toiminnan osa-alueet.\\n \\nHankittavaan  ohjelmistopalveluun konfiguroidaan HUS Apteekin lääkkeiden hallinnointia koskevia prosesseja ja tietoja. Ohjelmistopalvelun tulee integroitua HUSin muussa toiminnanohjauksessaan käyttämiin järjestelmiin (esim. Oracle Fusion Cloud).\\n\\nTarjouspyynnön liitteissä (liite 0 ja liitteet 1: Nykytoiminnan kuvaus) on kuvattu nykytoiminnan laajuutta sanallisin kuvauksin eri toiminta-alueittain. Kuvauksien tarkoitus on perehdyttää tarjoajaa HUS Apteekin nykytoimintaan. Liitteissä (liitteet 2: Tavoitetilan kuvaus) on kuvattu hankinnan kohteelle asetettuja vaatimuksia toiminta-aluekohtaisesti erilaisin prosessikuvauksin ja listatuilla vaatimuksilla. Tämän tarkoituksena on ilmaista tarjoajille toiminnanohjaukselle asetettavia vähimmäisvaatimuksia. Lisäksi on kuvattu tavoitteita nykytoiminnan kehittämiseksi.\\n\\nTarkoituksenamme on korvata nykyjärjestelmä ohjelmistopalvelulla (SaaS), joka mahdollistaa prosessien kehittämisen ja turvaa laadullisesti vakaan toiminnan. HUS hakee SaaS-pohjaista ohjelmistopalvelua, jonka tulee pohjautua tuotantokäytössä jo olevaan ja valmiiseen ohjelmistoon ja tilaajalle siitä konfiguroitavaan ratkaisuun.\\n\\nHanke on suunniteltu aikataulultaan sellaiseksi, että ohjelmistopalvelu otetaan käyttöön vuoden 2028 aikana. Hanke käynnistetään määrittelyvaiheella, jossa tarkennetaan tehdyt kuvaukset voittaneen tarjoajan tarjoamaa ohjelmistopalvelua vasten ja näin varmistetaan, että kyseinen ohjelmistopalvelu täyttää asetetut vaatimukset ja tarjoaa selkeän kehityspolun. Tässä määrittelyvaiheessa myös tarkennetaan käyttöönottoprojektin suunnitelma sellaiselle tasolle, että osapuolet voivat sitoutua projektin toteutukseen. \\n\\nMäärittelyvaihe on aikaperusteisesti laskutettava, maksimissaan 50 000 euroa ja kestoltaan enintään neljä kuukautta. Liitteessä Käyttöönottoprojektin kuvaus on tarkemmin selostettu mitä määrittelyvaiheessa tulee tuottaa.\\n\\nMäärittelyvaiheen jälkeen molemmilla osapuolilla on, niin halutessaan, mahdollisuus luopua hankkeesta. Määrittelyvaiheen jälkeen tilaaja ja tarjoaja neuvottelevat tarjouspyynnössä esitetyllä tavoin hankkeelle tavoitetyömäärän ja -hinnan.\\n\\nMuissa tarjouspyynnön liitteissä on kuvattu käyttöönottoprojektiin, jatkuviin palveluihin ja tietoturvaan liittyviä vaatimuksia. \\n\\nOhjelmistopalvelun  tulee olla  tavanomaisella  tavalla  integroitavissa  erilaisiin  hallinnollisiin järjestelmiin. Ohjelmistopalvelun liittymiä on esitetty liitteessä \\\"Integraatiot\\\". Oracle FINA -liittymät on yksittäisenä kuvattu tarkemmin liitteessä 2.9.3.\\n\\nLiite \\\"Sopimusluonnos\\\" kattaa sekä käyttöönottovaiheen että jatkuvien palveluiden aikaisen toiminnan.\\n\\nLiitteessä \\\"Hintalomake\\\" on kuvattu tarjousten Vertailuhinnan laskenta ja menettelyt Tavoitehinnan muodostamiseksi.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-09-21T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": true, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"16\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"e-Forms 2023 / EU / HUS 486-2023 Apteekin toiminnanohjausjärjestelmä ohjelmistopalveluna\", \"titleSv\": \"\", \"cpvCodes\": \"72210000 48451000 48812000 72212451 72268000\", \"currency\": null, \"deadline\": \"2026-09-21T09:00:00Z\", \"eFormsId\": \"a5d3138e-52b1-49a4-b08e-f8d31e0b1a5b\", \"isEForms\": true, \"mainType\": \"ContractNotices\", \"noticeId\": 56290, \"lowCarbon\": false, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"isCancelled\": false, \"procedureId\": 35085, \"biodiversity\": false, \"dateModified\": \"2026-09-06T07:05:04.345Z\", \"fullEFormsId\": \"a5d3138e-52b1-49a4-b08e-f8d31e0b1a5b-01\", \"noticeNumber\": \"2026-056290\", \"@search.score\": 1.0, \"codeOfConduct\": false, \"datePublished\": \"2026-09-06T07:05:04.289Z\", \"descriptionEn\": \"\", \"descriptionFi\": \"e-Forms 2023 / EU / HUS 486-2023 Apteekin toiminnanohjausjärjestelmä ohjelmistopalveluna HUS pyytää tarjoustan