INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (651,'2026-056285','HILMA','RFP','OPEN','Oppisopimuskoulutuksena järjestettävän Lähiesihenkilötyön ammattitutkinnon tutkintokoulutus ja tutkinnon järjestäminen','Oppisopimuskoulutuksena järjestettävän Lähiesihenkilötyön ammattitutkinnon tutkintokoulutus ja tutkinnon järjestäminen Varian työelämäpalvelut hankkii oppisopimuskoulutuksena toteutettavan Lähiesihenkilötyön ammattitutkintokoulutuksen ja näyttöjen järjestämisen. Hankittavana voi olla tutkinto tai osatutkinto työnantajan ja opiskelijan tarpeen mukaan. Tutkinnon osittain tapahtuvassa hankinnassa käytetään tutkinnon osaa koskevaa hinnoittelua. Lähiesihenkilötyön ammattitutkinto järjestetään yhteistyössä tilaajan, oppisopimustyönantajien, opiskelijoiden ja palvelun tuottajan kanssa. Koulutus tapahtuu pääasiallisesti oppisopimusopiskelijoiden työpaikoilla ja perustuu työnantajan ja työntekijän ja koulutuksen järjestäjän tai yrittäjän ja koulutuksen järjestäjän väliseen sopimukseen. Koulutuspäivien enimmäismäärä sisältäen lähi-, etä-, verkko- ja hybridiopetuksen on 12 päivää. Yhden henkilön koko tutkinnon koulutuksen keston arvioidaan olevan keskimäärin noin 12 kuukautta. Koulutuspäivien lukumäärä ja opintojen kesto määräytyy henkilökohtaisen osaamisen kehittämissuunnitelman mukaisesti. Koulutuspaikka sovitaan tilaajan ja palveluntuottajan kesken. Opiskelijamäärä 2 vuoden puitesopimusaikana on arviolta noin 160 henkilöä. Hankinnasta laaditaan 2 vuoden puitesopimus palvelun tuottajien kanssa ja varataan mahdollisuus myös optiovuosien käyttöön (1 + 1 vuotta).,','Vantaan kaupunki','ANY',6,14,NULL,NULL,480000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056285','[\"80511000\"]','[\"tutkinnon\", \"lähiesihenkilötyön\", \"oppisopimuskoulutuksena\", \"koulutuksen\", \"järjestettävän\", \"ammattitutkinnon\", \"tutkintokoulutus\", \"järjestäminen\", \"työnantajan\", \"tilaajan\", \"palvelun\", \"kanssa\", \"järjestäjän\", \"koulutuspäivien\", \"noin\", \"vuoden\", \"vantaan\", \"kaupunki\", \"varian\", \"työelämäpalvelut\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/vantaa?id=613517&tpk=7608e8a6-f36c-4528-815e-a3392a38f68a\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056285\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56285\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Oppisopimuskoulutuksena järjestettävän Lähiesihenkilötyön ammattitutkinnon tutkintokoulutus ja tutkinnon järjestäminen\", \"titleSv\": \"\", \"cpvCodes\": \"80511000\", \"currency\": \"EUR\", \"deadline\": \"2026-10-07T06:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Varian työelämäpalvelut hankkii oppisopimuskoulutuksena toteutettavan Lähiesihenkilötyön ammattitutkintokoulutuksen ja näyttöjen järjestämisen. Hankittavana voi olla tutkinto tai osatutkinto työnantajan ja opiskelijan tarpeen mukaan. Tutkinnon osittain tapahtuvassa hankinnassa käytetään tutkinnon osaa koskevaa hinnoittelua. Lähiesihenkilötyön ammattitutkinto järjestetään yhteistyössä tilaajan, oppisopimustyönantajien, opiskelijoiden ja palvelun tuottajan kanssa. Koulutus tapahtuu pääasiallisesti oppisopimusopiskelijoiden työpaikoilla ja perustuu työnantajan ja työntekijän ja koulutuksen järjestäjän tai yrittäjän ja koulutuksen järjestäjän väliseen sopimukseen.\\n\\nKoulutuspäivien enimmäismäärä sisältäen lähi-, etä-, verkko- ja hybridiopetuksen on 12 päivää. Yhden henkilön koko tutkinnon koulutuksen keston arvioidaan olevan keskimäärin noin 12 kuukautta. Koulutuspäivien lukumäärä ja opintojen kesto määräytyy henkilökohtaisen osaamisen kehittämissuunnitelman mukaisesti. Koulutuspaikka sovitaan tilaajan ja palveluntuottajan kesken. Opiskelijamäärä 2 vuoden puitesopimusaikana on arviolta noin 160 henkilöä. Hankinnasta laaditaan 2 vuoden puitesopimus palvelun tuottajien kanssa ja varataan mahdollisuus myös optiovuosien käyttöön (1 + 1 vuotta).\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 480000.0, \"expirationDate\": \"2026-10-07T06:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": true, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"20\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Oppisopimuskoulutuksena järjestettävän Lähiesihenkilötyön ammattitutkinnon tutkintokoulutus ja tutkinnon järjestäminen\", \"titleSv\": \"\", \"cpvCodes\": \"8051100