vuotta).,\", \"descriptionSv\": \"\", \"isCorrigendum\": false, \"linkedNotices\": \"\", \"procedureType\": \"open\", \"sendingSystem\": \"Cloudia Kilpailutus\", \"estimatedValue\": 480000.0, \"expirationDate\": \"2026-10-07T06:00:00Z\", \"parentNoticeId\": null, \"circularEconomy\": false, \"endUserInvolved\": true, \"isEuProcurement\": true, \"noticeOjsNumber\": \"\", \"contractFolderId\": \"ebad7c68-03c7-428c-a038-0fb76306bea9\", \"descriptionOther\": \"\", \"organisationType\": \"la\", \"previousEFormsId\": [], \"tedPublicationId\": null, \"tenderingInHilma\": false, \"previousSearchIds\": [], \"organisationNameEn\": \"\", \"organisationNameFi\": \"Vantaan kaupunki\", \"organisationNameSv\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"organisationAddress\": \"PL 1100 01030 Vantaan kaupunki FIN\", \"procurementTypeCode\": \"services\", \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"organisationNutsCode\": \"FI1B1\", \"previousFullEFormsId\": [], \"previousNoticeNumber\": [], \"isNationalProcurement\": false, \"justWorkingConditions\": false, \"organisationNameOther\": \"\", \"organisationDepartment\": \"\", \"listedGreenCriteriaUsed\": null, \"noticeResultTotalAmount\": null, \"oldProcurementProjectId\": 0, \"procurementDocumentsUrl\": \"https://tarjouspalvelu.fi/vantaa?id=613517&tpk=7608e8a6-f36c-4528-815e-a3392a38f68a\", \"previousContractFolderId\": [], \"previousTedPublicationId\": [], \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": true, \"refOldNoticeTedPublicationId\": null, \"solutionNewToMarketOrIndustry\": false, \"isPrivateSmallValueProcurement\": false, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"isNationalSmallValueProcurement\": false, \"noticeResultTotalAmountCurrency\": null, \"organisationNationalRegistrationNumber\": \"0124610-9\", \"overallMaximumFrameworkCo