INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (652,'2026-056282','HILMA','RFI','OPEN','Kantametron kuilujen saneeraus Paketit 4, 6 ja 7','Kantametron kuilujen saneeraus Paketit 4, 6 ja 7 Pääkaupunkiseudun Kaupunkiliikenne Oy (\"KLOY\" tai \"Tilaajan edustaja\") tulee järjestämään Helsingin kaupungin liikenneliikelaitoksen (\"HKL\" tai \"Tilaaja\") toimeksiannosta tarjouskilpailut seitsemästä erillisestä kantametron kuilujen teknisestä peruskorjauksesta, joista jokainen julkaistaan erillisenä tarjouskilpailuna. Tällä ennakkoilmoituksella hankintayksikkö mahdollistaa alla olevien tarjouskilpailutuspakettien määräaikojen lyhentämisen. Toimijoita pyydetään huomioimaan, että tämä ilmoitus ei ole hankintailmoitus, vaan erityisalojen hankintalain (laki vesi- ja energiahuollon, liikenteen ja postipalvelujen alalla toimivien yksiköiden hankinnoista ja käyttöoikeussopimuksesta 1398/2016) 65 §:n mukainen ennakkoilmoitus osana tulevan hankinnan valmistelua. Seuraavat kilpailutettavat hankintapaketit ovat: - Kantametron kuilut Paketti 4, kilpailutustunnus 49H25 - Kantametron kuilut Paketti 6, kilpailutustunnus 50H25 - Kantametron kuilut Paketti 7, kilpailutustunnus 51H25. Paketti 4 sisältää seuraavat kuilut: - Antinkadun kuilu (KP2) - Kaisaniemen eteläinen kuilu (HY1) - Laiturin varauloskäyntiportaikko (HY2) - Kaisaniemen pohjoinen kuilu (HY3) Paketti 6 sisältää seuraavat kuilut: - Vaihdealueen varauloskäyntiporras, raide 1 (MM1) - Vaihdealueen varauloskäyntiporras, raide 2 (MM2) - Palokunnan hyökkäystieporras radalle (MM3) - Mellunmäen kääntöraidekuilu (MM4) Paketti 7 sisältää seuraavat kuilut: - Puotilan läntinen kuilu (PT1) - Puotilan itäinen kuilu (PT2) - Leikkimäen kuilu (PT3) - Kääntöpaikan kuilu (PT4) Alustava aikataulu: - Tarjouspyynnön julkaisu: paketti 4 loka-marraskuu 2026, paketit 6 ja 7 tammi-helmikuu 2027 - Töiden aloitus: asiasta ilmoitetaan tarkemmin tulevissa tarjouspyynnöissä - Töiden valmistuminen: asiasta ilmoitetaan tarkemmin tulevissa tarjouspyynnöissä Rakennuttaja edellyttää, että urakoitsija on tutustunut rakennuspaikkaan ja sen olosuhteisiin ennen tarjouksen antamista. Kohteisiin tutustumisen ajankohta ilmoitetaan ko. kuilupakettia koskevassa tarjouspyynnössä. Tutustumiskäynnille tulee ilmoittautua ennakkoon tarjouspyynnössä olevien ohjeiden mukaisesti. Tarjoajien tulee huomioida, että tutustumiskäynnin yhteydessä ei voi esittää kysymyksiä, vaan kaikki kysymykset tulee esittää kirjallisesti tarjouspalvelu.fi -portaalin kautta. Kuiluissa tehdään RAK, LVISA korjaus sekä muutostöitä. Tämän ennakkoilmoituksen liitteenä on pakettien 4, 6 ja 7 urakkaohjelmat.,','Helsingin kaupungin liikenneliikelaitos','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056282','[\"45000000\"]','[\"paketti\", \"kuilu\", \"kantametron\", \"kuilut\", \"tulee\", \"seuraavat\", \"kuilujen\", \"paketit\", \"kilpailutustunnus\", \"sisältää\", \"ilmoitetaan\", \"saneeraus\", \"helsingin\", \"kaupungin\", \"olevien\", \"vaan\", \"kaisaniemen\", \"vaihdealueen\", \"varauloskäyntiporras\", \"raide\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/hkl?id=624299&tpk=ce5d0c1b-f16b-4171-898a-dc234b78dfba\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056282\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56282\", \"lots\": [{\"id\": \"PAR-0000\", \"titleEn\": \"\", \"titleFi\": \"Kantametron kuilujen saneeraus Paketit 4, 6 ja 7\", \"titleSv\": \"\", \"cpvCodes\": \"45000000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": null, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": null, 