INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (659,'2026-056274','HILMA','RFP','OPEN','Kaupungin lehti-ilmoitusten julkaisemisen hankinta','Kaupungin lehti-ilmoitusten julkaisemisen hankinta Salon kaupunki (jäljempänä hankintayksikkö / tilaaja) pyytää tarjouksia kaupungin ilmoitusten julkaisemisesta sanomalehdissä tämän tarjouspyynnön ja sen liitteiden mukaisesti. Hankinnan sopimuskausi on ajalle 1.1.2027-31.12.2028. Lisäksi tilaaja varaa mahdollisuuden kahteen yhden vuoden pituiseen optiovuoteen vuosille 2029 ja 2030. Optiolla tarkoitetaan hankinnan jatkamista alkuperäisin ehdoin. Tilaaja päättää optioiden käytöstä ja kestosta erikseen. Hankinnan kohteena on kaupungin kaikkien palvelualueiden erilaisten ilmoitusten, kuulutuksien sekä markkinointiaineiston julkaiseminen sanomalehdissä. Viralliset ilmoitukset, kuulutukset ja muut ilmoitukset sisältävät esimerkiksi maankäyttö- ja rakennuslaissa, ympäristönsuojelulaissa ja -asetuksessa, vaalilaissa ja jätelaissa mainitut ilmoitettavat asiat. Kaupungin virallisten ilmoitusten lisäksi julkaistaan myös muita kaupungin ilmoituksia, kuten esimerkiksi tapahtumiin ja vapaa-aikaan liittyviä ilmoituksia sekä mainoksia. Salon kaupungin ilmoitukset julkaistaan kuntalain 108 §:ssä säädetyllä tavalla yleisessä tietoverkossa ja erityislainsäädännön niin edellyttäessä kaupungin virallisella ilmoitustaululla. Kuntalaisten tasapuolisen tiedonsaannin varmistamiseksi julkaistaan kunnallisia ilmoituksia julkisen tietoverkon lisäksi kaupungin harkinnan mukaan myös alueella ilmestyvissä lehdissä. Salon kaupunki pidättää oikeuden käyttää ilmoitustensa julkaisemiseen muitakin lehtiä, mikäli se on ilmoitettavan asian kannalta tarkoituksenmukaista. Esimerkiksi viran- ja toimenhakuilmoitukset voidaan julkaista harkinnan mukaan myös muissa lehdissä.,','Salon kaupunki','ANY',5,1,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056274','[\"79000000\"]','[\"kaupungin\", \"ilmoitusten\", \"salon\", \"kaupunki\", \"tilaaja\", \"hankinnan\", \"lisäksi\", \"ilmoitukset\", \"esimerkiksi\", \"julkaistaan\", \"ilmoituksia\", \"lehti\", \"julkaisemisen\", \"hankinta\", \"sanomalehdissä\", \"harkinnan\", \"mukaan\", \"lehdissä\", \"jäljempänä\", \"hankintayksikkö\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/salo?id=622263&tpk=f16a6ea3-e878-41a4-b2af-75ac60137c4a\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056274\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56274\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Kaupungin lehti-ilmoitusten julkaisemisen hankinta\", \"titleSv\": \"\", \"cpvCodes\": \"79000000\", \"currency\": null, \"deadline\": \"2026-10-07T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1C1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Salon kaupunki (jäljempänä hankintayksikkö / tilaaja) pyytää tarjouksia kaupungin ilmoitusten julkaisemisesta sanomalehdissä tämän tarjouspyynnön ja sen liitteiden mukaisesti. Hankinnan sopimuskausi on ajalle 1.1.2027-31.12.2028. Lisäksi tilaaja varaa mahdollisuuden kahteen yhden vuoden pituiseen optiovuoteen vuosille 2029 ja 2030. Optiolla tarkoitetaan hankinnan jatkamista alkuperäisin ehdoin. Tilaaja päättää optioiden käytöstä ja kestosta erikseen.\\n\\nHankinnan kohteena on kaupungin kaikkien palvelualueiden erilaisten ilmoitusten, kuulutuksien sekä markkinointiaineiston julkaiseminen sanomalehdissä. Viralliset ilmoitukset, kuulutukset ja muut ilmoitukset sisältävät esimerkiksi maankäyttö- ja rakennuslaissa, ympäristöns