INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (664,'2026-056264','HILMA','RFP','OPEN','HUSK Kameravalvontajärjestelmien asennus-, huolto- ja korjaustöiden hankinta','HUSK Kameravalvontajärjestelmien asennus-, huolto- ja korjaustöiden hankinta HUS Kiinteistöt Oy kilpailuttaa HUS-yhtymän toiminta-alueella sijaitsevissa sairaaloissa ja muissa toimipisteissä tarvittavat kameravalvontajärjestelmien asennus-, huolto- ja korjaustyöt. Tällaisia toimipisteitä sijaitsee etenkin Helsingin, Espoon, Vantaan, Hyvinkään, Lohjan, Porvoon ja Raaseporin kaupunkien alueella, mutta toimintaa on myös muilla paikkakunnilla pienemmässä mittakaavassa. Kameravalvontajärjestelmien asennus-, huolto- ja korjaustyöt on kuvattu tarkemmin tarjouspyynnön liitteessä 2. palvelukuvaus sekä liitteissä 3-6. Koko HUS-alueelle valitaan kolme (3) toimittajaa ellei hyväksyttyjä tarjouksia saada vähemmän. Sopimuskauden kesto on kaksi (2) vuotta. Sopimukseen sisältyy mahdollisuus yhteen (1) kahden (2) vuoden optioon. Puitejärjestelyyn valituille urakoitsijoille järjestetään kansallisen kynnysarvon ylittävissä hankinnoista/urakoista aina minikilpailutus (projektikohtainen sopimus), jonka perusteella projektikohtainen urakoitsija valitaan. Minikilpailutuksessa annettavat hinnat eivät saa ylittää sopimuksessa sovittuja hintoja. Urakoitsija voi kuitenkin tarjota alempia hintoja. Kansallisen kynnysarvon alittavissa hankinnoissa (yksittäiset työtilaukset) tilaaja voi hankkia tarvittavan työkokonaisuuden tilanteen mukaan parhaaksi katsomaltaan ja tarkoituksenmukaisimmalta urakoitsijalta. Tällöin käytetään urakoitsijan tarjoamia hintoja. Hankintayksiköllä on myös oikeus minikilpailuttaa kynnysarvon alittavat hankinnat. Sopimuskaudella ostettavien palveluiden määrä sekä kohteet, joihin palveluita hankitaan, voivat vaihdella. Tilaaja ei sitoudu tiettyihin hankintamääriin. Sopimustoimittajilta on mahdollista hankkia myös muita hankinnan kohteeseen liittyviä tuotteita, vuokralaitteita ja koneita tai erityisosaamista. Muiden tuotteiden, vuokralaitteiden ja koneiden tai erityisosaamisen hinnoittelussa tulee noudattaa samaa periaatetta kuin tarjouksessa annetuissa hinnoissa. HUS-yhtymällä on sairaalakiinteistöjä vuokrasairaalat mukaan lukien yhteensä noin 1.300 000 brm2. Suuren kiinteistömassan takia kohteisiin ei järjestetä kiinteistökierroksia. Kohteisiin tutustutaan toimittajan kanssa tilauksen yhteydessä.,','HUS Kiinteistöt Oy','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056264','[\"50000000\", \"35120000\", \"35125300\", \"51000000\", \"51900000\"]','[\"kameravalvontajärjestelmien\", \"asennus\", \"huolto\", \"kynnysarvon\", \"hintoja\", \"husk\", \"korjaustöiden\", \"hankinta\", \"kiinteistöt\", \"alueella\", \"korjaustyöt\", \"valitaan\", \"kansallisen\", \"projektikohtainen\", \"urakoitsija\", \"tilaaja\", \"hankkia\", \"mukaan\", \"kohteisiin\", \"kilpailuttaa\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/huskiinteistot?id=613460&tpk=e5fd57f4-b25a-4998-8210-73da8b3a23b8\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056264\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56264\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"HUSK Kameravalvontajärjestelmien asennus-, huolto- ja korjaustöiden hankinta\", \"titleSv\": \"\", \"cpvCodes\": \"50000000 35120000 35125300 51000000 51900000\", \"currency\": null, \"deadline\": \"2026-09-25T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptio