INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (665,'2026-056370','HILMA','RFP','OPEN','Ikääntyneiden kotihoidon palvelujen hankinta','Ikääntyneiden kotihoidon palvelujen hankinta Kotihoidolla tarkoitetaan sosiaalihuoltolain (1301/2014) mukaisen kotipalvelun 19 §:ään ja terveydenhuoltolain (1326/2010) 25 §:ään sisätyvien kotisairaanhoidon tehtävien muodostamaa kokonaisuutta. Kotihoidon tavoitteena on tukea asiakkaiden kokonaisvaltaista hyvinvointia ja mahdollisimman itsenäistä selviytymistä kotona sekä ylläpitää ja parantaa heidän fyysistä, psyykkistä ja sosiaalista toimintakykyään. Kotihoito myönnetään asiakkaille palvelutarpeen ja -päätösten mukaisesti. Palveluntuottajalla tulee olla toimintaan Aluehallintoviraston ja Valviran lupa. Hankinnan kohteena oleva palvelu on kuvattu tarkemmin osallistumispyynnön liitteellä yksi (1) palvelukuvaus. Tilaajan hankinnalle asettamat yksityiskohtaiset tavoitteet ovat: 1. Asiakkaan valinnan vapauden edistäminen 2. Palvelun laadun kehittäminen asiakastarpeita vastaavaksi 3. Monituottajuusmallin tukeminen 4. Uusien yritysten joustavan markkinoille pääsyn mahdollistaminen 5. Kuntien taloudellista kantokykyä tukeva palvelumalli,','Päijät-Hämeen hyvinvointialue','SME',3,7,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056370','[\"85000000\"]','[\"kotihoidon\", \"ikääntyneiden\", \"palvelujen\", \"hankinta\", \"päijät\", \"hämeen\", \"hyvinvointialue\", \"kotihoidolla\", \"tarkoitetaan\", \"sosiaalihuoltolain\", \"mukaisen\", \"kotipalvelun\", \"terveydenhuoltolain\", \"sisätyvien\", \"kotisairaanhoidon\", \"tehtävien\", \"muodostamaa\", \"kokonaisuutta\",