INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (667,'2026-056364','HILMA','RFP','OPEN','Tekoälyavusteinen tulkkauspalvelu työllisyyspalvelujen vieraskielisille asiakkaille','Tekoälyavusteinen tulkkauspalvelu työllisyyspalvelujen vieraskielisille asiakkaille Helsingin kaupungin työllisyyspalveluliikelaitos tarjoaa työllisyyspalveluja mm. vieraskielisille asiakkaille, joilla ei ole suomen tai ruotsin kielen taitoa tai se on heikko. Tämän vuoksi tarvitaan tehokkaita tulkkausratkaisuja, jotka tukevat asiakkaan ja asiakasta ohjaavan työntekijän kommunikaatiota varmistaen, että vieraskieliset asiakkaat saavat täyden hyödyn työllisyyspalveluista. Kaupungilla on käytössä voimassa olevat tulkkauspalvelusopimukset tulkin avustuksella tapahtuvaan lähi- ja etätulkkaukseen. Täten Helsingin kaupungin työllisyyspalveluliikelaitos hankkii tekoälyavusteisen tulkkauspalvelun. Tulkkauspalvelun on pystyttävä tarjoamaan tulkkausta useilla kielillä. Palvelun tulee hyödyntää tekoälyä reaaliaikaisen tulkkauksen tarjoamiseen. Tulkkauspalvelun on oltava luottamuksellinen ja yksityisyyttä suojaava (Helsingin kaupungin tietosuojavaatimukset on täytettävä ja ne toimitetaan myöhemmin erikseen). Palvelun tulee olla helppokäyttöinen niin asiakkaille kuin palvelun tarjoajille ja käyttöliittymän voi käyttää eri laitteilla (tietokone, älypuhelin, tabletti, tms.). Hankinnan kohde on kuvattu tarkemmin liitteissä 1 Hankinnan kohteen palvelukuvaus ja 2 Vaatimusluettelo.,','Helsingin työllisyyspalveluliikelaitos','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056364','[\"79540000\", \"72000000\"]','[\"asiakkaille\", 