INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (668,'2026-056363','HILMA','RFP','OPEN','Ikääntyneiden tehostetun palveluasumisen palveluiden hankinta','Ikääntyneiden tehostetun palveluasumisen palveluiden hankinta Tehostettu palveluasuminen ikäihmisille tarkoittaa sosiaalihuoltolain (1301/2014) 21 §:n mukaista asumispalvelua, joka järjestetään palvelutaloissa tai asumisyksiköissä, joissa henkilökunta on paikalla ympärivuorokauden. Palveluntuottajalla tulee olla toimintaan Aluehallintoviraston tai Valviran lupa. Hankinnan kohteena oleva palvelu on kuvattu tarkemmin osallistumispyynnön liitteellä yksi (1) palvelukuvaus. Tilaajan hankinnalle asettamat yksityiskohtaiset tavoitteet ovat: 1. Asiakkaan valinnan vapauden edistäminen 2. Palvelun laadun kehittäminen asiakastarpeita vastaavaksi 3. Monituottajuusmallin tukeminen 4. Uusien yritysten joustavan markkinoille pääsyn mahdollistaminen 5. Kuntien taloudellista kantokykyä tukeva palvelumalli,','Päijät-Hämeen hyvinvointialue','SME',3,7,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056363','[\"85000000\"]','[\"ikääntyneiden\", \"tehostetun\", \"palveluasumisen\", \"palveluiden\", \"hankinta\", \"päijät\", \"hämeen\", \"hyvinvointialue\", \"tehostettu\", \"palveluasuminen\", \"ikäihmisille\", \"tarkoittaa\", \"sosiaalihuoltolain\", \"mukaista\", \"asumispalvelua\", \"järjestetään\", \"palvelutaloissa\", \"asumisyksiköissä\", \"joissa\", \"henkilökunta\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/phhvaj?id=362108&tpk=e663d72c-d946-4917-8993-62488f820ae2\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukse