INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (674,'2026-056354','HILMA','OTHER','OPEN','Sähköaseman päämuuntaja 117 / 21 kV, 31,5MVA ONAN (40MVA ONAF)','Sähköaseman päämuuntaja 117 / 21 kV, 31,5MVA ONAN (40MVA ONAF) ESE-Energia Oy pyytää tarjoustanne 31,5MVA:n päämuuntajasta liitteinä olevien hankinta-asiakirjojen mukaisesti. Päämuuntaja sijoitetaan Mikkelin kaupunkialueella sijaitsevalla sähköasemalle muuntajaperustukselle. Sijoituspaikka varmistuu hankinnan edetessä. Sähköasemalle on hyvät kulku-yhteydet, eikä sijainti vaikuttane merkittävästi toimituksen hintaa määriteltäessä. Lopullinen sijoituspaikka varmistuu myöhemmin. Hankintaan sisältyy 31,5MVA päämuuntajan suunnittelu, valmistus ja toimitus öljyineen ja varusteineen Tilaajan sähköaseman perustukselle haalattuna / nostettuna sekä muuntajan varustelu sekä käyttökuntoon saattaminen ja käyttöönottokokeet suoritettuna ja loppudokumentit ja käyttöohjeet toimitettuna. Hankinnan tarkempi sisältö on esitetty tarjouspyynnön liitteenä olevassa hankekuvauksessa ja muissa liitteissä.,','ESE-Energia Oy','ANY',5,14,NULL,NULL,1300000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056354','[\"31170000\"]','[\"sähköaseman\", \"päämuuntaja\", \"energia\", \"onan\", \"onaf\", \"sähköasemalle\", \"sijoituspaikka\", \"varmistuu\", \"hankinnan\", \"pyytää\", \"tarjoustanne\", \"päämuuntajasta\", \"liitteinä\", \"olevien\", \"hankinta\", \"asiakirjojen\", \"mukaisesti\", \"sijoitetaan\", \"mikkelin\", \"kaupunkialueella\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056354\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56354\", \