INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (679,'2026-056391','HILMA','RFP','OPEN','Henkilöstöhallintopalvelut ja näihin palveluihin liittyvät tietojärjestelmät kokonaispalveluna','Henkilöstöhallintopalvelut ja näihin palveluihin liittyvät tietojärjestelmät kokonaispalveluna Kotkan kaupungin (hankintayksikkö) henkilöstöasioiden yksikkö (tilaaja) pyytää tarjouksia palkkapalveluiden toimijasta, henkilöstöhallintopalveluista sekä niitä tukevista tietojärjestelmistä (palvelukokonaisuus) tarjouspyynnön ja sen liitteiden mukaisesti. Hankintasopimus tehdään toistaiseksi voimassa olevana yhden, kokonaistaloudellisesti edullisimman tarjoajan (hankinta-asiakirjoissa palveluntuottaja, toimittaja) kanssa. Sopimuskaudella palveluntuottaja tuottaa palvelukokonaisuutena tilaajan ulkoistamat palkanmaksupalvelun ja henkilöstöhallinnon palvelut tarjouspyynnön liitteiden mukaisesti. Palveluiden tuottamisessa noudatetaan kulloinkin voimassa olevaa lainsäädäntöä, palveluntuottajaa ja tilaajaa velvoittavia valtakunnallisia asetuksia, lausuntoja, ohjeita ja hyvää kirjanpitotapaa. Edellä mainittujen palveluiden lisäksi osana palvelukokonaisuutta palveluntuottaja toimittaa tilaajan käyttöön palvelutuotannon edellyttämät, täysin tuotantokäytössä olevat tietojärjestelmät SaaS-palveluna (järjestelmäkokonaisuus) tarjouspyynnön ja sen liitteiden mukaisesti. Mikäli tarjoaja käyttää näiden SaaS-palveluiden tuottamiseen alihankkijoina järjestelmätoimittajia, on nämä hankinta-asiakirjoissa ohjeistetun mukaisesti ilmoitettava tarjouksessa.,','Kotkan kaupunki','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056391','[\"79631000\", \"48450000\"]','[\"mukaisesti\", \"tietojärjestelmät\", \"kotkan\", \"tarjouspyynnön\", \"liitteiden\", \"palveluntuottaja\", \"palveluiden\", \"henkilöstöhallintopalvelut\", \"näihin\", \"palveluihin\", \"liittyvät\", \"kokonaispalveluna\", \"voimassa\", \"hankinta\", \"asiakirjoissa\", \"tilaajan\", \"saas\", \"kaupunki\", \"kaupungin\", \"hankintayksikkö\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/kotka?id=616963&tpk=11929b3c-ca28-4e2f-a843-c479ce6ebf11\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056391\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56391\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Henkilöstöhallintopalvelut ja näihin palveluihin liittyvät tietojärjestelmät kokonaispalveluna\", \"titleSv\": \"\", \"cpvCodes\": \"79631000 48450000\", \"currency\": null, \"deadline\": \"2026-10-02T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Kotkan kaupungin (hankintayksikkö) henkilöstöasioiden yksikkö (tilaaja) pyytää tarjouksia palkkapalveluiden toimijasta, henkilöstöhallintopalveluista sekä niitä tukevista tietojärjestelmistä (palvelukokonaisuus) tarjouspyynnön ja sen liitteiden mukaisesti.\\n\\nHankintasopimus tehdään toistaiseksi voimassa olevana yhden, kokonaistaloudellisesti edullisimman tarjoajan (hankinta-asiakirjoissa palveluntuottaja, toimittaja) kanssa.\\n\\nSopimuskaudella palveluntuottaja tuottaa palvelukokonaisuutena tilaajan ulkoistamat palkanmaksupalvelun ja henkilöstöhallinnon palvelut tarjouspyynnön liitteiden mukaisesti. Palveluiden tuottamisessa noudatetaan kulloinkin voimassa olevaa lainsäädäntöä, palveluntuottajaa ja tilaajaa velvoittavia valtakunnallisia asetuksia, lausuntoja, ohjeita ja hyvää kirjanpitotapaa.\\n\\nEdellä mainittujen palveluiden lisäksi osana palvelukokonaisuutta palveluntuottaja toimittaa tilaajan käyttöön palvelutuotannon edellyttämät, täysin tuotantokäytössä olevat tietojärjestelmät SaaS-palveluna (järjestelmäkokonaisuus) tarjouspyynnön ja sen liitteiden mukaisesti. Mikäli tarjoaja käyttää näiden SaaS-palveluiden tuottamiseen alihankkijoina järjestelmätoimittajia, on nämä hankinta-asiakirjoissa ohjeistetun mukaisesti ilmoitettava tarjouksessa.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-10-02T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"16\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Henkilöstöhallintopalvelut ja näihin palveluihin liittyvät tietojärjestelmät kokonaispalveluna\", \"titleSv\": \"\", \"cpvCodes\": \"79631000 48450000\", \"currency\": null, \"deadline\": \"2026-10-02T09:00:00Z\", \"eFormsId\": \"b2e5fec2-2d36-45d9-8b22-3f0c7e032296\", \"isEForms\": true, \"mainType\": \"ContractNotices\", \"noticeId\": 56391, \"lowCarbon\": false, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"isCancelled\": false, \"procedureId\": 35936, \"biodiversity\": false, \"dateModified\": \"2026-09-06T14:05:05.118Z\", \"fullEFormsId\": \"b2e5fec2-2d36-45d9-8b22-3f0c7e032296-01\", \"noticeNumber\": \"2026-056391\", \"@search.score\": 1.0, \"codeOfConduct\": false, \"datePublished\": \"2026-09-06T14:05:05.086Z\", \"descriptionEn\": \"\", \"descriptionFi\": \"Henkilöstöhallintopalvelut ja näihin palveluihin liittyvät tietojärjestelmät kokonaispalveluna Kotkan kaupungin (hankintayksikkö) henkilöstöasioiden yksikkö (tilaaja) pyytää tarjouksia palkkapalveluiden toimijasta, henkilöstöhallintopalveluista sekä niitä tukevista tietojärjestelmistä (palvelukokonaisuus) tarjouspyynnön ja sen liitteiden mukaisesti.\\n\\nHankintasopimus tehdään toistaiseksi voimassa olevana yhden, kokonaistaloudellisesti edullisimman tarjoajan (hankinta-asiakirjoissa palveluntuottaja, toimittaja) kanssa.\\n\\nSopimuskaudella palveluntuottaja tuottaa palvelukokonaisuutena tilaajan ulkoistamat palkanmaksupalvelun ja henkilöstöhallinnon palvelut tarjouspyynnön liitteiden mukaisesti. Palveluiden tuottamisessa noudatetaan kulloinkin voimassa olevaa lainsäädäntöä, palveluntuottajaa ja tilaajaa velvoittavia valtakunnallisia asetuksia, lausuntoja, ohjeita ja hyvää kirjanpitotapaa.\\n\\nEdellä mainittujen palveluiden lisäksi osana palvelukokonaisuutta palveluntuottaja toimittaa tilaajan käyttöön palvelutuotannon edellyttämät, täysin tuotantokäytössä olevat tietojärjestelmät SaaS-palveluna (järjestelmäkokonaisuus) tarjouspyynnön ja sen liitteiden mukaisesti. Mikäli tarjoaja käyttää näiden SaaS-palveluiden tuottamiseen alihankkijoina järjestelmätoimittajia, on nämä hankinta-asiakirjoissa ohjeistetun mukaisesti ilmoitettava tarjouksessa.,\", \"descriptionSv\": \"\", \"isCorrigendum\": true, \"linkedNo