INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (687,'2026-056376','HILMA','RFI','OPEN','Palveluseteli- ja ostopalvelujärjestelmä, markkinavuoropuhelu','Palveluseteli- ja ostopalvelujärjestelmä, markkinavuoropuhelu Tällä ilmoituksella Istekki ilmoittaa palveluseteli- ja ostopalvelujärjestelmän markkinavuoropuheluiden järjestämisestä. Vuoropuhelun tarkoituksena on varmistaa, että kilpailutuksen valmistelijoilla on käytössään mahdollisimman kattava ja ajantasainen kuva markkinoista ja tarjolla olevista ratkaisuista. Hankinnan kohteena on palveluseteli- ja ostopalvelujärjestelmäkokonaisuus ja sen liittymät muihin järjestelmiin, toimitusprojekti (sisältäen mm. migraatiot, konversiot), valmisohjelmistojen ylläpito ja tuki, tukipalvelu, erikseen tilattavat asiantuntijapalvelut sekä asiakaspalvelu. Hankittavaan järjestelmään voidaan tehdä jatkokehitystä sopimuskauden aikana. Palveluseteli- ja ostopalvelujärjestelmää käytetään palveluseteleiden ja maksusitoumusten myöntämiseen ja palvelujen ostamiseen yksityisiltä palveluntuottajilta tai muilta julkisilta toimijoilta. Järjestelmän kautta on tarpeen saada keskitettyä palvelusetelien ja ostopalvelutilausten (maksusitoumus) luominen, käyttäminen ja annetuista palveluista tilitysten tekeminen yksityisille palveluntuottajille tai muille julkisille toimijoille. Palveluseteli- ja ostopalvelujärjestelmässä tulee huomioida tarpeet sekä palvelun järjestäjän, - tuottajan että palvelua käyttävän asiakkaan näkökulmista. Palvelun järjestäjällä tulee olla järjestelmän kautta mahdollisuus palveluntuottajasopimusten hallintaan, palveluntarjonnan suunnitteluun, palvelusetelien ja maksusitoumuksien myöntämiseen, maksujen tiliöintiin, korjauspyyntöihin ja erilaisten raporttinäkymien seuraamiseen. Palveluntuottajalla tulee olla mahdollisuus hakeutua palveluntuottajaksi järjestelmän kautta. Lisäksi palveluntuottajan tulee pystyä kirjaamaan järjestelmään asiakkaan saama palvelu ja sitä kautta tilitys hyväksyttyjen tapahtumakirjausten perusteella. Asiakkaan tulee saada myönnetty palveluseteli / maksusitoumus käyttöönsä järjestelmän kautta. Palveluseteliasiakkaalla tulee olla mahdollisuus verrata tai tarkastella palveluntuottajia, seurata järjestelmästä palvelun toteutumista ja antaa palautetta palvelusta. Hankintayksikkö järjestää markkinavuoropuhelut joko etätapaamisina tai kirjallisesti tai molempia keinoja hyödyntäen. Markkinavuoropuhelut järjestetään suomen kielellä. Istekki ilmoittaa vuoropuheluun osallistuville yrityksille tarkemmat aikataulut sekä ohjeet myöhemmin. Huomioithan, että tässä ilmoituksessa esitetyt tiedot, kuvaukset ja arviot kilpailutuksen julkaisuajankohdasta ovat vasta alustavia ja suuntaa antavia. Lopulliset aikataulut tarkentuvat valmistelun edetessä. Mikäli olette kiinnostuneita osallistumaan markkinavuoropuheluun, pyydämme ilmoittamaan kiinnostuksenne viimeistään 11.09.2026 klo 14.00 osoitteeseen hankinnat@istekki.fi. Halutessanne voitte liittää mukaan myös suomenkielisiä esitteitä tai muuta materiaalia omasta palvelustanne. On hyvä huomioida, että tämä ilmoitus ei velvoita Istekki Oy:tä toteuttamaan hankintaa tässä asiakirjassa tai sen liitteissä esitetyllä tavalla. Mahdollinen tarjouskilpailu voidaan myös jättää järjestämättä. Vuoropuheluun vastaamisesta tai mahdollisiin esittelytilaisuuksiin osallistumisesta ei makseta erillistä korvausta. Haluamme vielä mainita, että kyseessä ei ole hankintailmoitus tai tarjouspyyntö. Tarkoituksena on tutustua markkinatilanteeseen ja kerätä hankinnan kohteeseen liittyvää tietoa tulevan kilpailutuksen suunnittelun tueksi. Tietopyyntöön vastaaminen on vapaaehtoista, eikä se ole edellytys mahdolliseen tarjouskilpailuun osallistumiselle tai sido Istekkiä julkaisemaan tarjouskilpailua. Samalla kuitenkin arvostamme suuresti toimittajien osallistumista, sillä se auttaa meitä rakentamaan tulevasta kilpailutuksesta mahdollisimman toimivan ja selkeän kokonaisuuden.,','Istekki Oy','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056376','[\"48000000\", \"72000000\"]','[\"palveluseteli\", \"istekki\", \"tulee\", \"kautta\", \"järjestelmän\", \"kilpailutuksen\", \"palvelun\", \"asiakkaan\", \"mahdollisuus\", \"ostopalvelujärjestelmä\", \"markkinavuoropuhelu\", \"ilmoittaa\", \"tarkoituksena\", \"mahdollisimman\", \"hankinnan\", \"järjestelmään\", \"voidaan\", \"myöntämiseen\", \"saada\", \"palvelusetelien\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/istekki?id=626520&tpk=6d2d21c4-4090-437a-8ef3-00d4d4cc1123\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056376\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56376\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Palveluseteli- ja ostopalvelujärjestelmä, markkinavuoropuhelu\", \"titleSv\": \"\", \"cpvCodes\": \"48000000 72000000\", \"currency\": null, \"deadline\": \"2026-09-11T11:00:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Tällä ilmoituksella Istekki ilmoittaa palveluseteli- ja ostopalvelujärjestelmän markkinavuoropuheluiden järjestämisestä. \\n\\nVuoropuhelun tarkoituksena on varmistaa, että kilpailutuksen valmistelijoilla on käytössään mahdollisimman kattava ja ajantasainen kuva markkinoista ja tarjolla olevista ratkaisuista. \\n\\nHankinnan kohteena on palveluseteli- ja ostopalvelujärjestelmäkokonaisuus ja sen liittymät muihin järjestelmiin, toimitusprojekti (sisältäen mm. migraatiot, konversiot), valmisohjelmistojen ylläpito ja tuki, tukipalvelu, erikseen tilattavat asia