INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (690,'2026-056373','HILMA','OTHER','OPEN','Kilpisen koulun peruskorjauksen sähkösuunnittelu','Kilpisen koulun peruskorjauksen sähkösuunnittelu Hankinnan kohteena on koulurakennuksen peruskorjauksen toteutussuunnittelu. Hankkeen tavoitteena on laatia yhteensovitetut ja toteutuskelpoiset suunnitelmat olemassa olevan rakennuksen peruskorjaamiseksi siten, että rakennuksen tekninen, toiminnallinen ja terveydellinen taso saatetaan nykyvaatimuksia vastaavaksi ja tilat palvelevat opetustoiminnan käyttöä. Toteutussuunnittelu käsittää arkkitehti‑, rakenne‑ sekä taloteknisen suunnittelun (LVI ja sähkö) sekä näiden suunnittelualojen yhteensovituksen. Peruskorjaus on tarkoitus toteuttaa osittain siten, että koulutoiminta jatkuu koululla osittain. Kohteessa on tehty laserkeilaus, joka toimii toteutussuunnittelun lähtötietona. Kyseessä on olemassa olevan koulurakennuksen peruskorjaus, minkä vuoksi suunnittelussa korostuu olemassa olevien rakenteiden ja järjestelmien huomioiminen sekä suunnitteluratkaisujen yhteensovittaminen. Toteutussuunnittelu tehdään tietomallipohjaisesti kolmiulotteisena mallina, jota hyödynnetään suunnittelukokouksissa ja käyttäjäyhteistyössä. Suunnittelukokoukset ja käyttäjäpalaverit järjestetään pääsääntöisesti hankkeen kohteella tilaajan kutsusta.,','Jyväskylän kaupunki','ANY',6,15,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056373','[\"71000000\"]','[\"peruskorjauksen\", \"toteutussuunnittelu\", \"olemassa\", \"kilpisen\", \"koulun\", \"sähkösuunnittelu\", \"koulurakennuksen\", \"hankkeen\", \"olevan\", \"rakennuksen\", \"siten\", \"peruskorjaus\", \"osittain\", \"jyväskylän\", \"kaupunki\", \"hankinnan\", \"kohteena\", \"tavoitteena\", \"laatia\", \"yhteensovitetut\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056373\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56373\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Kilpisen koulun peruskorjauksen sähkösuunnittelu\", \"titleSv\": \"\", \"cpvCodes\": \"71000000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": true, \"nutsCodes\": \"FI198\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Hankinnan kohteena on koulurakennuksen peruskorjauksen toteutussuunnittelu. Hankkeen tavoitteena on laatia yhteensovitetut ja toteutuskelpoiset suunnitelmat olemassa olevan rakennuksen peruskorjaamiseksi siten, että rakennuksen tekninen, toiminnallinen ja terveydellinen taso saatetaan nykyvaatimuksia vastaavaksi ja tilat palvelevat opetustoiminnan käyttöä. Toteutussuunnittelu käsittää arkkitehti‑, rakenne‑ sekä taloteknisen suunnittelun (LVI ja sähkö) sekä näiden suunnittelualojen yhteensovituksen. Peruskorjaus on tarkoitus toteuttaa osittain siten, että koulutoiminta jatkuu koululla osittain.\\n\\nKohteessa on tehty laserkeilaus, joka toimii toteutussuunnittelun lähtötietona. Kyseessä on olemassa olevan koulurakennuksen peruskorjaus, minkä vuoksi suunnittelussa korostuu olemassa olevien rakenteiden ja järjestelmien huomioiminen sekä suunnitteluratkaisujen yhteensovittaminen. Toteutussuunnittelu tehdään tietomallipohjaisesti kolmiulotteisena mallina, jota hyödynnetään suunnittelukokouksissa ja käyttäjäyhteistyössä. Suunnittelukokoukset ja käyttäjäpalaverit järjestetään pääsääntöisesti hankkeen kohteella tilaajan kutsusta.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2027-03-06T13:05:05.008Z\", \"circularEconomy\": true, \"endUserInvolved\": null, \"descriptionOther\":