INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (698,'2026-056418','HILMA','RFI','OPEN','TIPA / Markkinavuoropuhelu: Puitejärjestely liikuntasalien nostolaitteiden tarkastus- ja korjauspalvelusta','TIPA / Markkinavuoropuhelu: Puitejärjestely liikuntasalien nostolaitteiden tarkastus- ja korjauspalvelusta Tämä ei ole hankintailmoitus eikä tarjouspyyntö vaan tietopyyntö ja kutsu markkinavuoropuheluun. Ilmoituksessa mainitut hankintamenettelyä, määräaikoja, valintaperustetta, osatarjousten ja vaihtoehtoisten tarjousten hyväksymistä sekä muut hankintaa koskevat tiedot ovat alustavia eivätkä sido hankintayksikköä toteuttamaan suunnitteilla olevaa hankintaa niiden mukaisesti. Tietopyyntö ei sido Jyväskylän kaupunkia eikä hankinnasta kiinnostuneita markkinatoimijoita hankintaan. Tietopyynnön tarkoituksena on kartoittaa markkinatoimijoita ja näiden näkemyksiä Jyväskylän kaupungin hankinnan mahdollisesta toteuttamisesta. Alustavan suunnitelman mukaan Jyväskylän kaupunki kilpailuttaa \"Puitejärjestelyn liikuntasalien nostolaitteiden tarkastus- ja korjauspalveluista\" -hankinnan myöhemmin julkaistavalla tarjouspyynnöllä. Tällä ilmoituksella Jyväskylän kaupunki hakee hankinnasta kiinnostuneita toimijoita ilmoittautumaan hankinnan valmistelun osana toteutettaviin teknisiin vuoropuhelutilaisuuksiin. Alustavan suunnitelman mukaan teknisessä vuoropuhelussa on tarkoitus keskustella kilpailutettavan kokonaisuuden hinnoittelusta sekä laadullisista vaatimuksista. Hankintayksikkö lähettää ennakkomateriaalin tekniseen vuoropuheluun osallistuville toimijoille noin viikkoa aiemmin, jotta toimijat voivat valmistautua vuoropuhelussa käsiteltäviin kysymyksiin. Myös markkinatoimijoilla on mahdollisuus esittää kysymyksiä valmisteltavasta hankinnasta hankintayksikölle. Hankintayksikkö pyrkii vastamaan markkinatoimijoiden esittämiin kysymyksiin vuoropuhelun aikana. Tavoitteena on, että hankintayksikkö voi valmistella hankinnasta lopullisen tarjouspyynnön vuoropuheluiden jälkeen. Hankintayksikkö kutsuu ilmoittautuneiden joukosta enintään 2 (kpl) markkinatoimijaa esittäytymään ja keskustelemaan yksitellen valmisteilla olevasta hankinnasta. Mikäli ilmoittautuneita on enemmän, tekninen vuoropuhelu käydään muiden kanssa tarvittaessa sähköpostikyselyn muodossa. Ilmoittautumiset tekniseen vuoropuheluun ja kuvaukset toiminnasta pyydetään lähettämään sähköpostitse osoitteeseen tuomo.kiiski@jyvaskyla.fi 20.09.2026 klo 23.59 mennessä. Teknisten vuoropuheluiden ja hankinnan alustava aikataulu: Viimeinen ajankohta ilmoittautua mukaan tekniseen vuoropuheluun 20.09.2026 klo 23.59 mennessä. Markkinatoimijan tulee esittää kysymyksensä tietopyynnön kohteena olevasta hankinnasta hankintayksikölle viimeistään 14.09.2026 klo 23.59 mennessä. Hankintayksikkö toimittaa ennakkoaineiston tekniseen vuoropuheluun osallistuville 21.09.2026. Teknisen vuoropuhelun 1. neuvottelupäivä 25.9 (klo 08-15 välisenä aikana),','Jyväskylän kaupunki','ANY',5,15,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056418','[\"71000000\"]','[\"jyväskylän\", \"hankinnasta\", \"hankintayksikkö\", \"hankinnan\", \"kaupunki\", \"tekniseen\", \"vuoropuheluun\", \"liikuntasalien\", \"nostolaitteiden\", \"tarkastus\", \"mukaan\", \"mennessä\", \"tipa\", \"markkinavuoropuhelu\", \"puitejärjestely\", \"korjauspalvelusta\", \"eikä\", \"tietopyyntö\", \"hankintaa\", \"sido\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/jyvaskyla?id=626909&tpk=b752b3af-2083-47e1-9fd8-5fb38101a01e\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056418\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56418\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"TIPA / Markkinavuoropuhelu: Puitejärjestely liikuntasalien nostolaitteiden tarkastus- ja korjauspalvelusta\", \"titleSv\": \"\", \"cpvCodes\": \"71000000\", \"currency\": null, \"deadline\": \"2026-09-20T20:59:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Tämä ei ole hankintailmoitus eikä tarjouspyyntö vaan tietopyyntö ja kutsu markkinavuoropuheluun. Ilmoituksessa mainitut hankintamenettelyä, määräaikoja, valintaperustetta, osatarjousten ja vaihtoehtoisten tarjousten hyväksymistä sekä muut hankintaa koskevat tiedot ovat alustavia eivätkä sido hankintayksikköä toteuttamaan suunnitteilla olevaa hankintaa niiden mukaisesti. Tietopyyntö ei sido Jyväskylän kaupunkia eikä hankinnasta kiinnostuneita markkinatoimijoita hankintaan. Tietopyynnön tarkoituksena on kartoittaa markkinatoimijoita ja näiden näkemyksiä Jyväskylän kaupungin hankinnan mahdollisesta toteuttamisesta.\\n\\nAlustavan suunnitelman mukaan Jyväskylän kaupunki kilpailuttaa \\\"Puitejärjestelyn liikuntasalien nostolaitteiden tarkastus- ja korjauspalveluista\\\" -hankinnan myöhemmin julkaistavalla tarjouspyynnöllä.\\n\\nTällä ilmoituksella Jyväskylän kaupunki hakee hankinnasta kiinnostuneita toimijoita ilmoittautumaan hankinnan valmistelun osana toteutettaviin teknisiin vuoropuhelutilaisuuksiin. \\n\\nAlustavan suunnitelman mukaan teknisessä vuoropuhelussa on tarkoitus keskustella kilpailutettavan kokonaisuuden hinnoittelusta sekä laadullisista vaatimuksista. Hankintayksikkö lähettää ennakkomateriaalin tekniseen vuoropuheluun osallistuville toimijoille noin viikkoa aiemmin, jotta toimijat voivat valmistautua vuoropuhelussa käsiteltäviin kysymyksiin. Myös markkinatoimijoilla on mahdollisuus esittää kysymyksiä valmisteltavasta hankinnasta hankintayksikölle. Hankintayksikkö pyrkii vastamaan markkinatoimijoiden esittämiin kysymyksiin vuoropuhelun aikana. Tavoitteena on, että hankintayksikkö voi valmistella hankinnasta lopullisen tarjouspyynnön vuoropuheluiden jälkeen.\\n\\nHankintayksikkö kutsuu ilmoittautuneiden joukosta enintään 2 (kpl) markkinatoimijaa esittäytymään ja keskustelemaan yksitellen valmisteilla olevasta hankinnasta. Mikäli ilmoittautuneita on enemmän, tekninen vuoropuhelu käydään muiden kanssa tarvittaessa sähköpostikyselyn muodossa. \\n\\nIlmoittautumiset tekniseen vuoropuheluun ja kuvaukset toiminnasta pyydetään lähettämään sähköpostitse osoitteeseen tuomo.kiiski@jyvaskyla.fi 20.09.2026 klo 23.59 mennessä.\\n\\nTeknisten vuoropuheluiden ja hankinnan alustava aikataulu:\\n\\nViimeinen ajankohta ilmoittautua mukaan tekniseen vuoropuheluun 20.09.2026 klo 23.59 mennessä.\\n\\nMarkkinatoimijan tulee esittää kysymyksensä tietopyynnön kohteena olevasta hankinnasta hankintayksikölle viimeistään 14.09.2026 klo 23.59 mennessä.\\n\\nHankintayksikkö toimittaa ennakkoaineiston tekniseen vuoropuheluun osallistuville 21.09.2026.\\n\\nTeknisen vuoropuhelun 1. neuvottelupäivä 25.9 (klo 08-15 välisenä aikana)\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-09-20T20:59:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"procurementTypeCode\": \"services supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": null, \"lotResultTotalAmount\": null, \"justWorkingConditions\": null, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": null, \"includesFrameworkAgreement\": null, \"smeParticipationConsidered\": null, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": null, \"tendersFromMicroTenderersCount\": 